TURATH_CHUNK(55,[{"num":11000,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي رُكُوعِهِ وَسُجُودِهِ :  سُبُّوحٌ قُدُّوس ربُ الْمَلَائِكَةِ وَالرُّوحِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (487) عن أبي بكر بن أبي شيبة، ثنا محمد بن بِشْر العبدي، حدثنا سعيد بن أبي عروبة، عن قتادة، عن مطرِفّ بن عبدالله بن الشخّير، أن عائشة نَبَّأته فذكرتِ الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (487).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ would say while bowing and prostrating: “The Perfectly Glorious, the Perfectly Holy, Lord of the angels and the Spirit.”"]}},"tuhfa":{},"full":1,"rep":[2124],"tks":"صحيح: رواه مسلم (487)."},{"num":11001,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ أَنَّهُ صَلَّى مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ   فَكَانَ يَقُولُ فِي رُكُوعِهِ.","سُبْحَانَ رَبِّيَ الْعَظِيمِ وَفِي سُجُودِهِ: سُبْحَانَ رَبِّيَ الْأَعْلَى وَمَا مَرَّ بِآيَةِ رَحْمَةٍ إِلَّا وَقَفَ عِنْدَهَا، فَسَأَلَ، وَلَا بِآيَةِ عَذَابٍ إِلَّا وَقَفَ عِنْدَهَا فَتَعَوَّذَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (772) من طريق الأعمش، عن سعد بن عبيدة، عن المستورد بن الأحنف، عن صِلة بن زفر، عن حذيفة فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (772).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Ḥudhayfah narrated: He prayed with the Prophet ﷺ, who would say while bowing: “Glory be to my Lord, the Magnificent.” While prostrating, he would say: “Glory be to my Lord, the Most High.” Whenever he passed a verse mentioning mercy, he would pause and ask Allah for it. Whenever he passed a verse mentioning punishment, he would pause and seek refuge from it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (772)."},{"num":11002,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ يَقُولُ فِي سُجُودِهِ: اللَّهُمَّ اغْفِرْ لِي ذَنْبِي كُلَّهُ: دِقَّهُ وَجِلَّهُ، وَأَوَّلَهُ وَآخِرَهُ، وَعَلَانِيَتَهُ وَسِرَّهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (483) من طريق سمى مولى أبي بكر، عن أبي صالح، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (483).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ would say while prostrating: “O Allah, forgive all of my sins: the minor and the major, the first and the last, the public and the secret.”"]}},"tuhfa":{},"full":1,"rep":[2127],"tks":"صحيح: رواه مسلم (483)."},{"num":11003,"demo":false,"sanad":"","matn":["عَنْ علِّي بن أَبِي طَالِبٍ، عَنْ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي حَدِيثِ طَوِيلٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِذَا رَكَعَ: اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمعِي وبَصْرِي، ومُخِّي وعَظْمِي وَعَصَبِي. وَإِذَا رَفَعَ قَالَ: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ مِلْءَ السموات وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا بَيْنَهُمَا وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ وَإِذَا سَجَدَ يَقُولُ: اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، سَجَدَ وَجْهِي لِلذِي خَلَقَهُ، وصوَّره، وشقَّ سَمْعَه، وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (771: 201) عن محمد بن أبي بكر المقدمي، حدثنا يوسف الماجشون، حدثني أبي، عن عبد الرحمن الأعرج، عن عبيدالله بن أبي رافع، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (771/201).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿAlī narrated in a lengthy hadith that when the Prophet ﷺ bowed, he would say: “O Allah, for You I have bowed, in You I have believed, and to You I have submitted. My hearing, my sight, my mind, my bones, and my nerves have humbled themselves before You.” When he raised his head, he would say: “O Allah, our Lord, all praise belongs to You—enough to fill the heavens, enough to fill the earth, enough to fill what lies between them, and enough to fill whatever else You will.” When he prostrated, he would say: “O Allah, for You I have prostrated, in You I have believed, and to You I have submitted. My face has prostrated before the One who created and fashioned it and opened its hearing and sight. Blessed is Allah, the Best of creators.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (771: 201)."},{"num":11004,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ الأَشْجَعِيِّ، قَالَ: قُمْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَيْلَةً، فَقَامَ فَقَرَأَ سُورَةَ الْبَقَرَةِ، لاَ يَمُرُّ بِآيَةِ رَحْمَةٍ إِلاَّ وَقَفَ فَسَأَلَ، وَلاَ يَمُرُّ بِآيَةِ عَذَابٍ إِلاَّ وَقَفَ فَتَعَوَّذَ، - قَالَ: - ثُمَّ رَكَعَ بِقَدْرِ قِيَامِهِ يَقُولُ فِي رُكُوعِهِ: سُبْحَانَ ذِي الْجَبَرُوتِ وَالْمَلَكُوتِ وَالْكِبْرِيَاءِ وَالْعَظَمَةِ. ثُمَّ سَجَدَ بِقَدْرِ قِيَامِهِ، ثُمَّ قَالَ فِي سُجُودِهِ مِثْلَ ذَلِكَ، - ثُمَّ قَامَ فَقَرَأَ بِآلِ عِمْرَانَ، ثُمَّ قَرَأَ سُورَةً سُورَةً."],"takhrij":"حسن: رواه أبو داود (873)، والنسائي (1132) والترمذي في الشمائل (306) كلهم من طريق معاوية بن صالح، عن عمرو بن قيس الكندي، يقول: سمعت عاصم بن حميد، يقول سمعت عوف بن مالك يقول: قمتُ مع النبيّ صلى الله عليه وسلم ليلة فذكر الحديث.","grade":"حسن","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (873), al-Nasā’ī (1132), and al-Tirmidhī in al-Shamā’il (306).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["ʿAwf ibn Mālik al-Ashjaʿī narrated: I stood in prayer with the Messenger of Allah ﷺ one night. He stood and recited Sūrat al-Baqarah. Whenever he passed a verse of mercy, he paused and asked Allah for it. Whenever he passed a verse of punishment, he paused and sought refuge from it. He then bowed for a length of time similar to his standing, saying: “Glory be to the Possessor of absolute might, dominion, greatness, and majesty.” He then prostrated for a length of time similar to his standing and said the same words in his prostration. He then stood and recited Sūrat Āl ʿImrān, and afterward continued reciting one sūrah after another."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2129,13159],"tks":"حسن: رواه أبو داود (873)، والنسائي (1132)، والترمذي في الشمائل (306)."},{"num":11005,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَكَعَ قَالَ: اللَّهُمَّ لَكَ رَكَعْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، وَعَلَيْكَ تَوَكَّلْتُ، أَنْتَ رَبِّي، خَشَعَ سَمْعِي وَبَصَرِي وَدَمِي وَلَحْمِي وَعَظْمِي وَعَصَبِي لِلَّهِ رَبِّ الْعَالَمِينَ."],"takhrij":"صحيح: رواه النسائي (1051) عن يحيى بن عثمان الحمصي، حدثنا أبو حيوة، حدثنا شُعيب، عن محمد بن المنكدر، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1051).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that when the Prophet ﷺ bowed, he would say: “O Allah, for You I have bowed, in You I have believed, to You I have submitted, and upon You I have relied. You are my Lord. My hearing, my sight, my blood, my flesh, my bones, and my nerves have humbled themselves before Allah, Lord of the worlds.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2131],"tks":"صحيح: رواه النسائي (1051)."},{"num":11006,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي سُجُودِهِ: اللَّهُمَّ لَكَ سَجَدْتُ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، وَأَنْتَ رَبِّي، سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ وَصَوَّرَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ، تَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ."],"takhrij":"صحيح: رواه النسائي (1127) عن يحيى بن عثمان قال: أخبرنا أبو حيوة، قال: حدثنا شعيب بن أبي حمزة، عن محمد بن المنكدر، عن جابر بن عبدالله، فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1127).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that the Prophet ﷺ would say while prostrating: “O Allah, for You I have prostrated, in You I have believed, and to You I have submitted. You are my Lord. My face has prostrated before the One who created and fashioned it and opened its hearing and sight. Blessed is Allah, the Best of creators.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2130],"tks":"صحيح: رواه النسائي (1127)."},{"num":11007,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: بِتُّ عِنْدَ خَالَتِي مَيْمُونَةَ بِنْتِ الْحَارِثِ، وَبَاتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَهَا فَرَأَيْتُهُ قَامَ لِحَاجَتِهِ، فَأَتَى الْقِرْبَةَ فَحَلَّ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا بَيْنَ الْوُضُوءَيْنِ ثُمَّ أَتَى فِرَاشَهُ فَنَامَ، ثُمَّ قَامَ قَوْمَةً أُخْرَى، فَأَتَى الْقِرْبَةَ فَحَلَّ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا هُوَ الْوُضُوءُ، ثُمَّ قَامَ يُصَلِّي وَكَانَ يَقُولُ فِي سُجُودِهِ: اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَاجْعَلْ فِي سَمْعِي نُورًا، وَاجْعَلْ فِي بَصَرِي نُورًا، وَاجْعَلْ مِنْ تَحْتِي نُورًا، وَاجْعَلْ مِنْ فَوْقِي نُورًا، وَعَنْ يَمِينِي نُورًا وَعَنْ يَسَارِي نُورًا، وَاجْعَلْ أَمَامِي نُورًا، وَاجْعَلْ خَلْفِي نُورًا، وَأَعْظِمْ لِي نُورًا. ثُمَّ نَامَ حَتَّى نَفَخَ، فَأَتَاهُ بِلاَلٌ فَأَيْقَظَهُ لِلصَّلاَةِ."],"takhrij":"صحيح: رواه النسائي (1120) عن هنَّاد بن السري، عن أبي الأحوص، عن سعيد بن مسروق، عن سلمة بن كُهيل، عن رِشْدين -وهو كريب مولى ابن عباس، عن ابن عباس فذكر الحديث، ونص النسائي أن هذا الدعاء كان يدعو به النبي صلى الله عليه وسلم في السجود.","grade":"صحيح","chapter_ar":"باب ما يقال في الركوع والسجود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1120).","chapter_en":"What Should Be Said While Bowing and Prostrating","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās narrated: I spent the night at the home of my maternal aunt, Maymūnah bint al-Ḥārith, while the Messenger of Allah ﷺ was staying with her. I saw him rise to relieve himself. He went to the water-skin, loosened its strap, and performed a moderate ablution. He then returned to his bed and slept. He later rose again, went to the water-skin, loosened its strap, performed a complete ablution, and stood to pray. While prostrating, he would say: “O Allah, place light within my heart, place light within my hearing, and place light within my sight. Place light beneath me and light above me, light to my right and light to my left, light before me and light behind me, and magnify light for me.” He then slept until the sound of his breathing could be heard. Bilāl came and awakened him for the prayer."]},"buhuth":{"en":["The Prophet ﷺ used to recite this supplication at different times, including while prostrating, as in this narration, while going to the mosque, and during the night prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2135],"tks":"صحيح: رواه النسائي (1120)."},{"num":11008,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ وَالْأَرْضِ، وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، أَحَقُّ مَا قَالَ الْعَبْدُ، وَكُلُّنَا لَكَ عَبْدٌ. اللَّهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"صحيح: رواه مسلم في الصلاة (477) عن عبدالله بن عبدالرحمن الدارمي، أخبرنا مروان بن محمد الدمشقي، حدثنا سعيد بن عبد العزيز، عن عطية بن قيس، عن قَزْعة، عن أبي سعيد الخدري فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (477).","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: When the Messenger of Allah ﷺ raised his head from bowing, he would say: “Our Lord, all praise belongs to You, enough to fill the heavens and the earth and whatever else You will beyond them. You are worthy of all praise and majesty. This is the truest statement a servant can make, and all of us are Your servants. O Allah, none can withhold what You give, none can give what You withhold, and no person’s wealth or worldly fortune can benefit him against You.”"]}},"tuhfa":{},"full":1,"rep":[2067,13129],"tks":"صحيح: رواه مسلم (477)."},{"num":11009,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَُ السَّمَاوَاتِ وَمِلْءَُ الْأَرْضِ وَمَا بَيْنَهُمَا، وَمِلْءَُ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ، أَهْلَ الثَّنَاءِ وَالْمَجْدِ، لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ. وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"صحيح: رواه مسلم في الصلاة (478) عن أبي بكر بن أبي شيبة، حدثنا هُشيم بن بَشير، أخبرنا هشامُ بن حسَّان، عن قيس بن سعد، عن عطاء، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (478).","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbās narrated: When the Prophet ﷺ raised his head from bowing, he would say: “O Allah, our Lord, all praise belongs to You, enough to fill the heavens, the earth, what lies between them, and whatever else You will beyond them. You are worthy of all praise and majesty. None can withhold what You give, none can give what You withhold, and no person’s wealth or worldly fortune can benefit him against You.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (478)."},{"num":11010,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي أَوْفَى قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ ظَهْرَهُ مِنَ الرُّكُوعِ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، اللَّهُمَّ رَبَّنَا لَكَ الْحَمْدُ، مِلْءَ السَّمَاوَاتِ وَمِلْءَ الْأَرْضِ وَمِلْءَ مَا شِئْتَ مِنْ شَيْءٍ بَعْدُ.","وفي رواية: اللَّهُمَّ لَكَ الْحَمْدُ، مِلْءَُ السَّمَاءِ وَمِلْءَُ الْأَرْضِ، وَمِلْءَُ مَا شِئْتَ مِنْ شَيْءٍ بعدُ.اللهم طَهِّرْنِي بِالثَّلْجِ وَالْبَرَدِ وَالْمَاءِ الْبَارِدِ، اللَّهُمَّ طَهِّرْنِي مِنَ الذُّنُوبِ وَالْخَطَايَا كَمَا يُنَقَّى الثَّوْبُ الْأَبْيَضُ مِنَ الْوَسَخِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (476) من طريق عن عبيد بن الحسن، عن عبد الله بن أبي أوفى فذكره باللفظ الأول. ورواه (476: 204) من طريق مَجْزأة بن زاهر، عن عبدالله بن أبي أوفى، فذكره باللفظ الثاني.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (476) with the first wording, and by Muslim (476/204) with the second wording.","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Ibn Abī Awfā narrated: When the Messenger of Allah ﷺ raised his back from bowing, he would say: “Allah hears the one who praises Him. O Allah, our Lord, all praise belongs to You, enough to fill the heavens, enough to fill the earth, and enough to fill whatever else You will.” Another narration states: “O Allah, all praise belongs to You, enough to fill the heaven, enough to fill the earth, and enough to fill whatever else You will. O Allah, purify me with snow, hail, and cold water. O Allah, purify me from sins and misdeeds as a white garment is cleansed of dirt.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (476) باللفظ الأول، ورواه (476/204) باللفظ الثاني."},{"num":11011,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّهُ سَمِعَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: رَبَّنَا وَلَكَ الْحَمْدُ."],"takhrij":"صحيح: رواه أحمد (6346) عن عبدالرزاق -وهو في المصنف (2911)، حدثنا معمر، عن الزهري، عن سالم، عن ابن عمر فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (6346) through ʿAbd al-Razzāq, and it is also found in al-Muṣannaf (2911).","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated that he heard the Messenger of Allah ﷺ say, when he raised his head from bowing: “Our Lord, and all praise belongs to You.”"]}},"tuhfa":{},"full":1,"rep":[2070],"tks":"صحيح: رواه أحمد (6346)، عن عبد الرزاق، وهو في المصنف (2911)."},{"num":11012,"demo":false,"sanad":"","matn":["عن علي بن أبي طالب، عن النبي صلى الله عليه وسلم في حديث طويل:","وَإِذَا رَكَعَ قَالَ: اللَّهُمَّ لَكَ رَكَعْتَ، وَبِكَ آمَنْتُ، وَلَكَ أَسْلَمْتُ، خَشَعَ لَكَ سَمْعِي وَبَصْرِي، وَمُخِّي وَعَظْمِي وَعَصَبِي.","وإذا رفع قال: اللهم ربنا لك الحمدُ مِلأَ السماوات ومِلأَ الأرضِ ومِلأَ ما بينهما، ومِلأَ ما شئت من شيء بعدُ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (771: 201) عن محمد بن أبي بكر المقدمي، ثنا يوسف الماجشون، حدثني أبي، عن عبدالرحمن الأعرج، عن","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (771/201).","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated in a lengthy hadith: When the Prophet ﷺ bowed, he would say: “O Allah, for You I have bowed, in You I have believed, and to You I have submitted. My hearing, my sight, my mind, my bones, and my nerves have humbled themselves before You.” When he raised his head, he would say: “O Allah, our Lord, all praise belongs to You, enough to fill the heavens, enough to fill the earth, enough to fill what lies between them, and enough to fill whatever else You will.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (771: 201)."},{"num":11013,"demo":false,"sanad":"","matn":["عَنْ رِفَاعَةَ بْنِ رَافِعٍ الزُّرَقِيِّ، قَالَ: كُنَّا يَوْمًا نُصَلِّي وَرَاءَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا رَفَعَ رَأْسَهُ مِنَ الرَّكْعَةِ قَالَ: سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ. قَالَ رَجُلٌ وَرَاءَهُ: رَبَّنَا وَلَكَ الْحَمْدُ، حَمْدًا كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، فَلَمَّا انْصَرَفَ قَالَ: مَنِ الْمُتَكَلِّمُ. قَالَ أَنَا. قَالَ: رَأَيْتُ بِضْعَةً وَثَلاَثِينَ مَلَكًا يَبْتَدِرُونَهَا، أَيُّهُمْ يَكْتُبُهَا أَوَّلُ."],"takhrij":"صحيح: رواه مالك في القرآن (25) عن نُعيم بن عبدالله المجمر، عن علي بن يحيى الزرقي، عن أبيه، عن رفاعة بن رافع فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (25) and al-Bukhārī (799).","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Rifāʿah ibn Rāfiʿ al-Zuraqī narrated: One day, we were praying behind the Messenger of Allah ﷺ. When he raised his head from bowing, he said: “Allah hears the one who praises Him.” A man behind him said: “Our Lord, and all praise belongs to You—abundant, pure, and blessed praise.” When the Prophet ﷺ completed the prayer, he asked: “Who spoke those words just now?” The man replied: “I did.” The Prophet ﷺ said: “I saw more than thirty angels hastening toward them, each seeking to be the first to record them.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (25)، والبخاري (799)."},{"num":11014,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا رَفَعَ رَأْسَهُ مِنَ الرُّكُوعِ قَالَ: اللَّهُمَّ رَبَّنَا وَلَكَ الْحَمْدُ."],"takhrij":"صحيح: رواه النسائي (1060) عن إسحاق بن إبراهيم، عن عبد الرزاق -وهو في المصنف (2912)-، عن معمر، عن الزهري، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكر الحديث. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رفع رأسه من الركوع","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1060) and ʿAbd al-Razzāq in al-Muṣannaf (2912).","chapter_en":"What One Should Say after Raising the Head from Bowing","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated: When the Messenger of Allah ﷺ raised his head from bowing, he would say: “O Allah, our Lord, and all praise belongs to You.”"]}},"tuhfa":{},"full":1,"rep":[2071],"tks":"صحيح: رواه النسائي (1060)، وعبد الرزاق، وهو في المصنف (2912)."},{"num":11015,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ بَيْنَ السَّجْدَتَيْنِ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَعَافِنِي، وَاهْدِنِي، وَارْزُقْنِي."],"takhrij":"حسن: رواه أبو داود (850)، والترمذي (284)، وابن ماجه (898) كلهم من طريق كامل أبي العلاء، حدثني حبيب بن ثابت، عن سعيد بن جُبير، عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما يقال بين السجدتين","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (850), al-Tirmidhī (284), and Ibn Mājah (898). The wording cited first is that of Abū Dāwūd.","chapter_en":"What Should Be Said between the Two Prostrations","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ would say between the two prostrations: “O Allah, forgive me, have mercy upon me, grant me well-being, guide me, and provide for me.”"]},"buhuth":{"en":["The wording of Ibn Mājah states:","The Messenger of Allah ﷺ would say between the two prostrations during the night prayer:","“My Lord, forgive me, have mercy upon me, mend my condition, provide for me, and raise me in rank.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2138],"tks":"حسن: رواه أبو داود (850)، والترمذي (284)، وابن ماجه (898). واللفظ لأبي داود."},{"num":11016,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ بَيْنَ السَّجْدَتَيْنِ: رَبِّ اغْفِرْ لِي، رَبِّ اغْفِرْ لِي."],"takhrij":"حسن: رواه النسائي (1665)، وابن ماجه (897) وصحّحه الحاكم (1/271) كلهم من طريق العلاء بن المسيب، عن عمرو بن مرة، عن طلحة بن يزيد الأنصاري، عن حذيفة فذكره.وسياق النسائي أطول.","grade":"حسن","chapter_ar":"باب ما يقال بين السجدتين","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1665) and Ibn Mājah (897), and authenticated by al-Ḥākim (1/271).","chapter_en":"What Should Be Said between the Two Prostrations","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":7,"content":{"translation":{"en":["Ḥudhayfah narrated: The Prophet ﷺ would say between the two prostrations: “My Lord, forgive me. My Lord, forgive me.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2137],"tks":"حسن: رواه النسائي (1665)، وابن ماجه (897)، وصححه الحاكم (1/271)."},{"num":11017,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ:  كُنَّا نَقُولُ فِي الصَّلَاةِ خَلْفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: السَّلَامُ عَلَى اللَّهِ، السَّلَامُ عَلَى فُلَانٍ، فَقَالَ لَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ: إِنَّ اللَّهَ هُوَ السَّلَامُ، فَإِذَا قَعَدَ أَحَدُكُمْ فِي الصَّلَاةِ، فَلْيَقُلِ: التَّحِيَّاتُ لِلهِ، وَالصَّلَوَاتُ وَالطَّيِّبَاتُ. السَّلَامُ عَلَيْكَ، أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. السَّلَامُ عَلَيْنَا، وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، فَإِذَا قَالَهَا أَصَابَتْ كُلَّ عَبْدٍ لِلهِ، صَالِحٍ فِي السَّمَاءِ وَالْأَرْضِ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ. ثُمَّ يَتَخَيَّرُ مِنَ الْمَسْأَلَةِ مَا شَاءَ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6328)، ومسلم في الصلاة (402) كلاهما عن عثمان بن أبي شيبة، عن جرير، عن منصور، عن أبي وائل، عن عبد الله بن مسعود فذكره.واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"باب ذكر ما ورد من صيغ التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6328) and Muslim (402). The wording cited here is that of Muslim.","chapter_en":"Forms of the Tashahhud That Have Been Narrated","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: While praying behind the Messenger of Allah ﷺ, we used to say: “Peace be upon Allah, and peace be upon so-and-so.” One day, the Messenger of Allah ﷺ said to us: “Indeed, Allah Himself is al-Salām. Therefore, when one of you sits in prayer, let him say: ‘All greetings, prayers, and pure words belong to Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah.’ When he says this, it reaches every righteous servant of Allah in the heavens and the earth. Then let him say: ‘I testify that there is no deity worthy of worship except Allah, and I testify that Muḥammad is His servant and Messenger.’ After that, he may choose whatever supplication he wishes.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6328)، ومسلم (402)، واللفظ لمسلم."},{"num":11018,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّهُ قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا التَّشَهُّدَ كَمَا يُعَلِّمُنَا السُّورَةَ مِنَ الْقُرْآنِ، فَكَانَ يَقُولُ: التَّحِيَّاتُ الْمُبَارَكَاتُ، الصَّلَوَاتُ الطَّيِّبَاتُ لِلهِ. السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ. أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا رَسُولُ اللَّهِ."],"takhrij":"صحيح: رواه مسلم في الصلاة (403) عن قتيبة بن سعيد، حدثنا ليث (هو ابن سعد) عن أبي الزبير، عن سعيد بن جبير وعن طاوس، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ذكر ما ورد من صيغ التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (403).","chapter_en":"Forms of the Tashahhud That Have Been Narrated","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The Messenger of Allah ﷺ would teach us the tashahhud just as he would teach us a sūrah from the Qur’an. He would say: “All blessed greetings, prayers, and pure words belong to Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I testify that there is no deity worthy of worship except Allah, and I testify that Muḥammad is the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2163],"tks":"صحيح: رواه مسلم (403)."},{"num":11019,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَطَبَنَا فبيَّن لَنَا سنَّتنا، وَعَلَّمَنَا صَلَاتَنَا فَقَالَ: وَإِذَا كَانَ عِنْدَ الْقَعْدَةِ فَلْيَكُنْ مِنْ أوّل قَوْلِ أَحَدِكُمُ: التَّحِيَّاتُ الطَّيِّبَاتُ الصَّلَوَاتُ لِلهِ، السَّلَامُ عَلَيْكَ أيُّها النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه مسلم في الصلاة (404) من حديث حِطّان بن عبدالله الرقاشي قال: صليتُ مع أبي موسى الأشعري صلاة، ثم ذكر حديثا طويلاً فيه الجزء المذكور.","grade":"صحيح","chapter_ar":"باب ذكر ما ورد من صيغ التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (404).","chapter_en":"Forms of the Tashahhud That Have Been Narrated","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī narrated: The Messenger of Allah ﷺ delivered a sermon to us in which he clarified our Sunnah and taught us our prayer. He said: “When one of you reaches the sitting position, let the first words he says be: ‘All greetings, pure words, and prayers belong to Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I testify that there is no deity worthy of worship except Allah, and I testify that Muḥammad is His servant and Messenger.’”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (404)."},{"num":11020,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي التَّشَهُّدِ: التَّحِيَّاتُ لِلَّهِ، الصَّلَوَاتُ الطَّيِّبَاتُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. قَالَ قَالَ ابْنُ عُمَرَ زِدْتُ فِيهَا وَبَرَكَاتُهُ. السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ. قَالَ ابْنُ عُمَرَ زِدْتُ فِيهَا وَحْدَهُ لاَ شَرِيكَ لَهُ. وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه أبو داود (971) والدارقطني (1329) كلاهما من حديث نصر بن علي، حدثني أبي، حدثنا شعبة، عن أبي بشر، سمعتُ مجاهداً يحدث عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ذكر ما ورد من صيغ التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (971) and al-Dāraquṭnī (1/351).","chapter_en":"Forms of the Tashahhud That Have Been Narrated","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Ibn ʿUmar narrated the following form of the tashahhud from the Messenger of Allah ﷺ: “All greetings belong to Allah, as do the prayers and pure words. Peace be upon you, O Prophet, and the mercy of Allah and His blessings.” Ibn ʿUmar said: “I added the words: ‘and His blessings.’” The tashahhud continues: “Peace be upon us and upon the righteous servants of Allah. I testify that there is no deity worthy of worship except Allah.” Ibn ʿUmar said: “I added: ‘He alone, without partner.’” It concludes: “And I testify that Muḥammad is His servant and Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2165],"tks":"صحيح: رواه أبو داود (971)، والدارقطني (1329)."},{"num":11021,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن عبدٍ القاري أَنَّهُ سَمِعَ عُمَرَ بْنَ الْخَطَّابِ يعلِّم النَّاسَ التَّشَهُّدِ عَلَى الْمِنْبَرِ، فَيَقُولُ: قُولُوا: التَّحِيَّاتُ لِلَّهِ، الزَّاكِيَّاتُ لِلَّهِ، الطَّيِّبَاتُ لِلَّهِ، الصَّلَوَاتُ لِلَّهِ، السَّلَامُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلَامُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، أَشْهَدُ أَنْ لَا إِلَهَ إلاّ اللَّهُ، وَأَشْهَدُ أنّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ."],"takhrij":"صحيح: رواه مالك في الصلاة (57) عن ابن شهاب، عن عروة بن الزبير، عن عبدالرحمن بن عبد القاري، فذكره.","grade":"صحيح","chapter_ar":"باب ذكر ما ورد من صيغ التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (57), ʿAbd al-Razzāq (2/202), and al-Bayhaqī (2/144).","chapter_en":"Forms of the Tashahhud That Have Been Narrated","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAbd al-Qārī narrated that he heard ʿUmar ibn al-Khaṭṭāb teaching the people the tashahhud from the pulpit, saying: “Say: ‘All greetings belong to Allah, all pure and growing deeds belong to Allah, all pure words belong to Allah, and all prayers belong to Allah. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I testify that there is no deity worthy of worship except Allah, and I testify that Muḥammad is His servant and Messenger.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مالك (57)، وعبد الرزاق (3172)، والبيهقي (2838)."},{"num":11022,"demo":false,"sanad":"","matn":["عَنِ الْقَاسِمِ بْنِ مُحَمَّدٍ، أَنَّهُ أَخْبَرَهُ أَنَّ عَائِشَةَ زَوْجَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَتْ تَقُولُ إِذَا تَشَهَّدَتِ: التَّحِيَّاتُ الطَّيِّبَاتُ، الصَّلَوَاتُ الزَّاكِيَاتُ لِلَّهِ، أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، وَأَشْهَدُ أَنَّ مُحَمَّدًا عَبْدُ اللَّهِ وَرَسُولُهُ، السَّلاَمُ عَلَيْكَ أَيُّهَا النَّبِيُّ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ، السَّلاَمُ عَلَيْنَا وَعَلَى عِبَادِ اللَّهِ الصَّالِحِينَ، السَّلاَمُ عَلَيْكُمْ."],"takhrij":"صحيح: رواه مالك في الصلاة (59، 60) عن عبدالرحمن بن القاسم، ويحيى بن سعيد الأنصاري كلاهما عن القاسم بن محمد، قال (فذكر الحديث).","grade":"صحيح","chapter_ar":"باب ذكر ما ورد من صيغ التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (59, 60).","chapter_en":"Forms of the Tashahhud That Have Been Narrated","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":8,"content":{"translation":{"en":["Al-Qāsim ibn Muḥammad narrated that when ʿĀ’ishah, the wife of the Prophet ﷺ, recited the tashahhud, she would say: “All greetings and pure words belong to Allah, as do the pure prayers. I testify that there is no deity worthy of worship except Allah alone, without partner, and I testify that Muḥammad is His servant and Messenger. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. Peace be upon you all.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2167],"tks":"صحيح: رواه مالك (59، 60)."},{"num":11023,"demo":false,"sanad":"","matn":["عَنْ أَبِي مَسْعُودٍ الْأَنْصَارِيِّ أَنَّهُ قَالَ: أَتَانَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَجْلِسِ سَعْدِ بْنِ عُبَادَةَ: فَقَالَ لَهُ بَشِيرُ بْنُ سَعْدٍ: أَمَرَنَا اللهُ أَنْ نُصَلِّيَ عَلَيْكَ يَا رَسُولَ اللَّهِ، فَكَيْفَ نُصَلِّي عَلَيْكَ؟ قَالَ: فَسَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى تَمَنَّيْنَا أَنَّهُ لَمْ يَسْأَلْهُ ثُمَّ قَالَ: قُولُوا: اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ، كَمَا صلَّيت عَلَى إِبْرَاهِيمَ، وَبَارِكْ عَلَى مُحَمَّدٍ وَعَلَى آلِ مُحَمَّدٍ كَمَا بَارَكْتَ عَلَى آلِ إِبْرَاهِيمَ فِي الْعَالَمِينَ، إِنَّكَ حَمِيدٌ مَجِيدٌ، وَالسَّلَامُ كَمَا عَلِمْتُمْ."],"takhrij":"صحيح: رواه مالك في قصر الصلاة (67) عن نعيم بن عبدالله المُجْمِر، عن محمد بن عبدالله بن زيد، أنه أخبره عن أبي مسعود الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب الصلاة على النبي ﷺ في التشهد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (67) and Muslim (405).","chapter_en":"Sending Blessings upon the Prophet ﷺ during the Tashahhud","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":9,"content":{"translation":{"en":["Abū Masʿūd al-Anṣārī narrated: The Messenger of Allah ﷺ came to us while we were gathered in the assembly of Saʿd ibn ʿUbādah. Bashīr ibn Saʿd said to him: “Allah has commanded us to send blessings upon you, O Messenger of Allah. How should we send blessings upon you?” The Messenger of Allah ﷺ remained silent for so long that we wished he had not asked him. He then said: “Say: ‘O Allah, send blessings upon Muḥammad and the family of Muḥammad, as You sent blessings upon Abraham. Bless Muḥammad and the family of Muḥammad, as You blessed the family of Abraham among all the worlds. Indeed, You are Praiseworthy and Glorious.’ As for the greeting of peace, it is as you have already been taught.”"]},"buhuth":{"en":["Ibn Khuzaymah (711) and others added:","“How should we send blessings upon you when we do so during our prayer?”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10858],"tks":"صحيح: رواه مالك (67)، ومسلم (405)."},{"num":11024,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، زَوْجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخْبَرَتْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَدْعُو فِي الصَّلاَةِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ، وَأَعُوذُ بِكَ مِنْ فِتْنَةِ الْمَحْيَا وَفِتْنَةِ الْمَمَاتِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْمَأْثَمِ وَالْمَغْرَمِ. فَقَالَ لَهُ قَائِلٌ مَا أَكْثَرَ مَا تَسْتَعِيذُ مِنَ الْمَغْرَمِ فَقَالَ إِنَّ الرَّجُلَ إِذَا غَرِمَ حَدَّثَ فَكَذَبَ، وَوَعَدَ فَأَخْلَفَ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (832)، ومسلم في المساجد (589) كلاهما من طريق شُعيب، عن الزهري، قال: أخبرني عروة بن الزبير، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (832) and Muslim (589).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, narrated that the Prophet ﷺ would supplicate during the prayer: “O Allah, I seek refuge in You from the punishment of the grave. I seek refuge in You from the trial of the False Messiah. I seek refuge in You from the trials of life and death. O Allah, I seek refuge in You from sin and debt.” Someone asked him: “How frequently you seek refuge from debt, O Messenger of Allah!” He replied: “When a man falls into debt, he speaks and lies, and he makes promises and breaks them.”"]}},"tuhfa":{},"full":1,"rep":[2176],"tks":"متفق عليه: رواه البخاري (832)، ومسلم (589)."},{"num":11025,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: دَخَلَتْ عليَّ عَجُوزَانِ مِنْ عُجُز يَهُودِ الْمَدِينَةِ، فَقَالَتَا لِي: إِنَّ أَهْلَ الْقُبُورِ يُعَذَّبُونَ فِي قُبُورِهِمْ، فَكَذَّبْتُهُمَا، وَلَمْ أُنْعم أَنْ أُصَدِّقَهُمَا فَخَرَجَتَا.وَدَخَلَ عليَّ النبيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ لَهُ: يَا رَسُولَ اللَّهِ إِنَّ عَجُوزَيْنِ مِنْ عُجُز الْمَدِينَةِ دخلتا عليَّ، فزعمتا أَنْ أَهْلَ الْقُبُورِ يُعَذَّبُونَ فِي قُبُورِهِمْ فَقَالَ: صَدَقَتَا، إِنَّهُمْ يُعَذَّبُونَ عَذَابًا تَسْمَعُهُ الْبَهَائِمُ كُلُّهَا.","قالت: فما رأيتُ بعد في صلاة إلا تعوذ من عذاب القبر."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6366)، ومسلم في المساجد (586/125) كلاهما من طريق جرير، عن منصور، عن أبي وائل، عن مسروق، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6366) and Muslim (586/125).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah narrated: Two elderly Jewish women from Madinah entered upon me and said: “The inhabitants of the graves are punished in their graves.” I rejected their statement and was unwilling to believe them. They then left. The Prophet ﷺ entered upon me, and I said: “O Messenger of Allah, two elderly women from among the women of Madinah entered upon me and claimed that the inhabitants of the graves are punished in their graves.” He said: “They spoke the truth. They are punished with a punishment that all animals can hear.” ʿĀ’ishah said: “After that, I never saw him perform a prayer without seeking refuge from the punishment of the grave.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6366)، ومسلم (586/125)."},{"num":11026,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ، وَمِنْ عَذَابِ النَّارِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ فِتْنَةِ الْمَسِيحِ الدَّجَّالِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1377)، ومسلم في المساجد (588: 131) كلاهما من حديث هشام، عن يحيى، عن أبي سلمة، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1377) and Muslim (588/131).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated: The Prophet ﷺ would supplicate: “O Allah, I seek refuge in You from the punishment of the grave, from the punishment of the Fire, from the trials of life and death, and from the trial of the False Messiah.”"]}},"tuhfa":{},"full":1,"rep":[2180,11330],"tks":"متفق عليه: رواه البخاري (1377)، ومسلم (588: 131)."},{"num":11027,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا فَرَغَ أَحَدُكُمْ مِنَ التَّشَهُّدِ الْآخِرِ فَلْيَتَعَوَّذْ بِاللهِ مِنْ أَرْبَعٍ: مِنْ عَذَابِ جَهَنَّمَ، وَمِنْ عَذَابِ الْقَبْرِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ شَرِّ الْمَسِيحِ الدَّجَّالِ."],"takhrij":"صحيح: رواه مسلم في المساجد (588: 130) عن زهير بن حرب، حدثنا الوليد بن مسلم، حدثني الأوزاعي، حدثنا حسان بن عطية، حدثني محمد بن أبي عائشة، أنه سمع أبا هريرة يقول فذكره.وقد أكثر مسلم من ذكر طرقه وألفاظه.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (588/130).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you completes the final tashahhud, let him seek refuge in Allah from four things: the punishment of Hell, the punishment of the grave, the trials of life and death, and the evil of the False Messiah.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (588: 130)."},{"num":11028,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ أَبَا الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي صَلاَتِهِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ فِتْنَةِ الْقَبْرِ، وَمِنْ فِتْنَةِ الدَّجَّالِ، وَمِنْ فِتْنَةِ الْمَحْيَا وَالْمَمَاتِ، وَمِنْ حرّ جَهَنَّمَ."],"takhrij":"صحيح: رواه النسائي (5520) عن عمرو بن سواد، حدثنا ابن وهب، حدثنا عمرو بن الحارث (هو ابن يعقوب الأنصاري)، عن يزيد بن أبي حبيب، عن سليمان بن سنان المزني، أنه سمع أبا هريرة يقول فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (5520).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard Abū al-Qāsim ﷺ say during his prayer: “O Allah, I seek refuge in You from the trial of the grave, from the trial of the False Messiah, from the trials of life and death, and from the scorching heat of Hell.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي (5520)."},{"num":11029,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرٍ الصِّدِّيقِ رَضِيَ اللَّهُ عَنْهُ. أَنَّهُ قَالَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: عَلِّمْنِي دُعَاءً أَدْعُو بِهِ فِي صَلاَتِي. قَالَ: قُلِ: اللَّهُمَّ إِنِّي ظَلَمْتُ نَفْسِي ظُلْمًا كَثِيرًا، َلاَ يَغْفِرُ الذُّنُوبَ إِلاَّ أَنْتَ، فَاغْفِرْ لِي مَغْفِرَةً مِنْ عِنْدِكَ، وَارْحَمْنِي إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (834)، ومسلم في الذكر والدعاء (2705) كلاهما عن قتيبة بن سعيد، قال: حدثنا الليث، عن يزيد بن أبي حبيب، عن أبي الخير، عن عبدالله بن عمرو بن العاص، عن أبي بكر الصديق فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (834) and Muslim (2705).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Abū Bakr al-Ṣiddīq said to the Messenger of Allah ﷺ: “Teach me a supplication that I may recite during my prayer.” He said: “Say: ‘O Allah, I have greatly wronged myself, and none forgives sins except You. Therefore, grant me forgiveness from Yourself and have mercy upon me. Indeed, You are the All-Forgiving, the Most Merciful.’”"]}},"tuhfa":{},"full":1,"rep":[2183],"tks":"متفق عليه: رواه البخاري (834)، ومسلم (2705)."},{"num":11030,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ مِنْ آخِرِ مَا يَقُولُ بَيْنَ التَّشَهُّدِ وَالتَّسْلِيمِ: اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ لَا إِلَهَ إِلَّا أَنْتَ."],"takhrij":"صحيح: رواه مسلم في المسافرين (771) من طريق يوسف الماجسون، عن أبيه، عن عبدالرحمن الأعرج، عن عبيدالله بن أبي رافع، عن علي رضي الله عنه.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (771).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated in a lengthy hadith that the Prophet ﷺ would say between the tashahhud and the concluding greeting of peace: “O Allah, forgive me for what I have sent ahead and what I have left behind, what I have concealed and what I have made public, what I have committed excessively, and what You know better about me than I do. You are the One who brings forward, and You are the One who delays. There is no deity worthy of worship except You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (771)."},{"num":11031,"demo":false,"sanad":"","matn":["عَنْ فَرْوَةَ بْنِ نَوْفَلٍ، قَالَ: قُلْتُ لِعَائِشَةَ: حَدِّثِينِي بِشَىْءٍ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدْعُو بِهِ فِي صَلاَتِهِ. فَقَالَتْ نَعَمْ، كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ مَا عَمِلْتُ، وَمِنْ شَرِّ مَا لَمْ أَعْمَلْ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2716) عن يحيى بن يحيى وإسحاق بن إبراهيم واللفظ ليحيى قالا: أخبرنا جرير، عن منصور، عن هلال، عن فروة بن نوفل الأشجعي قال: سألت عائشة فذكر الحديث، ومسلم ساق لفظ يحيى، وليس في روايته أنه كان يدعو به في صلاته، وإنما ذكره إسحاق بن إبراهيم، وعنه رواه النسائي (1307) بالسند المذكور عند مسلم، والمتن الذي سقتُه منه.وكذا لم يرو أبو داود (1550) وابن ماجه (3839) من طريق إسحاق بن إبراهيم، فلم يذكرا أيضاً أن ذلك كان في الصلاة.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2716).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Farwah ibn Nawfal narrated: I said to ʿĀ’ishah: “Tell me of something with which the Messenger of Allah ﷺ used to supplicate during his prayer.” She replied: “Yes. The Messenger of Allah ﷺ used to say: ‘O Allah, I seek refuge in You from the evil of what I have done and from the evil of what I have not done.’”"]}},"tuhfa":{},"full":1,"rep":[2178],"tks":"صحيح: رواه مسلم (2716)."},{"num":11032,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي بَعْضِ صَلَاتِهِ: اللهُمَّ حَاسِبْنِي حِسَابًا يَسِيرًا فَلَمَّا انْصَرَفَ، قُلْتُ: يَا نَبِيَّ اللَّهِ، مَا الْحِسَابُ الْيَسِيرُ؟ قَالَ: أَنْ يَنْظُرَ فِي كِتَابِهِ، فَيَتَجَاوَزَ عَنْهُ، إِنَّهُ مَنْ نُوقِشَ الْحِسَابَ يَوْمَئِذٍ يَا عَائِشَةُ هَلَكَ، وَكُلُّ مَا يُصِيبُ الْمُؤْمِنَ، يُكَفِّرُ اللهُ عَزَّ وَجَلَّ بِهِ عَنْهُ، حَتَّى الشَّوْكَةُ تَشُوكُهُ."],"takhrij":"حسن: رواه أحمد (24215) ، وصحّحه ابن خزيمة (849) والحاكم (1/255، 57) كلهم من حديث إسماعيل، حدثنا محمد ابن إسحاق، قال: حدثني عبدالواحد بن حمزة بن عبدالله بن الزبير، عن عبَّاد بن عبدالله بن الزبير، عن عائشة فذكرت الحديث.وإسناده حسن من أجل محمد بن إسحاق.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (24215), and authenticated by Ibn Khuzaymah (849) and al-Ḥākim (1/57, 255).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿĀ’ishah narrated: I heard the Prophet ﷺ say during one of his prayers: “O Allah, call me to an easy account.” When he completed the prayer, I asked: “O Prophet of Allah, what is an easy account?” He replied: “It is that a person’s record is examined and he is then pardoned. Whoever is thoroughly questioned about his account on that Day, O ʿĀ’ishah, will be ruined. Everything that afflicts a believer is made an expiation for him by Allah, Mighty and Majestic, even a thorn that pricks him.”"]}},"tuhfa":{},"full":1,"rep":[2179,13697,16196],"tks":"حسن: رواه أحمد (24215)، وصححه ابن خزيمة (849)، والحاكم (1/57، 255)."},{"num":11033,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ: مَا تَقُولُ فِي الصَّلاَةِ. قَالَ: أَتَشَهَّدُ ثُمَّ أَسْأَلُ اللَّهَ الْجَنَّةَ، وَأَعُوذُ بِهِ مِنَ النَّارِ أَمَا وَاللَّهِ مَا أُحْسِنُ دَنْدَنَتَكَ وَلاَ دَنْدَنَةَ مُعَاذٍ. فَقَالَ حَوْلَهُمَا نُدَنْدِنُ."],"takhrij":"صحيح: رواه ابن ماجه (910، 3847)، وصحّحه ابن خزيمة (725)، وابن حبان (868) كلهم من طريق جرير بن عبد الحميد، عن الأعمش، عن أبي صالح، عن أبي هريرة فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (910, 3847), and authenticated by Ibn Khuzaymah (725) and Ibn Ḥibbān (868).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ asked a man: “What do you say during the prayer?” The man replied: “I recite the tashahhud, then I ask Allah for Paradise and seek refuge in Him from the Fire. By Allah, I am not skilled in the elaborate supplications that you and Muʿādh make.” The Prophet ﷺ said: “It is around these two matters that our supplications revolve.”"]}},"tuhfa":{},"full":1,"rep":[2181],"tks":"صحيح: رواه ابن ماجه (910، 3847)، وصححه ابن خزيمة (725)، وابن حبان (868)."},{"num":11034,"demo":false,"sanad":"","matn":["عَنْ مِحْجَن بن الأدْرَعِ قَالَ: دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَسْجِدَ، فَإِذَا هُوَ بِرَجُلٍ قَدْ قَضَى صَلاَتَهُ وَهُوَ يَتَشَهَّدُ وَهُوَ يَقُولُ: اللَّهُمَّ إِنِّي أَسْأَلُكَ يَا اللَّهُ الأَحَدُ الصَّمَدُ، الَّذِي لَمْ يَلِدْ وَلَمْ يُولَدْ وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ، أَنْ تَغْفِرَ لِي ذُنُوبِي، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ، قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ :قَدْ غُفِرَ لَهُ، قَدْ غُفِرَ لَهُ ثَلاَثًا."],"takhrij":"صحيح: رواه أبو داود (985)، والنسائي (1301)، وصحّحه ابن خزيمة (724)، والحاكم (985) كلهم من طريق عبدالوارث، حدثنا الحسين المعلم، عن عبدالله بن بريدة، عن حنظلة بن علي، أن محجن بن الأدْرع حدثه فذكر مثله.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (985) and al-Nasā’ī (1301), and authenticated by Ibn Khuzaymah (724) and al-Ḥākim (985).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Miḥjan ibn al-Adraʿ narrated: The Messenger of Allah ﷺ entered the mosque and found a man who had completed his prayer and was reciting the tashahhud. The man was saying: “O Allah, I ask You, O Allah, the One, the Self-Sufficient Master, who neither begets nor was born, and there is none comparable to Him, to forgive my sins. Indeed, You are the All-Forgiving, the Most Merciful.” The Messenger of Allah ﷺ said three times: “He has been forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (985)، والنسائي (1301)، وصححه ابن خزيمة (724)، والحاكم (985)."},{"num":11035,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحُصيب الأسلمي أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ سَمِعَ رَجُلاً يَقُولُ: اللَّهُمَّ إنّي أَسْأَلُكَ أَني أَشْهَدُ أَنَّكَ أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الأَحَدُ الصَّمَدُ الَّذِي لَمْ يَلِدْ، وَلَمْ يُولَدْ، وَلَمْ يَكُنْ لَهُ كُفُوًا أَحَدٌ.فَقَالَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ سَأَلْتَ اللَّهَ بِالاِسْمِ الَّذِي إِذَا سُئل بِهِ أَعْطَى، وَإِذَا دُعى بِهِ أَجَابَ."],"takhrij":"صحيح: رواه أبو داود (1493، 1494)، والترمذي (3475)، وابن ماجه (3857)، وصحّحه ابن حبان (891)، والحاكم (1858) كلهم من طريق مالك بن مغول، عن عبدالله بن بريدة، عن أبيه فذكر الحديث.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1493, 1494), al-Tirmidhī (3475), and Ibn Mājah (3857), and authenticated by Ibn Ḥibbān (891).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb al-Aslamī narrated: The Messenger of Allah ﷺ heard a man saying: “O Allah, I ask You by my testimony that You are Allah. There is no deity worthy of worship except You, the One, the Self-Sufficient Master, who neither begets nor was born, and there is none comparable to Him.” The Messenger of Allah ﷺ said: “You have asked Allah by the Name through which, when He is asked, He gives, and when He is called upon, He answers.”"]}},"tuhfa":{},"full":1,"rep":[2186,10899,10966],"tks":"صحيح: رواه أبو داود (1493، 1494)، والترمذي (3475)، وابن ماجه (3857)، وصححه ابن حبان (891)."},{"num":11036,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّهُ كَانَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا وَرَجُلٌ يُصَلِّي، ثُمَّ دَعَا: اللَّهُمَّ إِنِّي أَسْأَلُكَ بِأَنَّ لَكَ الْحَمْدَ، لاَ إِلَهَ إِلاَّ أَنْتَ الْمَنَّانُ، بَدِيعُ السَّمَوَاتِ وَالأَرْضِ، يَا ذَا الْجَلاَلِ وَالإِكْرَامِ، يَا حَىُّ يَا قَيُّومُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقَدْ دَعَا اللَّهَ بِاسْمِهِ الْعَظِيمِ الَّذِي إِذَا دُعِيَ بِهِ أَجَابَ، وَإِذَا سُئِلَ بِهِ أَعْطَى."],"takhrij":"حسن: رواه أبو داود (1495)، والنسائي (1300)، وصحّحه ابن حبان (893)، والحاكم (1856) كلهم من طريق خلف بن خليفة، عن حفص بن أخي أنس، عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1495) and al-Nasā’ī (1300), and authenticated by Ibn Ḥibbān (893) and al-Ḥākim (1856).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Anas narrated: I was sitting with the Messenger of Allah ﷺ while a man was praying. The man then supplicated: “O Allah, I ask You because all praise belongs to You. There is no deity worthy of worship except You, the Bestower of favors, Originator of the heavens and the earth, Possessor of majesty and honor, O Ever-Living, O Sustainer of all.” The Prophet ﷺ said: “He has called upon Allah by His magnificent Name through which, when He is called upon, He answers, and when He is asked, He gives.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[10901],"tks":"حسن: رواه أبو داود (1495)، والنسائي (1300)، وصححه ابن حبان (893)، والحاكم (1856)."},{"num":11037,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: جَاءَتْ أُمُّ سُلَيْمٍ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَتْ: يَا رَسُولَ اللَّهِ عَلِّمْنِي كَلِمَاتٍ أَدْعُو بِهِنَّ فِي صَلاَتِي. قَالَ سَبِّحِي اللَّهَ عَشْرًا، وَاحْمَدِيهِ عَشْرًا وَكَبِّرِيهِ عَشْرًا، ثُمَّ سَلِيهِ حَاجَتَكِ يَقُلْ نَعَمْ نَعَمْ."],"takhrij":"حسن: رواه النسائي (1299)، والترمذي (481) كلاهما من طريق عكرمة بن عمار، عن إسحاق بن عبدالله بن أبي طلحة، عن أنس فذكر مثله.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1299) and al-Tirmidhī (481).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Anas narrated: Umm Sulaym came to the Prophet ﷺ and said: “O Messenger of Allah, teach me some words with which I may supplicate during my prayer.” He said: “Glorify Allah ten times, praise Him ten times, magnify Him ten times, and then ask Him for your need. He will say: ‘Yes, yes.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2188],"tks":"حسن: رواه النسائي (1299)، والترمذي (481)."},{"num":11038,"demo":false,"sanad":"","matn":["عَنْ سلمى أم بني أَبِي رَافِعٍ أَنَّهَا قَالَتْ: يَا رَسُولَ اللَّهِ أَخْبِرْنِي بِكَلِمَاتٍ، وَلَا تُكْثِرْ عَلَيَّ، قَالَ: قَوْلِي: اللَّهُ أَكْبَرُ، اللَّهُ أَكْبَرُ، عَشْرَ مَرَّاتٍ يَقُولُ اللَّهُ عَزَّ وَجَلَّ: هَذَا لِي، وَقُولِي: سُبْحَانَ اللَّهِ، سُبْحَانَ اللَّهِ، عَشْرَ مَرَّاتٍ يَقُولُ اللَّهُ عَزَّ وَجَلَّ: هَذَا لِي، وَقُولِي: اللَّهُمَّ اغْفِرْ لِي، اللَّهُمَّ اغْفِرْ لِي، عَشْرَ مَرَّاتٍ، يَقُولُ اللَّهُ عَزَّ وَ جَلَّ قَدْ فَعَلْتُ ."],"takhrij":"حسن: رواه الطبراني في الكبير (24/302)، والدعاء (1731) من طريق محمد بن المثنى، حدثنا أبو بكر الحنفي (هو عبد الكبير بن عبد المجيد البصري)، ثنا بكير بن مسمار، عن زيد بن أسلم، عن سلمى أم بني أبي رافع فذكرته.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (24/302) and in al-Duʿāʾ (1731).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["Salmā, the mother of the children of Abū Rāfiʿ, narrated that she said: “O Messenger of Allah, teach me some words, but do not give me too many.” He said: “Say: ‘Allah is the Greatest, Allah is the Greatest,’ ten times. Allah, Mighty and Majestic, will say: ‘This is for Me.’ Say: ‘Glory be to Allah, glory be to Allah,’ ten times. Allah, Mighty and Majestic, will say: ‘This is for Me.’ Then say: ‘O Allah, forgive me. O Allah, forgive me,’ ten times. Allah, Mighty and Majestic, will say: ‘I have done so.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (24/302)، وفي الدعاء (1731)."},{"num":11039,"demo":false,"sanad":"","matn":["عَنْ عَمَّارِ بن يَاسِرٍ قَالَ: سَمِعْتُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي صلاته: اللَّهُمَّ بِعِلْمِكَ الغَيبَ، وَقُدْرَتِكَ عَلَى الخَلْقِ أحْيِنِي مَا علِمتَ الْحَيَاةَ خَيْرًا لِي، وَتَوَفَّنِي إِذَا علِمتَ الْوَفَاةَ خَيْرًا لِي، اللَّهُمَّ أَسْأَلُكَ خَشْيَتَكَ - يَعْنِي فِي الْغَيْبِ وَالشَّهَادَةِ-، وَأَسْأَلُكَ كَلِمَةَ الحقِّ فِي الرِّضا وَالْغَضَبِ، وَأَسْأَلُكَ القَصْدَ فِي الفَقْرِ وَالْغِنَى، وَأَسْأَلُكَ نَعِيمًا لاَ يَنْفَدُ، وَأَسْأَلُكَ قُرَّةَ عينٍ لاَ تَنْقَطِعُ، وَأَسْأَلُكَ الرِّضَا بَعْدَ الْقَضَاءِ، وَأَسْأَلُكَ بَرْدَ الْعَيْشِ بَعْدَ الْمَوْتِ، وَأَسْأَلُكَ لذَّةَ النَّظَرِ إِلَى وَجْهِكَ، وَالشَّوْقَ إِلَى لِقَائِكَ فِي غَيْرِ ضَرَّاء مُضِرَّةٍ، وَلاَ فِتْنَةٍ مُضِلَّةٍ، اللَّهُمَّ زَيِّنَا بِزِينَةِ الإِيمَانِ، وَاجْعَلْنَا هُداةً مُهْتَدِينَ."],"takhrij":"صحيح: رواه النسائي (1305)، وصحّحه ابن حبان (1971)، والحاكم (1923) كلهم من طريق حماد بن زيد، حدثنا عطاء بن السائب بن مالك، عن أبيه قال: صلى بنا عمار بن ياسر صلاة، فأوجز فيها، فقال له بعض القوم، لقد خفَّفتَ -أو أوجزتَ الصلاة.قال: ما عَلَيَّ ذلك، فقد دعوتُ فيها دعوات سمعتُهن من رسول الله صلى الله عليه وسلم، فلما قام، تبعه رجل من القوم، هو أبي (أي أبو عطاء) غير أنه كنى عن نفسه فسأله عن الدعاء، ثم جاء فأخبر به القوم، فذكر الدعاء.","grade":"صحيح","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1305), and authenticated by Ibn Ḥibbān (1971) and al-Ḥākim (1923).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿAmmār ibn Yāsir narrated: I heard the Messenger of Allah ﷺ say during his prayer: “O Allah, by Your knowledge of the unseen and Your power over creation, keep me alive for as long as You know that life is better for me, and cause me to die when You know that death is better for me. O Allah, I ask You for fear of You in private and in public. I ask You for the word of truth in times of contentment and anger. I ask You for moderation in poverty and wealth. I ask You for bliss that never ends and for a delight of the eyes that never ceases. I ask You for contentment after Your decree and for the coolness and comfort of life after death. I ask You for the delight of looking upon Your Face and for longing to meet You, without harmful adversity or a trial that leads astray. O Allah, adorn us with the adornment of faith and make us rightly guided guides.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1305)، وصححه ابن حبان (1971)، والحاكم (1923)."},{"num":11040,"demo":false,"sanad":"","matn":["عن عاصم بن كليب، الْجَرْمِيُّ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، قَالَ: دَخَلْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهُوَ يُصَلِّي، وَقَدْ وَضَعَ يَدَهُ الْيُسْرَى عَلَى فَخِذِهِ الْيُسْرَى، وَوَضَعَ يَدَهُ الْيُمْنَى عَلَى فَخِذِهِ الْيُمْنَى، وَقَبَضَ أَصَابِعَهُ، وَبَسَطَ السَّبَّابَةَ وَهُوَ يَقُولُ: يَا مُقَلِّبَ الْقُلُوبِ، ثَبِّتْ قَلْبِي عَلَى دِينِكَ."],"takhrij":"حسن: رواه الترمذي (3587) عن عقبة بن مُكْرَم، حدثنا سعيد بن سفيان الجحدري، حدثنا عبدالله بن مَعْدان، أخبرني عاصم بن كليب الجرميُّ، عن أبيه، عن جدّه قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء من الأدعية قبل التسليم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3587).","chapter_en":"Supplications Narrated before the Concluding Greeting of Peace","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":10,"content":{"translation":{"en":["ʿĀṣim ibn Kulayb narrated from his father, from his grandfather: I entered upon the Prophet ﷺ while he was praying. He had placed his left hand upon his left thigh and his right hand upon his right thigh. He had closed his fingers and extended his index finger while saying: “O Turner of hearts, keep my heart firm upon Your religion.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3587)."},{"num":11041,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا انْصَرَفَ مِنْ صَلَاتِهِ، اسْتَغْفَرَ ثَلَاثًا، وَقَالَ: اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ ذَا الْجَلَالِ وَالْإِكْرَامِ.","قَالَ الْوَلِيدُ: فَقُلْتُ لِلْأَوْزَاعِيِّ: كَيْفَ الْاسْتِغْفَارُ؟ قَالَ: تَقُولُ:","أَسْتَغْفِرُ اللهَ، أَسْتَغْفِرُ اللهَ."],"takhrij":"صحيح: رواه مسلم في المساجد (591) عن داود بن رُشيد، حدثنا الوليد، عن الأوزاعي، عن أبي عمار شدَّاد بن عبدالله، عن أبي أسماء، عن ثوبان فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (591).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Thawbān narrated: When the Messenger of Allah ﷺ finished his prayer, he would seek Allah’s forgiveness three times and say: “O Allah, You are Peace, and from You comes peace. Blessed are You, O Possessor of majesty and honor.” Al-Walīd said: I asked al-Awzāʿī: “How should one seek forgiveness?” He replied: “Say: ‘I seek Allah’s forgiveness. I seek Allah’s forgiveness.’”"]},"intro":{"ar":["دبر، جمعه أدبار، وهو خلاف القبل، يكنى به عن العضوين المخصوصين للإنسان، وهو آخر جزء من الشيء، كما يطلق على الخلف، مثل قولهم: عتق العبد عن دبر، أي: بعد الموت.","وفي قوله ﷺ: «دبر الصلوات»، أطلق على المعنيين، ويحدد معناه حسب القرائن."],"en":["The word dubur, whose plural is adbār, means the opposite of the front. It may be used as an indirect expression for the rear parts of the human body, and it also refers to the final part of something. It can likewise mean “after,” as in the expression, “He freed the slave after his death.”","In the Prophet’s ﷺ phrase “at the dubur of the prayers,” the word may carry either meaning—at the end of the prayer or after it—and its intended meaning is determined by the surrounding context."]}},"tuhfa":{},"full":1,"rep":[2218,13475],"tks":"صحيح: رواه مسلم (591)."},{"num":11042,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ لَمْ يَقْعُدْ إِلَّا مِقْدَارَ مَا يَقُولُ: اللَّهُمَّ أَنْتَ السَّلَامُ، وَمِنْكَ السَّلَامُ، تَبَارَكْتَ ذَا الْجَلَالِ وَالْإِكْرَامِ. وَفِي رِوَايَةِ: ابْنِ نُمَيْرٍ: يَا ذَا الْجَلَالِ وَالْإِكْرَامِ."],"takhrij":"صحيح: رواه مسلم في المساجد (592) من طريق أبي معاوية، عن عاصم، عن عبدالله بن الحارث، عن عائشة فذكرتِه.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (592).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["ʿĀ’ishah narrated: When the Prophet ﷺ concluded the prayer with the greeting of peace, he would remain seated only long enough to say: “O Allah, You are Peace, and from You comes peace. Blessed are You, Possessor of majesty and honor.” Another narration states: “O Possessor of majesty and honor.”"]}},"tuhfa":{},"full":1,"rep":[2219],"tks":"صحيح: رواه مسلم (592)."},{"num":11043,"demo":false,"sanad":"","matn":["عن جعفر بن رَبِيعَةَ، أَنَّ عَوْنَ بْنَ عَبْدِ اللَّهِ بْنِ عُتْبَةَ قَالَ: صَلَّى رَجُلٌ إِلَى جَنْبِ عَبْدِ اللَّهِ بْنِ عَمْرِو بْنِ الْعَاصِي، فَسَمِعَهُ حِينَ سَلَّمَ يَقُولُ: أَنْتَ السَّلَامُ وَمِنْكَ السَّلَامُ، تَبَارَكْتَ يَا ذَا الْجِلَالِ وَالْإِكْرَامِ، ثُمَّ صَلَّى إِلَى جَنْبِ عَبْدِ اللَّهِ بْنِ عُمَرَ حِينَ سَلَّمَ، فَسَمِعَهُ يَقُولُ مِثْلَ ذَلِكَ، فَضَحِكَ الرَّجُلُ، فَقَالَ لَهُ ابْنُ عُمَرَ: مَا أَضْحَكَكَ؟ قَالَ: إِنِّي صَلَّيْتُ إِلَى جَنْبِ عَبْدِ اللَّهِ بْنِ عَمْرٍو فَسَمِعْتُهُ يَقُولُ مِثْلَ مَا قُلْتَ، قَالَ ابْنُ عُمَرَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ ذَلِكَ."],"takhrij":"حسن: رواه النسائي في الكبرى (10125)، والطبراني (13225) كلاهما من طريق سعيد بن الحكم بن أبي مريم، أخبرنا يحيى بن أيوب، حدثني جعفر بن ربيعة فذكره.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in al-Sunan al-Kubrā (10125) and al-Ṭabarānī in al-Muʿjam al-Kabīr (12/339).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Jaʿfar ibn Rabīʿah narrated that ʿAwn ibn ʿAbdullāh ibn ʿUtbah said: A man prayed beside ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ and heard him say after concluding the prayer: “You are Peace, and from You comes peace. Blessed are You, O Possessor of majesty and honor.” He later prayed beside ʿAbdullāh ibn ʿUmar and heard him say the same words after concluding the prayer, so the man laughed. Ibn ʿUmar asked: “What made you laugh?” He replied: “I prayed beside ʿAbdullāh ibn ʿAmr and heard him say the same thing that you said.” Ibn ʿUmar said: “The Messenger of Allah ﷺ used to say that.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في السنن الكبرى (10125)، والطبراني في الكبير (13225)."},{"num":11044,"demo":false,"sanad":"","matn":["عَنْ وَرَّادٍ، كَاتِبِ الْمُغِيرَةِ بْنِ شُعْبَةَ قَالَ: أَمْلَى عَلَىَّ الْمُغِيرَةُ بْنُ شُعْبَةَ فِي كِتَابٍ إِلَى مُعَاوِيَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي دُبُرِ كُلِّ صَلاَةٍ مَكْتُوبَةٍ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهْوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ، اللَّهُمَّ لاَ مَانِعَ لِمَا أَعْطَيْتَ، وَلاَ مُعْطِيَ لِمَا مَنَعْتَ، وَلاَ يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (844)، ومسلم في المساجد (593) كلاهما من طريق ورَّاد مولى المغيرة به مثله.","grade":"متفق عليه","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (844) and Muslim (593).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Warrād, the scribe of al-Mughīrah ibn Shuʿbah, narrated: Al-Mughīrah ibn Shuʿbah dictated to me in a letter addressed to Muʿāwiyah that the Prophet ﷺ would say after every obligatory prayer: “There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things. O Allah, none can withhold what You give, none can give what You withhold, and no person’s wealth or worldly fortune can benefit him against You.”"]},"buhuth":{"en":["Regarding the phrase “no person’s worldly fortune can benefit him against You,” al-Nawawī said:","“The well-known reading adopted by the majority is with the letter jīm carrying a fatḥah. Its meaning is that the wealth and good fortune of a wealthy and fortunate person cannot benefit him against You.”","Here, dubur means immediately after the prayer, as will appear in the narration of Ibn al-Zubayr."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2212,12304,13128],"tks":"متفق عليه: رواه البخاري (844)، ومسلم (593)."},{"num":11045,"demo":false,"sanad":"","matn":["عَنْ مُعَاوِيَةَ بن أَبِي سُفْيَانَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اللهُمَّ لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الْجَدِّ مِنْكَ الْجَدُّ."],"takhrij":"صحيح: رواه أحمد (16929)، والطبراني في الكبير (19/344) كلاهما من طريق أبي نعيم، حدثنا عبد الله بن مبشر مولى أم حبيبة، عن زيد بن أبي عتاب، عن معاوية فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16929) and al-Ṭabarānī in al-Muʿjam al-Kabīr (19/344).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Muʿāwiyah ibn Abī Sufyān narrated: I heard the Messenger of Allah ﷺ say: “O Allah, none can withhold what You give, none can give what You withhold, and no person’s wealth or worldly fortune can benefit him against You.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16929)، والطبراني في الكبير (19/344)."},{"num":11046,"demo":false,"sanad":"","matn":["عَنْ أَبِي الزُّبَيْرِ قَالَ:  كَانَ ابْنُ الزُّبَيْرِ يَقُولُ فِي دُبُرِ كُلِّ صَلَاةٍ حِينَ يُسَلِّمُ: لَا إِلَهَ إِلَّا اللَّهُ، وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ. لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللهِ، لَا إِلَهَ إِلَّا اللَّهُ، وَلَا نَعْبُدُ إِلَّا إِيَّاهُ، لَهُ النِّعْمَةُ وَلَهُ الْفَضْلُ وَلَهُ الثَّنَاءُ الْحَسَنُ. لَا إِلَهَ إِلَّا اللَّهُ مُخْلِصِينَ لَهُ الدِّينَ، وَلَوْ كَرِهَ الْكَافِرُونَ. وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُهَلِّلُ بِهِنَّ دُبُرَ كُلِّ صَلَاةٍ."],"takhrij":"صحيح: رواه مسلم في المساجد (594) عن محمد بن عبدالله بن نمير، حدثنا أبي، حدثنا هشام، عن أبي الزبير فذكر مثله.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (594).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū al-Zubayr narrated: Ibn al-Zubayr would say after every prayer, once he had concluded it with the greeting of peace: “There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things. There is no power and no strength except through Allah. There is no deity worthy of worship except Allah, and we worship none but Him. To Him belong all blessings, all favor, and all excellent praise. There is no deity worthy of worship except Allah, sincerely devoting the religion to Him, even though the disbelievers dislike it.” He said: “The Messenger of Allah ﷺ used to proclaim Allah’s oneness with these words after every prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2217,13214],"tks":"صحيح: رواه مسلم (594)."},{"num":11047,"demo":false,"sanad":"","matn":["عَنْ مُعَاذِ بْنِ جَبَلٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَخَذَ بِيَدِهِ وَقَالَ: يَا مُعَاذُ وَاللَّهِ إِنِّي لأُحِبُّكَ، وَاللَّهِ إِنِّي لأُحِبُّكَ. فَقَالَ: أُوصِيكَ يَا مُعَاذُ لاَ تَدَعَنَّ فِي دُبُرِ كُلِّ صَلاَةٍ تَقُولُ: اللَّهُمَّ أَعِنِّي عَلَى ذِكْرِكَ وَشُكْرِكَ وَحُسْنِ عِبَادَتِكَ."],"takhrij":"صحيح: رواه أبو داود (1522) وهذا لفظه، والنسائي (1303) كلاهما من طريق حيوة بن شريح، قال: سمعتُ عقبة بن مسلم يقول: حدثني أبو عبدالرحمن الحُبُلي، عن الصُنابحي، عن معاذ بن جبل فذكره.وزاد النسائي بعد قول النبي صلى الله عليه وسلم لمعاذ والله إنّي لأحبَك: قال معاذ: وأنا أحبك يا رسول الله.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1522), whose wording is cited here, and al-Nasā’ī (1303).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Muʿādh ibn Jabal narrated: The Messenger of Allah ﷺ took him by the hand and said: “O Muʿādh, by Allah, I truly love you. By Allah, I truly love you.” He then said: “I advise you, O Muʿādh: never neglect to say after every prayer, ‘O Allah, help me to remember You, thank You, and worship You in the best manner.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2226],"tks":"صحيح: رواه أبو داود (1522)، وهذا لفظه، والنسائي (1303)."},{"num":11048,"demo":false,"sanad":"","matn":["عَنْ أَبِي مروان أَنَّ كَعْبًا حَلَفَ لَهُ بالله الَّذِي فَلَقَ الْبَحْرَ لِمُوسَى إِنَّا لَنَجِدُ فِي التَّوْرَاةِ أَنَّ دَاوُدَ نَبِيَّ اللَّهِ كَانَ إِذَا انْصَرَفَ مِنْ صَلَاتِهِ قَالَ: اللَّهُمَّ أَصْلِحْ لِي دِينِي الَّذِي جَعَلْتَهُ لِي عِصْمَةً، وَأَصْلِحْ لِي دُنيايَ الَّتِي جَعَلْتَ فِيهَا مَعَاشِي، اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِك، وَأَعُوذُ بِعَفْوِكَ مِنْ نَقْمَتِك، وَأَعُوذُ بِكَ مِنْكَ، لَا مَانِعَ لِمَا أَعْطَيْتَ، وَلَا مُعْطِيَ لِمَا مَنَعْتَ، وَلَا يَنْفَعُ ذَا الجدِّ مِنْكَ الجدُّ.قَالَ: وَحَدَّثَنِي كَعْبٌ أَنَّ صُهيباً حدَّثه أَنَّ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُهُنَّ عِنْدَ انْصِرَافِهِ مِنْ صَلَاتِهِ."],"takhrij":"حسن: رواه النسائي (1346)، وابن خزيمة (745)، وابن حبان (2036) كلهم من طريق حفص بن ميسرة، عن موسى بن عُقبة، عن عطاء بن أبي مروان، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1346), and authenticated by Ibn Khuzaymah (745) and Ibn Ḥibbān (2036).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Marwān narrated: Kaʿb swore to him by Allah, who split the sea for Moses: “We find in the Torah that David, the Prophet of Allah, would say after completing his prayer: ‘O Allah, rectify for me my religion, which You have made a protection for me, and rectify for me my worldly life, in which You have placed my livelihood. O Allah, I seek refuge in Your pleasure from Your anger, in Your pardon from Your punishment, and in You from You. None can withhold what You give, none can give what You withhold, and no person’s wealth or worldly fortune can benefit him against You.’” He said: Kaʿb also told me that Ṣuhayb narrated to him that Muḥammad ﷺ would say these words after completing his prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1346)، وصححه ابن خزيمة (745)، وابن حبان (2036)."},{"num":11049,"demo":false,"sanad":"","matn":["عَنْ سَعْدِ بن أَبِي وَقَّاصٍ أَنَّهُ كَانَ يُعلِّم بَنِيهِ هَؤُلاَءِ الْكَلِمَاتِ، كَمَا يُعلِّم المعلِّمُ الْغِلْمَانَ الْكِتَابَةَ وَيَقُولُ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَتَعَوَّذُ مِنْهُنَّ دُبُرَ الصَّلاَةِ: اللَّهُمَّ أَعُوذُ بِكَ مِنَ الجُبْنِ، وَأَعُوذُ بِكَ أَنْ أرَدَّ إِلَى أَرْذَلِ الْعُمُرِ، وأَعُوذُ بِكَ مِنْ فِتْنَةِ الدُّنْيَا، وأَعُوذُ بِكَ مِنْ عَذَابِ الْقَبْرِ. وَزَادَ فِي رِوَايَةِ: وَأَعُوذُ بِكَ من الْبُخْلِ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2822) من طريق أبي عوانة، عن عبدالملك بن عمير، قال: سمعتُ عمرو بن ميمون الأوْدي قال:كان سعد فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2822).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Saʿd ibn Abī Waqqāṣ used to teach his sons these words just as a teacher teaches children to write. He would say: The Messenger of Allah ﷺ used to seek refuge through them at the end of the prayer: “O Allah, I seek refuge in You from cowardice. I seek refuge in You from being returned to the most feeble stage of life. I seek refuge in You from the trial of this world, and I seek refuge in You from the punishment of the grave.” Another narration adds: “And I seek refuge in You from miserliness.”"]},"buhuth":{"en":["Here, dubur means at the end of the prayer before the concluding greeting of peace."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2822)."},{"num":11050,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَلَّمَ مِنَ الصَّلاَةِ قَالَ: اللَّهُمَّ اغْفِرْ لِي مَا قَدَّمْتُ، وَمَا أَخَّرْتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، وَمَا أَسْرَفْتُ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، أَنْتَ الْمُقَدِّمُ، وَأَنْتَ الْمُؤَخِّرُ، لاَ إِلَهَ إِلاَّ أَنْتَ."],"takhrij":"صحيح: رواه أبو داود (1509) عن عبيد الله بن معاذ، قال حدثنا أبي، حدثنا عبد العزيز بن أبي سلمة، عن عمه الماجشون بن أبى سلمة، عن عبد الرحمن الأعرج، عن عبيد الله بن أبى رافع، عن علي بن أبى طالب فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1509).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: When the Prophet ﷺ concluded the prayer with the greeting of peace, he would say: “O Allah, forgive me for what I have sent ahead and what I have left behind, what I have concealed and what I have made public, what I have committed excessively, and what You know better about me than I do. You are the One who brings forward, and You are the One who delays. There is no deity worthy of worship except You.”"]},"buhuth":{"en":["It is also narrated in Ṣaḥīḥ Muslim (771/201) that the Prophet ﷺ would say this between the tashahhud and the concluding greeting of peace, while another narration states that he said it after concluding the prayer. These reports may be reconciled by understanding that he sometimes said it before the greeting of peace and at other times afterward."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2228],"tks":"صحيح: رواه أبو داود (1509)."},{"num":11051,"demo":false,"sanad":"","matn":["عَنْ مُسْلِمِ بْنِ أَبِي بَكْرَةَ، قَالَ كَانَ أَبِي يَقُولُ فِي دُبُرِ الصَّلاَةِ: اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنَ الْكُفْرِ وَالْفَقْرِ وَعَذَابِ الْقَبْرِ، فَكُنْتُ أَقُولُهُنَّ، فَقَالَ أَبِي: أَىْ بُنَىَّ عَمَّنْ أَخَذْتَ هَذَا؟ قُلْتُ عَنْكَ. قَالَ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُهُنَّ فِي دُبُرِ الصَّلاَةِ."],"takhrij":"حسن: رواه النسائي (1347)، وأحمد (20409، 20447)، وصحّحه ابن خزيمة (747)، والحاكم (927) كلهم من طرق عن عثمان الشحام، عن مسلم بن أبي بكرة فذكره.واللفظ للنسائي.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1347) and Aḥmad (20409, 20447), and authenticated by Ibn Khuzaymah (747) and al-Ḥākim (927).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Muslim ibn Abī Bakrah narrated: My father would say at the end of the prayer: “O Allah, I seek refuge in You from disbelief, poverty, and the punishment of the grave.” I began saying these words as well. My father asked: “My son, from whom did you learn this?” I replied: “From you.” He said: “The Messenger of Allah ﷺ used to say these words at the end of the prayer.”"]},"buhuth":{"en":["Here, dubur means at the end of the prayer before the concluding greeting of peace."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1347)، وأحمد (20409، 20447)، وصححه ابن خزيمة (747)، والحاكم (927)."},{"num":11052,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، مِنْ بَنِي كِنَانَةَ قَالَ: صَلَّيْتُ خَلْفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ الْفَتْحِ فَسَمِعْتُهُ يَقُولُ: اللهُمَّ لَا تُخْزِنِي يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أحمد (18065) عن إبراهيم بن إسحاق الطالقاني، حدثنا ابن مبارك، عن يحيى بن حسان، عن رجل من بني كنانة فذكره.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (18065).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["A man from Banū Kinānah narrated: I prayed behind the Prophet ﷺ during the Year of the Conquest and heard him say: “O Allah, do not disgrace me on the Day of Resurrection.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (18065)."},{"num":11053,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: جَاءَ الْفُقَرَاءُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: ذَهَبَ أهلُ الدُّثُورِ مِنَ الأَمْوَالِ بِالدَّرَجَاتِ العُلى وَالنَّعِيمِ الْمُقِيمِ: يُصلَّون كَمَا نُصلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَلَهُمْ فَضلٌ مِنْ أَمْوَالٍ يَحُجُّون بِهَا وَيَعْتَمِرُونَ، وَيُجَاهِدُونَ وَيَتَصَدَّقُونَ.قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَلاَ أُحدِّثُكم بِأَمْرٍ إِنْ أَخَذْتُمْ بِهِ أَدْرَكْتُمْ مَنْ سَبقَكم، وَلَمْ يُدْرِكْكُمْ أَحَدٌ بَعْدَكُمْ، وَكُنْتُمْ خَيْرَ مَنْ أَنْتُمْ بينَ ظَهْرَانَيْهِ، إِلاَّ مَن عَمِلَ مِثلَه، تُسبِّحُونَ وتَحمَدونَ وتُكبِّرون خلفَ كلِّ صَلاَةٍ ثَلاَثًا وَثَلاَثِينَ، فَاخْتَلَفْنَا بَيْنَنَا: فَقَالَ بَعْضُنَا: نُسبِّحُ ثَلاَثًا وَثَلاَثِينَ، وَنَحْمَدُ ثَلاَثًا وَثَلاَثِينَ، ونكبِّرُ أَرْبَعًا وَثَلاَثِينَ.فَرَجَعْتُ إِلَيْهِ، فَقَالَ: تَقُولُ سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَاللَّهُ أَكْبَرُ، حَتَّى يَكُونَ منهنَّ كلّهنَّ ثلاثٌ وثلاثون."],"takhrij":"متفق عليه: رواه البخاري في الأذان (843)، ومسلم في المساجد (595) كلاهما من طريق معتمر، عن عبيدالله، عن سُمّيٍ، عن أبي صالح، عن أبي هريرة فذكره،","grade":"متفق عليه","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (843) and Muslim (595). The wording cited here is that of al-Bukhārī.","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated: The poor came to the Prophet ﷺ and said: “The wealthy have taken the highest ranks and everlasting bliss. They pray as we pray and fast as we fast, but they possess surplus wealth through which they perform pilgrimage and ʿumrah, strive in Allah’s path, and give charity.” The Messenger of Allah ﷺ said: “Shall I not tell you of something through which, if you act upon it, you will catch up with those who have preceded you, no one after you will catch up with you, and you will be the best among those around you—except someone who does the same? Glorify Allah, praise Him, and proclaim His greatness thirty-three times after every prayer.” The narrators then differed among themselves. Some said: “We should glorify Allah thirty-three times, praise Him thirty-three times, and proclaim His greatness thirty-four times.” I returned to him, and he said: “Say: ‘Glory be to Allah, all praise belongs to Allah, and Allah is the Greatest,’ until each of them has been said thirty-three times.”"]},"buhuth":{"en":["The word al-duthūr is the plural of dathr and means abundant wealth.","The words “we differed among ourselves” were spoken by Sumayy.","The phrase “I returned to him” means that he returned to Abū Ṣāliḥ, as indicated by some of Muslim’s narrations.","In summary, the phrase “thirty-three times” could be understood as referring to a combined total for all three remembrances, in which case each would be said eleven times. This was the understanding of Suhayl ibn Abī Ṣāliḥ, as Muslim narrated. However, he was not supported in that interpretation.","The clearer meaning is that each remembrance has its own number: Allah is glorified thirty-three times, praised thirty-three times, and magnified thirty-four times, completing one hundred. This interpretation is supported by the other narrations.","The word khalf here means after the concluding greeting of peace."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (843)، ومسلم (595)، واللفظ للبخاري."},{"num":11054,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  مَنْ سَبَّحَ اللهَ فِي دُبُرِ كُلِّ صَلَاةٍ ثَلَاثًا وَثَلَاثِينَ، وَحَمِدَ اللَّهَ ثَلَاثًا وَثَلَاثِينَ، وَكَبَّرَ اللهَ ثَلَاثًا وَثَلَاثِينَ فَتِلْكَ تِسْعَةٌ وَتِسْعُونَ. وَقَالَ: تَمَامَ الْمِائَةِ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، غُفِرَتْ خَطَايَاهُ وَإِنْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"صحيح: رواه مسلم في المساجد (597) عن عبدالحميد بن بيان الواسطي، أخبرنا خالد بن عبدالله، عن سُهيل، عن أبي عبيد المذحجِي، عن عطاء بن يزيد الليثي، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (597).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Whoever glorifies Allah thirty-three times after every prayer, praises Allah thirty-three times, and proclaims Allah’s greatness thirty-three times—making ninety-nine—and completes the hundred by saying, ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things,’ his sins will be forgiven even if they are like the foam of the sea.”"]},"buhuth":{"en":["Here, dubur means immediately after the prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2215,13394],"tks":"صحيح: رواه مسلم (597)."},{"num":11055,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: يَا رَسُولَ اللَّهِ! ذَهَبَ أَصْحَابُ الدُّثُورِ بِالأُجُورِ، يُصَلُّونَ كَمَا نُصَلِّي، وَيَصُومُونَ كَمَا نَصُومُ، وَلَهُمْ فُضُولُ أَمْوَالٍ يَتَصَدَّقُونَ بِهَا، وَلَيْسَ لَنَا مَالٌ نَتَصَدَّقُ بِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا أَبَا ذَرٍّ أَلاَ أُعَلِّمُكَ كَلِمَاتٍ تُدْرِكُ بهنَّ مَنْ سَبَقَكَ، وَلاَ يَلْحَقُكَ مَنْ خَلْفَكَ إِلاَّ مَنْ أَخَذَ بِمِثْلِ عَمَلِكَ؟ قَالَ: بَلَى يَا رَسُولَ اللَّهِ، قَالَ: تُكَبِّرُ اللَّهَ عَزَّ وَجَلَّ دُبر كُلِّ صَلاَةٍ ثَلاَثًا وَثَلاَثِينَ، وَتَحْمَدُهُ ثَلاَثًا وَثَلاَثِينَ، وَتُسَبِّحُهُ ثَلاَثًا وَثَلاَثِينَ، وَتَخْتِمُهَا بِلاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شيء قَدِيرٌ، غُفِرَتْ لَهُ ذُنُوبُهُ وَلَوْ كَانَتْ مِثْلَ زَبَدِ الْبَحْرِ."],"takhrij":"صحيح: رواه أبو داود (1504)، وأحمد (7243)، وصحّحه ابن حبان (2015) كلهم من طريق الوليد بن مسلم، حدثنا الأوزاعي، حدثني حسان بن عطية، حدثني محمد بن أبي عائشة قال: حدثني أبو هريرة قال: قال أبو ذر فذكره.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1504) and Aḥmad (7243), and authenticated by Ibn Ḥibbān (2015).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Dharr said: “O Messenger of Allah, the wealthy have taken all the rewards. They pray as we pray and fast as we fast, but they possess surplus wealth that they give in charity, while we have no wealth to give.” The Messenger of Allah ﷺ said: “O Abū Dharr, shall I not teach you words through which you will catch up with those who preceded you, and no one after you will overtake you except one who performs the same deed?” He replied: “Certainly, O Messenger of Allah.” He said: “Proclaim Allah’s greatness thirty-three times after every prayer, praise Him thirty-three times, glorify Him thirty-three times, and conclude by saying: ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things.’ His sins will be forgiven even if they are like the foam of the sea.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2222],"tks":"صحيح: رواه أبو داود (1504)، وأحمد (7243)، وصححه ابن حبان (2015)."},{"num":11056,"demo":false,"sanad":"","matn":["عَنْ كَعْبِ بْنِ عُجْرَةَ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  مُعَقِّبَاتٌ لَا يَخِيبُ قَائِلُهُنَّ - أَوْ فَاعِلُهُنَّ - دُبُرَ كُلِّ صَلَاةٍ مَكْتُوبَةٍ: ثَلَاثٌ وَثَلَاثُونَ تَسْبِيحَةً، وَثَلَاثٌ وَثَلَاثُونَ تَحْمِيدَةً، وَأَرْبَعٌ وَثَلَاثُونَ تَكْبِيرَةً."],"takhrij":"صحيح: رواه مسلم في المساجد (596) عن الحسن بن عيسى، أخبرنا ابن المبارك، أخبرنا مالك بن مِغْول، قال: سمعتُ الحكم بن عتيبة، يحدث عن عبدالرحمن بن أبي ليلى، عن كعب بن عُجرة فذكر مثله.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (596).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Kaʿb ibn ʿUjrah narrated that the Messenger of Allah ﷺ said: “There are remembrances recited in succession whose speaker—or performer—will not be disappointed after every obligatory prayer: thirty-three glorifications, thirty-three praises, and thirty-four proclamations of Allah’s greatness.”"]},"buhuth":{"en":["Regarding the word muʿaqqibāt, al-Harawī narrated from Shamir that it means glorifications recited after the prayer.","Abū al-Haytham said that they are called muʿaqqibāt because they are performed repeatedly, one after another.","Allah, the Exalted, said:","“For him are successive angels before him and behind him.”","[Sūrat al-Raʿd 13:11]","That is, angels who follow one another in succession. This was mentioned by al-Nawawī.","Here, dubur means immediately after the prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2221],"tks":"صحيح: رواه مسلم (596)."},{"num":11057,"demo":false,"sanad":"","matn":["عَنْ زَيْدِ بْنِ ثَابِتٍ، رَضِيَ اللَّهُ عَنْهُ قَالَ: أُمِرْنَا أَنْ نُسَبِّحَ دُبُرَ كُلِّ صَلاَةٍ ثَلاَثًا وَثَلاَثِينَ، وَنَحْمَدَهُ ثَلاَثًا وَثَلاَثِينَ، وَنُكَبِّرَهُ أَرْبَعًا وَثَلاَثِينَ. قَالَ: فَرَأَى رَجُلٌ مِنَ الأَنْصَارِ فِي الْمَنَامِ فَقَالَ: أَمَرَكُمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ تُسَبِّحُوا فِي دُبُرِ كُلِّ صَلاَةٍ ثَلاَثًا وَثَلاَثِينَ، وَتَحْمَدُوا اللَّهَ ثَلاَثًا وَثَلاَثِينَ، وَتُكَبِّرُوا أَرْبَعًا وَثَلاَثِينَ؛ قَالَ: نَعَمْ. قَالَ: فَاجْعَلُوا خَمْسًا وَعِشْرِينَ، وَاجْعَلُوا التَّهْلِيلَ مَعَهُنَّ، فَغَدَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثَهُ فَقَالَ: افْعَلُوا."],"takhrij":"صحيح: رواه الترمذي (3413)، والنسائي (1350)، وأحمد (21600)، وصحّحه ابن خزيمة (752)، وابن حبان (2017) كلهم من طريق هشام بن حسان، عن محمد بن سيرين، عن كثير بن أفلح، عن زيد بن ثابت فذكر مثله.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3413), al-Nasā’ī (1350), and Aḥmad (21600), and authenticated by Ibn Khuzaymah (752).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Zayd ibn Thābit narrated: We were commanded to glorify Allah thirty-three times after every prayer, praise Him thirty-three times, and proclaim His greatness thirty-four times. A man from the Anṣār then saw in a dream that he was asked: “Did the Messenger of Allah ﷺ command you to glorify Allah thirty-three times after every prayer, praise Him thirty-three times, and proclaim His greatness thirty-four times?” He replied: “Yes.” He was told: “Make each of them twenty-five times and include the declaration that there is no deity worthy of worship except Allah among them.” The next morning, he went to the Prophet ﷺ and told him about it. The Prophet ﷺ said: “Do so.”"]},"buhuth":{"en":["The instruction “make them twenty-five” means to say each of the following twenty-five times: Subḥān Allah, al-ḥamdu lillāh, Allāhu akbar, and lā ilāha illā Allah. This makes a total of one hundred.","Here, dubur means immediately after the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3413)، والنسائي (1350)، وأحمد (21600)، وصححه ابن خزيمة (752)."},{"num":11058,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ رَجُلاً، رَأَى فِيمَا يَرَى النَّائِمُ، قِيلَ لَهُ: بِأَىِّ شَىْءٍ أَمَرَكُمْ نَبِيُّكُمْ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: أَمَرَنَا أَنْ نُسَبِّحَ ثَلاَثًا وَثَلاَثِينَ، وَنَحْمَدَ ثَلاَثًا وَثَلاَثِينَ، وَنُكَبِّرَ أَرْبَعًا وَثَلاَثِينَ. فَتِلْكَ مِائَةٌ. قَالَ سَبِّحُوا خَمْسًا وَعِشْرِينَ وَاحْمَدُوا خَمْسًا وَعِشْرِينَ وَكَبِّرُوا خَمْسًا وَعِشْرِينَ وَهَلِّلُوا خَمْسًا وَعِشْرِينَ فَتِلْكَ مِائَةٌ فَلَمَّا أَصْبَحَ ذَكَرَ ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ افْعَلُوا كَمَا قَالَ الأَنْصَارِيُّ."],"takhrij":"حسن: رواه النسائي (1351) أخبرنا عبيدالله بن عبدالكريم أبوزرعة الرازي، قال: حدثنا أحمد بن عبدالله بن يونس، قال: حدثني علي بن الفُضَيل ابن عياض، عن عبد العزيز بن أبي روَّاد، عن نافع، عن ابن عمر فذكر مثله.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (1351).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar narrated: A man saw in a dream that he was asked: “What has your Prophet ﷺ commanded you to do?” He replied: “He commanded us to glorify Allah thirty-three times, praise Him thirty-three times, and proclaim His greatness thirty-four times, making one hundred.” He was told: “Glorify Allah twenty-five times, praise Him twenty-five times, proclaim His greatness twenty-five times, and declare His oneness twenty-five times. That makes one hundred.” When morning came, he mentioned the dream to the Prophet ﷺ. The Messenger of Allah ﷺ said: “Do as the Anṣārī said.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (1351)."},{"num":11059,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: خَصْلَتَانِ أَوْ خَلَّتَانِ لاَ يُحَافِظُ عَلَيْهِمَا عَبْدٌ مُسْلِمٌ إِلاَّ دَخَلَ الْجَنَّةَ، هُمَا يَسِيرٌ، وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ، يُسَبِّحُ فِي دُبُرِ كُلِّ صَلاَةٍ عَشْرًا، وَيَحْمَدُ عَشْرًا، وَيُكَبِّرُ عَشْرًا، فَذَلِكَ خَمْسُونَ وَمِائَةٌ بِاللِّسَانِ، وَأَلْفٌ وَخَمْسُمِائَةٍ فِي الْمِيزَانِ، وَيُكَبِّرُ أَرْبَعًا وَثَلاَثِينَ إِذَا أَخَذَ مَضْجَعَهُ، وَيَحْمَدُ ثَلاَثًا وَثَلاَثِينَ، وَيُسَبِّحُ ثَلاَثًا وَثَلاَثِينَ فَذَلِكَ مِائَةٌ بِاللِّسَانِ، وَأَلْفٌ فِي الْمِيزَانِ. فَلَقَدْ رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَعْقِدُهَا بِيَدِهِ قَالُوا: يَا رَسُولَ اللَّهِ كَيْفَ هُمَا يَسِيرٌ وَمَنْ يَعْمَلُ بِهِمَا قَلِيلٌ؟ قَالَ: يَأْتِي أَحَدَكُمْ - يَعْنِي الشَّيْطَانَ - فِي مَنَامِهِ فَيُنَوِّمُهُ قَبْلَ أَنْ يَقُولَهُ وَيَأْتِيهِ فِي صَلاَتِهِ فَيُذَكِّرُهُ حَاجَةً قَبْلَ أَنْ يَقُولَهَا."],"takhrij":"صحيح: رواه أبو داود (5065) من طريق شعبة-، والترمذي (3410) من طريق إسماعيل بن علية-، والنسائي (1348) من طريق حماد-، وابن ماجه (926) من طريق إسماعيل، ومحمد بن فضيل، وأبي يحيى التيمي، وابن الأجلح- كلهم عن عطاء بن السائب، عن أبيه، عن عبد الله بن عمرو فذكره.واللفظ لأبي داود.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (5065), al-Tirmidhī (3410), al-Nasā’ī (1348), and Ibn Mājah (926).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr narrated that the Prophet ﷺ said: “There are two practices which no Muslim servant preserves except that he will enter Paradise. They are easy, yet those who perform them are few. After every prayer, he glorifies Allah ten times, praises Him ten times, and proclaims His greatness ten times. That amounts to one hundred and fifty upon the tongue and one thousand five hundred in the Scale. When he goes to bed, he proclaims Allah’s greatness thirty-four times, praises Him thirty-three times, and glorifies Him thirty-three times. That amounts to one hundred upon the tongue and one thousand in the Scale.” The narrator said: “I saw the Messenger of Allah ﷺ counting them upon his hand.” They asked: “O Messenger of Allah, how can they be easy while those who perform them are few?” He replied: “Satan comes to one of you when he is about to sleep and causes him to fall asleep before he says them. He also comes to him during his prayer and reminds him of some need before he says them.”"]},"buhuth":{"en":["The phrase “one hundred and fifty” refers to the total after the five daily prayers.","Here, dubur means immediately after the prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11252],"tks":"صحيح: رواه أبو داود (5065)، والترمذي (3410)، والنسائي (1348)، وابن ماجه (926)."},{"num":11060,"demo":false,"sanad":"","matn":["عَنْ عُقْبَةَ بْنِ عَامِرٍ، قَالَ: أَمَرَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ أَقْرَأَ بِالْمُعَوِّذَاتِ دُبُرَ كُلِّ صَلاَةٍ."],"takhrij":"حسن: رواه أبو داود (1523)، والنسائي (1336)، وصحّحه ابن خزيمة (755)، والحاكم (929) كلهم من طريق الليث بن سعد، أن حنين بن أبي حكيم، حدَّثه عن علي بن رباح، عن عقبة بن عامر فذكره.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1523) and al-Nasā’ī (1336), and authenticated by Ibn Khuzaymah (755) and al-Ḥākim (929).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["ʿUqbah ibn ʿĀmir narrated: “The Messenger of Allah ﷺ commanded me to recite the protecting sūrahs after every prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2227],"tks":"حسن: رواه أبو داود (1523)، والنسائي (1336)، وصححه ابن خزيمة (755)، والحاكم (929)."},{"num":11061,"demo":false,"sanad":"","matn":["عَن أَبِي أُمَامَة، قَالَ: قَالَ رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: من قَرَأَ آيَة الْكُرْسِيّ فِي دُبُرِ كُلِّ صَلَاة مَكْتُوبَة، لَمْ يمنعهُ من دُخُول الْجنَّة إِلَّا أَن يَمُوت."],"takhrij":"حسن: رواه النسائي في اليوم والليلة (100) عن الحسين بن بشر قال: حدثنا محمد بن حِمْيَر، قال: حدثنا محمد بن زياد، عن أبي أمامة فذكر الحديث.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (100).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Umāmah narrated that the Messenger of Allah ﷺ said: “Whoever recites Āyat al-Kursī after every obligatory prayer, nothing prevents him from entering Paradise except that he must die.”"]},"buhuth":{"en":["Here, dubur means immediately after the prayer."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11881],"tks":"حسن: رواه النسائي في عمل اليوم والليلة (100)."},{"num":11062,"demo":false,"sanad":"","matn":["عن أَبِي أُمَامَةَ قَالَ: قَالَ رَسُولُ اللَّهِ - صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ قَالَ دُبُرَ كُلِّ صَلَاةِ الْغَدَاةِ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، يُحْيِي وَيُمِيتُ، بِيَدِهِ الْخَيْرُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، مِائَةَ مَرَّةٍ قَبْلَ أَنْ يَثْنِيَ رِجْلَيْهِ ; كَانَ يَوْمَئِذٍ مِنْ أَفْضَلِ أَهْلِ الْأَرْضِ عَمَلًا، إِلَّا مَنْ قَالَ مِثْلَ مَا قَالَ أَوْ زَادَ عَلَى مَا قَالَ."],"takhrij":"حسن: رواه الطبراني في الكبير (8075)، والأوسط (4656-مجمع البحرين)، وابن السني في عمل اليوم والليلة (143) كلهم من طريق عبد الصمد بن عبد الوارث، عن آدم بن الحكم، حدثنا أبو غالب، عن أبي أمامة فذكره.","grade":"حسن","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (8/336) and al-Muʿjam al-Awsaṭ (4656, as cited in Majmaʿ al-Baḥrayn), and by Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (143).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Abū Umāmah narrated that the Messenger of Allah ﷺ said: “Whoever says one hundred times after the dawn prayer, before moving his legs from their position: ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise. He gives life and causes death. All goodness is in His hand, and He has power over all things,’ will on that day be the best of the people of the earth, except someone who says the same as he said or says more.”"]},"buhuth":{"en":["Here, dubur means immediately after the prayer."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (8075)، والأوسط (4656 - مجمع البحرين)، وابن السني في عمل اليوم والليلة (143)."},{"num":11063,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ بَعْدَ صَلَاةِ الْفَجْرِ: اللَّهُمَّ، إِنِّي أَسْأَلُكَ رِزْقًا طَيِّبًا، وَعِلْمًا نَافِعًا، وَعَمَلًا مُتَقَبَّلًا."],"takhrij":"صحيح: رواه الطبراني في الصغير (735) عن عامر بن إبراهيم بن عامر الأصبهاني، حدثنا أبي، عن جدي عامر بن إبراهيم، عن النعمان بن عبد السلام، عن سفيان الثوري، عن منصور، عن الشعبي، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب الأذكار أعقاب الصلوات المفروضة وأدبارها","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭabarānī in al-Muʿjam al-Ṣaghīr (1/260).","chapter_en":"Remembrances Recited Immediately after the Obligatory Prayers and at Their Conclusions","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":11,"content":{"translation":{"en":["Umm Salamah narrated: The Prophet ﷺ would say after the Fajr prayer: “O Allah, I ask You for lawful and wholesome provision, beneficial knowledge, and accepted deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الطبراني في الصغير (735)."},{"num":11064,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أنّ رَفْعَ الصَّوْتِ بِالذِّكْرِ حِينَ يَنْصَرِفُ النَّاسُ مِنَ الْمَكْتُوبَةِ كَانَ عَلَى عَهْدِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. . وَقَالَ ابْنُ عَبَّاسٍ: كنتُ أَعْلَمُ إِذَا انْصَرَفُوا بِذَلِكَ إِذَا سَمِعْتُهُ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (841)، ومسلم في المساجد (583: 122) كلاهما من طريق عبد الرزاق، أخبرنا ابن جريج قال: أخبرني عمرو بن دينار، أن أبا معبد مولى ابن عباس أخبره، أن ابن عباس أخبره، فذكره.","grade":"متفق عليه","chapter_ar":"باب رفع الصوت بالأذكار عقب الصلوات المفروضة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (841) and Muslim (583/122).","chapter_en":"Raising the Voice with Remembrance after the Obligatory Prayers","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās narrated: Raising the voice with remembrance when the people completed the obligatory prayer was practiced during the time of the Prophet ﷺ. Ibn ʿAbbās said: “I would know that they had completed the prayer when I heard it.”"]},"buhuth":{"en":["Al-Bukhārī (842) and Muslim (583/120) also narrated it with the wording:","“We used to recognize the completion of the prayer of the Messenger of Allah ﷺ by the takbīr.”","The word “takbīr” here may refer generally to remembrance, as indicated by the first narration, because the reported supplications after obligatory prayers do not contain takbīr.","It is also possible that the Prophet ﷺ raised his voice with the takbīr on one or two occasions and Ibn ʿAbbās heard it, although this was not his regular practice."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2213],"tks":"متفق عليه: رواه البخاري (841)، ومسلم (583: 122)."},{"num":11065,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَتَهَجَّدُ قَالَ: اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ قَيِّمُ السماوات وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ لَكَ ملكُ السماوات وَالأَرْضِ وَمَنْ فِيهِنَّ، وَلَكَ الْحَمْدُ أَنْتَ نورُ السماوات وَالأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ مالك السماوات وَالأَرْضِ، وَلَكَ الْحَمْدُ أَنْتَ الْحَقُّ، وَوَعْدُكَ الْحَقُّ، ولقاءُك حَقٌّ، وَقَوْلُكَ حَقٌّ، وَالْجَنَّةُ حَقٌّ وَالنَّارُ حَقٌّ، وَالنَّبِيُّونَ حَقٌّ، وَمُحَمَّدٌ حَقٌّ، وَالسَّاعَةُ حَقٌّ.اللَّهُمَّ لَكَ أَسْلَمْتُ، وَبِكَ آمَنْتُ، وَعَلَيْكَ تَوَكَّلْتُ، وَإِلَيْكَ أَنَبْتُ، وَبِكَ خَاصَمْتُ، وَإِلَيْكَ حَاكَمْتُ، فَاغْفِرْ لِي مَا قدَّمتُ وَمَا أخَّرتُ، وَمَا أَسْرَرْتُ، وَمَا أَعْلَنْتُ، أَنْتَ المقَدِّم، وَأَنْتَ الْمُؤَخِّرُ لاَ إِلَهَ إِلاَّ أنتَ لاَ إِلَهَ غَيْرُكَ.","قَالَ سُفْيَانُ: وَزَادَ عَبْدُ الْكَرِيمِ أَبُو أُمَيَّةَ: ولاحولَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في التهجد (1120)، ومسلم في صلاة المسافرين (769) كلاهما من حديث سفيان، عن سليمان بن أبي مسلم الأحول، عن طاوسٍ، سمع ابن عباس قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد وفي التهجد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1120) and Muslim (769).","chapter_en":"Recommended Remembrance upon Rising for the Night Prayer and during It","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿAbbās narrated: When the Prophet ﷺ rose during the night to perform the night prayer, he would say: “O Allah, all praise belongs to You. You are the Sustainer of the heavens and the earth and all who are within them. All praise belongs to You. To You belongs the dominion of the heavens and the earth and all who are within them. All praise belongs to You. You are the Light of the heavens and the earth. All praise belongs to You. You are the King of the heavens and the earth. All praise belongs to You. You are the Truth, Your promise is true, meeting You is true, Your word is true, Paradise is true, the Fire is true, the prophets are true, Muḥammad is true, and the Hour is true. O Allah, to You I have submitted, in You I have believed, upon You I have relied, to You I have turned in repentance, through Your aid I have disputed, and to You I have referred for judgment. Forgive me for what I have sent ahead and what I have left behind, what I have concealed and what I have made public. You are the One who brings forward, and You are the One who delays. There is no deity worthy of worship except You; there is no deity besides You.”","Sufyān said: ʿAbd al-Karīm Abū Umayyah added: “There is no power and no strength except through Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2668],"tks":"متفق عليه: رواه البخاري (1120)، ومسلم (769)."},{"num":11066,"demo":false,"sanad":"","matn":["عن عُبَادَةَ بْنِ الصَّامِتِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ تَعَارَّ مِنَ اللَّيْلِ فَقَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ، وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ. الْحَمْدُ لِلَّهِ، وَسُبْحَانَ اللَّهِ، وَلاَ إِلَهَ إِلاَّ اللَّهُ، وَاللَّهُ أَكْبَرُ، وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ. ثُمَّ قَالَ: اللَّهُمَّ اغْفِرْ لِي. أَوْ دَعَا، اسْتُجِيبَ، فَإِنْ تَوَضَّأَ وَصَلَّى قُبِلَتْ صَلاَتُهُ."],"takhrij":"صحيح: رواه البخاري في التهجد (1154) عن صَدَقَة بن الفضل، أخبرنا الوليد، عن الأوزاعي، قال: حدثني عُمير بن هانئ قال: حدثني جنادةُ بن أبي أمية، حدثني عُبادة بن الصامت فذكره.","grade":"صحيح","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد وفي التهجد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1154).","chapter_en":"Recommended Remembrance upon Rising for the Night Prayer and during It","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["ʿUbādah ibn al-Ṣāmit narrated that the Prophet ﷺ said: “Whoever awakens during the night and says: ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things. All praise belongs to Allah, glory be to Allah, there is no deity worthy of worship except Allah, Allah is the Greatest, and there is no power and no strength except through Allah,’ and then says, ‘O Allah, forgive me,’ or makes another supplication, his supplication will be answered. If he performs ablution and prays, his prayer will be accepted.”"]},"buhuth":{"en":["Al-Baghawī said that the word taʿārra means to awaken from sleep."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2669,11263],"tks":"صحيح: رواه البخاري (1154)."},{"num":11067,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَلَمَةَ بن عبدالرحمن بن عَوْفٍ قَالَ: سَأَلْتُ عَائِشَةَ أُمَّ المؤمين: بأيّ شَيْءٍ كَانَ نبيُّ اللَّهِ يَفْتَتِحُ صَلَاتَهُ إِذَا قَامَ مِنَ اللَّيْلِ؟ قَالَتْ: كَانَ إِذَا قَامَ مِنَ اللَّيْلِ افْتَتَحَ صَلَاتَهُ: اللَّهُمَّ ربَّ جَبْرَائيل وَمِيكَائِيلَ وَإِسْرَافِيلَ.فَاطِرَ السَّمَاوَاتِ وَالْأَرْضِ، عَالِمَ الْغَيْبِ وَالشَّهَادَةِ، أَنْتَ تَحْكُمُ بَيْنَ عِبَادِكَ فِيمَا كَانُوا فِيهِ يَخْتَلِفُونَ، اهْدِنِي لِمَا اختُلِف فِيهِ مِنَ الْحَقِّ بِإِذْنِكَ إِنَّكَ تَهْدِي مَنْ تَشَاءُ إِلَى صِرَاطٍ مُسْتَقِيمٍ."],"takhrij":"صحيح: رواه مسلم في صلاة المسافرين (770) من طرق عن عمر بن يونس، حدثنا عكرمة بن عمار، حدثنا يحيى بن أبي كثير، حدثني أبو سلمة بن عبدالرحمن فذكره.","grade":"صحيح","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد وفي التهجد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (770).","chapter_en":"Recommended Remembrance upon Rising for the Night Prayer and during It","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Abū Salamah ibn ʿAbd al-Raḥmān ibn ʿAwf narrated: I asked ʿĀ’ishah, Mother of the Believers: “With what would the Prophet of Allah ﷺ begin his prayer when he rose during the night?” She replied: When he rose during the night, he would begin his prayer by saying: “O Allah, Lord of Gabriel, Michael, and Isrāfīl, Originator of the heavens and the earth, Knower of the unseen and the witnessed, You judge between Your servants concerning that over which they differ. Guide me, by Your permission, to the truth concerning that over which they differ. Indeed, You guide whom You will to a straight path.”"]}},"tuhfa":{},"full":1,"rep":[2670],"tks":"صحيح: رواه مسلم (770)."},{"num":11068,"demo":false,"sanad":"","matn":["عَنْ عَاصِمِ بْنِ حُمَيْدٍ، قَالَ: سَأَلْتُ عَائِشَةَ: بِأَىِّ شَىْءٍ كَانَ يَفْتَتِحُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِيَامَ اللَّيْلِ؟ فَقَالَتْ: لَقَدْ سَأَلْتَنِي عَنْ شَىْءٍ مَا سَأَلَنِي عَنْهُ أَحَدٌ قَبْلَكَ، كَانَ إِذَا قَامَ كَبَّرَ عَشْرًا، وَحَمِدَ اللَّهَ عَشْرًا، وَسَبَّحَ عَشْرًا، وَهَلَّلَ عَشْرًا، وَاسْتَغْفَرَ عَشْرًا، وَقَالَ: اللَّهُمَّ اغْفِرْ لِي، وَاهْدِنِي، وَارْزُقْنِي وَعَافِنِي. وَيَتَعَوَّذُ مِنْ ضِيقِ الْمَقَامِ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه أبو داود (766)، والنسائي (1618)، وابن ماجه (1356) وصحّحه ابن حبان (2602) كلّهم من حديث زيد بن الحُباب، عن معاوية بن صالح، قال: حدثني أزهر بن سعيد، عن عاصم بن حُميد فذكره.","grade":"حسن","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد وفي التهجد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (766), al-Nasā’ī (1618), and Ibn Mājah (1356), and authenticated by Ibn Ḥibbān (2602).","chapter_en":"Recommended Remembrance upon Rising for the Night Prayer and during It","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["ʿĀṣim ibn Ḥumayd narrated: I asked ʿĀ’ishah: “With what would the Messenger of Allah ﷺ begin the night prayer?” She replied: “You have asked me about something that no one before you has asked me.” When he rose, he would proclaim Allah’s greatness ten times, praise Allah ten times, glorify Him ten times, declare His oneness ten times, and seek His forgiveness ten times. He would then say: “O Allah, forgive me, guide me, and provide for me.” He would also seek refuge from the constriction and hardship of standing on the Day of Resurrection."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2671,13693],"tks":"حسن: رواه أبو داود (766)، والنسائي (1618)، وابن ماجه (1356)، وصححه ابن حبان (2602)."},{"num":11069,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ:  بِتُّ لَيْلَةً عِنْدَ خَالَتِي مَيْمُونَةَ، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ، فَأَتَى حَاجَتَهُ، ثُمَّ غَسَلَ وَجْهَهُ وَيَدَيْهِ، ثُمَّ نَامَ. ثُمَّ قَامَ، فَأَتَى الْقِرْبَةَ، فَأَطْلَقَ شِنَاقَهَا، ثُمَّ تَوَضَّأَ وُضُوءًا بَيْنَ الْوُضُوءَيْنِ، وَلَمْ يُكْثِرْ، وَقَدْ أَبْلَغَ. ثُمَّ قَامَ، فَصَلَّى، فَقُمْتُ فَتَمَطَّيْتُ كَرَاهِيَةَ أَنْ يَرَى أَنِّي كُنْتُ أَنْتَبِهُ لَهُ، فَتَوَضَّأْتُ. فَقَامَ فَصَلَّى فَقُمْتُ عَنْ يَسَارِهِ، فَأَخَذَ بِيَدِي فَأَدَارَنِي عَنْ يَمِينِهِ، فَتَتَامَّتْ صَلَاةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنَ اللَّيْلِ ثَلَاثَ عَشْرَةَ رَكْعَةً، ثُمَّ اضْطَجَعَ فَنَامَ حَتَّى نَفَخَ، - وَكَانَ إِذَا نَامَ نَفَخَ، -، فَأَتَاهُ بِلَالٌ فَآذَنَهُ بِالصَّلَاةِ فَقَامَ فَصَلَّى، وَلَمْ يَتَوَضَّأْ، وَكَانَ فِي دُعَائِهِ: اللَّهُمَّ اجْعَلْ فِي قَلْبِي نُورًا، وَفِي بَصَرِي نُورًا، وَفِي سَمْعِي نُورًا، وَعَنْ يَمِينِي نُورًا، وَعَنْ يَسَارِي نُورًا. وَفَوْقِي نُورًا، وَتَحْتِي نُورًا، وَأَمَامِي نُورًا، وَخَلْفِي نُورًا. وَعَظِّمْ لِي نُورًا.","قال كريب (الراوي عن ابن عباس): وسبعا في التابوت فلقيت بعض ولد العباس فحدثني بهن فذكر عصبي ولحمي ودمي وشعري وبشري وذكر خصلتين."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6316)، ومسلم في صلاة المسافرين (763: 181) كلاهما من طريق ابن مهدي، عن سفيان، عن سلمة، عن كريب، عن ابن عباس قال:فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يستحب من الذكر عند القيام للتهجد وفي التهجد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6316) and Muslim (763/181).","chapter_en":"Recommended Remembrance upon Rising for the Night Prayer and during It","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":13,"content":{"translation":{"en":["Ibn ʿAbbās narrated: I spent a night at the home of my maternal aunt Maymūnah. The Prophet ﷺ rose during the night, relieved himself, washed his face and hands, and then slept. He later rose again, went to the water-skin, loosened its strap, and performed a moderate but complete ablution. He then stood to pray. I rose and stretched, not wanting him to realize that I had been awake and observing him. I performed ablution and stood on his left side. He took me by the hand and moved me to his right. The Messenger of Allah ﷺ completed thirteen units of prayer during the night. He then lay down and slept until the sound of his breathing could be heard, for when he slept, his breathing could be heard. Bilāl came and informed him that it was time for prayer. He rose and prayed without performing a new ablution. Among his supplications was: “O Allah, place light within my heart, light within my sight, and light within my hearing. Place light to my right and light to my left, light above me and light beneath me, light before me and light behind me, and magnify light for me.” Kurayb, the narrator from Ibn ʿAbbās, said: “There were seven additional phrases stored in my heart.” I later met one of the descendants of al-ʿAbbās, who narrated them to me. He mentioned: “My nerves, my flesh, my blood, my hair, and my skin,” and he mentioned two additional qualities."]},"buhuth":{"en":["The phrase “in the chest” means that seven additional words were retained in his heart, but he later forgot them."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6316)، ومسلم (763: 181)."},{"num":11070,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ فِي آخِرِ وِتْرِهِ اللَّهُمَّ إِنِّي أَعُوذُ بِرِضَاكَ مِنْ سَخَطِكَ، وَبِمُعَافَاتِكَ مِنْ عُقُوبَتِكَ، وَأَعُوذُ بِكَ مِنْكَ، لاَ أُحْصِي ثَنَاءً عَلَيْكَ أَنْتَ كَمَا أَثْنَيْتَ عَلَى نَفْسِكَ."],"takhrij":"صحيح: رواه أبو داود (1427)، والترمذي (3561)، والنسائي (1748)، وابن ماجه (1179)، والحاكم (1150) كلهم من طريق حماد بن سلمة، حدثني هشام بن عمرو الفزاري، عن عبدالرحمن بن الحارث بن هشام المخزومي، عن علي بن أبي طالب فذكره.","grade":"صحيح","chapter_ar":"باب ما يدعى به في قنوت الوتر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1427), al-Tirmidhī (3561), al-Nasā’ī (1748), and Ibn Mājah (1179).","chapter_en":"What Should Be Said in the Qunūt of Witr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated: At the end of the Witr prayer, the Prophet ﷺ would say: “O Allah, I seek refuge in Your pleasure from Your anger, in Your pardon from Your punishment, and in You from You. I cannot enumerate sufficient praise of You. You are as You have praised Yourself.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2833],"tks":"صحيح: رواه أبو داود (1427)، والترمذي (3561)، والنسائي (1748)، وابن ماجه (1179)."},{"num":11071,"demo":false,"sanad":"","matn":["عَنْ الْحَسَنِ بن عَلِيٍّ قَالَ: علَّمني رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَلِمَاتٍ أقولُهنَّ فِي الْوِتْرِ: اللَّهُمَّ اهْدِنِي فِيمَنْ هَدَيْتَ، وَعَافِنِي فِيمَنْ عَافَيْتَ، وَتَوَلَّنِي فِيمَنْ تولَّيتَ، وَبَارِكْ لِي فِيمَا أَعْطَيْتَ، وقِنِي شرَّ مَا قَضَيْتَ، إنَّك تَقْضِي وَلاَ يُقْضَى عَلَيْكَ، وإنَّه لاَ يَذِلُّ مَنْ وَالَيْتَ، وَلاَ يَعِزُّ مَنْ عَادَيْتَ، تَبَارَكْتَ ربَّنا وَتَعَالَيْتَ."],"takhrij":"صحيح: رواه أبو داود (1425)، والترمذي (464)، والنسائي (1745)، وابن ماجه (1178) وصحّحه ابن خزيمة (1095) كلهم من طريق أبي إسحاق، عن بُريد بن أبي مريم السلولي، عن أبي الحوراء، عن الحسن بن علي فذكره.","grade":"صحيح","chapter_ar":"باب ما يدعى به في قنوت الوتر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1425), al-Tirmidhī (464), al-Nasā’ī (1745), and Ibn Mājah (1178).","chapter_en":"What Should Be Said in the Qunūt of Witr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":14,"content":{"translation":{"en":["Al-Ḥasan ibn ʿAlī ibn Abī Ṭālib narrated: The Messenger of Allah ﷺ taught me words to say during the Witr prayer: “O Allah, guide me among those whom You have guided. Grant me well-being among those to whom You have granted well-being. Take me into Your care among those whom You have taken into Your care. Bless me in what You have given me, and protect me from the evil of what You have decreed. Indeed, You decree, and none decrees over You. The one whom You befriend is never humiliated, and the one whom You oppose is never honored. Blessed are You, our Lord, and Exalted.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2834],"tks":"صحيح: رواه أبو داود (1425)، والترمذي (464)، والنسائي (1745)، وابن ماجه (1178)."},{"num":11072,"demo":false,"sanad":"","matn":["عن أُبيّ بن كعب قال: كان رسول الله صلى الله عليه وسلم إذا جلس في آخر صلاته في الوتر يقول: يعني بعد التسليم: سبحان الملك القدُّوس ثلاثاً."],"takhrij":"صحيح: رواه النسائي (1701) من طريق سفيان، عن زُبيد، عن سعيد بن عبدالرحمن بن أَبزى، عن أبيه، عن أبي بن كعب فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال عقب السلام من الوتر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1701).","chapter_en":"What Should Be Said after Concluding the Witr Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":15,"content":{"translation":{"en":["Ubayy ibn Kaʿb narrated: When the Messenger of Allah ﷺ completed the Witr prayer, he would say after the concluding greeting of peace: “Glory be to the Sovereign, the Most Holy,” three times."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه النسائي (1701)."},{"num":11073,"demo":false,"sanad":"","matn":["عن ابن عبدالرحمن بن أبْزى، عن أبيه، أن رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كان يُوتر سَبِّحِ اسْمَ رَبِّكَ الْأَعْلَى و قُلْ يَا أَيُّهَا الْكَافِرُونَ و قُلْ هُوَ اللَّهُ أَحَدٌ وكان يقول إذا سلَّم: سبحان الملك القدوس ثلاثاً ويرفع صوتَه بالثالثة."],"takhrij":"صحيح: رواه النسائي (1732) عن عمرو بن يزيد، قال: حدثنا بهز بن أسد، قال: حدثنا شُعبة، عن سلمة وزُبيد، عن ذر، عن ابن عبدالرحمن بن أبْزى فذكره.","grade":"صحيح","chapter_ar":"باب ما يقرأ في صلاة الوتر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1732).","chapter_en":"What Should Be Recited in the Witr Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":16,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abzā narrated from his father: The Messenger of Allah ﷺ would perform the Witr prayer by reciting: “Glorify the name of your Lord, the Most High,” “Say: O disbelievers,” and: “Say: He is Allah, the One.” After concluding the prayer with the greeting of peace, he would say: “Glory be to the Sovereign, the Most Holy,” three times, raising his voice during the third repetition."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه النسائي (1732)."},{"num":11074,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: دَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الَّذِينَ قَتَلُوا ـ يَعْنِي ـ أَصْحَابَهُ بِبِئْرِ مَعُونَةَ ثَلاَثِينَ صَبَاحًا، حِينَ يَدْعُو عَلَى رِعْلٍ وَلِحْيَانَ: وَعُصَيَّةَ عَصَتِ اللَّهَ وَرَسُولَهُ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَ أَنَسٌ: فَأَنْزَلَ اللَّهُ تَعَالَى لِنَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الَّذِينَ قُتِلُوا أَصْحَابِ بِئْرِ مَعُونَةَ قُرْآنًا قَرَأْنَاهُ حَتَّى نُسِخَ بَعْدُ: بَلِّغُوا قَوْمَنَا فَقَدْ لَقِينَا رَبَّنَا، فَرَضِيَ عَنَّا، وَرَضِينَا عَنْهُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4095) ، ومسلم في المساجد (677) كلاهما من طريق مالك، عن إسحاق بن عبد الله بن أبي طلحة، عن أنس بن مالك فذكره.واللفظ للبخاري، وزاد مسلم وذكوان بعد رِعْلٍ.","grade":"متفق عليه","chapter_ar":"باب ما جاء في القنوت في الصلوات إذا نزلت بالمسلمين نازلة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4095) and Muslim (677).","chapter_en":"Qunūt in the Prayers When a Calamity Befalls the Muslims","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Mālik narrated: For thirty mornings, the Prophet ﷺ supplicated against those who had killed his Companions at Bi’r Maʿūnah. He supplicated against Riʿl, Liḥyān, and ʿUṣayyah, saying: “ʿUṣayyah has disobeyed Allah and His Messenger.” Anas said: Allah, the Exalted, revealed to His Prophet ﷺ concerning those Companions who had been killed at Bi’r Maʿūnah words of the Qur’an which we recited until they were later abrogated: “Inform our people that we have met our Lord, that He is pleased with us, and that we are pleased with Him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2841,8885],"tks":"متفق عليه: رواه البخاري (4095)، ومسلم (677)."},{"num":11075,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ حِينَ يَفْرُغُ مِن صَلَاةِ الْفَجْرِ مِنَ الْقِرَاءَةِ، ويكبِّر، وَيَرْفَعُ رَأْسَهُ سَمِعَ اللَّهُ لِمَنْ حَمِدَهُ، رَبَّنَا وَلَكَ الْحَمْدُ ثُمَّ يَقُولُ وَهُوَ قَائِمٌ: اللَّهُمَّ أنْجِ الْوَلِيدَ بْنَ الْوَلِيدِ، وَسَلَمَةَ بْنَ هِشَامٍ، وَعَيَّاشَ بْنَ أَبِي رَبِيعَةَ، وَالْمُسْتَضْعَفِينَ مِنَ الْمُؤْمِنِينَ، واللهم اشدُدْ وَطْأتك عَلَى مُضَرَ، وَاجْعَلْهَا عَلَيْهِمْ كَسِنِيِّ يُوسُفَ.اللَّهُمَّ العَنْ لَحْيانَ ورِعْلاً وَذَكْوَانَ وعُصَيَّة عصتِ اللَّهَ وَرَسُولَهُ ثُمَّ بَلَغَنَا أَنَّهُ تَرَكَ ذَلِكَ لَمَّا أُنْزِلَ: ﴿لَيْسَ لَكَ مِنَ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ﴾ [سورة آلِ عِمْرَانَ: 128]."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4560)، ومسلم في المساجد (675) كلاهما من طريق ابن شهاب، عن سعيد بن المسيب وأبي سلمة بن عبدالرحمن، عن أبي هريرة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب ما جاء في القنوت في الصلوات إذا نزلت بالمسلمين نازلة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4560) and Muslim (675).","chapter_en":"Qunūt in the Prayers When a Calamity Befalls the Muslims","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":17,"content":{"translation":{"en":["Abū Hurayrah narrated: When the Messenger of Allah ﷺ finished reciting during the Fajr prayer, proclaimed the takbīr, and raised his head, he would say: “Allah hears the one who praises Him. Our Lord, and all praise belongs to You.” Then, while standing, he would say: “O Allah, rescue al-Walīd ibn al-Walīd, Salamah ibn Hishām, ʿAyyāsh ibn Abī Rabīʿah, and the oppressed believers. O Allah, intensify Your punishment upon Muḍar and inflict upon them years of famine like the years of Joseph. O Allah, curse Liḥyān, Riʿl, Dhakwān, and ʿUṣayyah, for they disobeyed Allah and His Messenger.” We were later informed that he stopped doing this when the following verse was revealed: “You have no authority in this matter—whether He turns toward them in mercy or punishes them—for indeed, they are wrongdoers.” [Sūrat Āl ʿImrān 3:128]"]},"buhuth":{"en":["It is also authentically established that ʿUmar ibn al-Khaṭṭāb would recite the qunūt during the Fajr prayer, saying:","“In the name of Allah, the Most Compassionate, the Most Merciful. O Allah, we seek Your assistance, believe in You, rely upon You, praise You for all goodness, and do not disbelieve in You.”","He would then recite:","“In the name of Allah, the Most Compassionate, the Most Merciful. O Allah, You alone we worship. For You we pray and prostrate. Toward You we hasten and strive. We hope for Your mercy and fear Your punishment. Indeed, Your punishment will overtake the disbelievers. O Allah, punish the disbelievers among the People of the Book who turn others away from Your path.”","Narrated by Ibn Abī Shaybah (7104), through Ḥafṣ ibn Ghiyāth, from Ibn Jurayj, from ʿAṭāʾ, from ʿUbayd ibn ʿUmayr, who said:","“I heard ʿUmar reciting the qunūt during the Fajr prayer,”","and he mentioned this supplication.","Its chain of transmission is authentic, and it is a statement attributed to ʿUmar ibn al-Khaṭṭāb."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4560)، ومسلم (675)."},{"num":11076,"demo":false,"sanad":"","matn":["عن عُثْمَانَ بن أَبِي الْعَاصِ أتى النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وآله وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ الشَّيْطَانَ قَدْ حَالَ بَيْنِي وَبَيْنَ صَلَاتِي وَقِرَاءَتِي، يَلْبِسُهَا عَلَيَّ! فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ذَاكَ شَيْطَانٌ يُقَالُ لَهُ: خِنْزَِبٌ، فَإِذَا أَحْسَسْتَهُ، فَتَعَوَّذْ بِاللهِ مِنْهُ، وَاتْفُِلْ عَلَى يَسَارِكَ ثَلَاثًا. قَالَ: فَفَعَلْتُ ذَلِكَ فَأَذْهَبَهُ اللهُ عَنِّي."],"takhrij":"صحيح: رواه مسلم في السلام (2203) عن يحيى بن خلف الباهلي حدثنا عبدالأعلى، عن سعيد الجريري، عن أبي العلاء، عن عثمان بن أبي العاص فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول من وسوس له الشيطان في صلاته وقراءته","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2203).","chapter_en":"What One Should Say When Satan Whispers during the Prayer and Recitation","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":18,"content":{"translation":{"en":["ʿUthmān ibn Abī al-ʿĀṣ came to the Prophet ﷺ and said: “O Messenger of Allah, Satan has come between me and my prayer and recitation, confusing me during them.” The Messenger of Allah ﷺ said: “That is a devil called Khinzab. When you sense him, seek refuge in Allah from him and spit lightly to your left three times.” He said: “I did that, and Allah removed him from me.”"]},"buhuth":{"en":["The name Khinzab begins with a kasrah on the letter khāʾ, followed by a silent nūn, and then a zāy that may be pronounced with either a kasrah or a fatḥah. It is a name given to this devil, and its literal meaning is a piece of foul-smelling flesh.","The phrase “confusing me during it” means that he mixes up the prayer and causes doubt concerning it.","The words “he has come between me and my prayer” mean that he disturbed the prayer, deprived the worshipper of its sweetness, and prevented him from attaining complete concentration and humility. This explanation was given by al-Nawawī."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2203)."},{"num":11077,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّ رَجُلاً، دَخَلَ الْمَسْجِدَ يَوْمَ جُمُعَةٍ مِنْ بَابٍ كَانَ نَحْوَ دَارِ الْقَضَاءِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يَخْطُبُ، فَاسْتَقْبَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمًا ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ هَلَكَتِ الأَمْوَالُ، وَانْقَطَعَتِ السُّبُلُ، فَادْعُ اللَّهَ يُغِيثُنَا فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، ثُمَّ قَالَ: اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا، اللَّهُمَّ أَغِثْنَا.","قَالَ أَنَسٌ: وَلا وَاللَّهِ مَا نَرَى فِي السَّمَاءِ مِنْ سَحَابٍ وَلَا قَزَعَةً، وَمَا بَيْنَنَا وَبَيْنَ سَلْعٍ مِنْ بَيْتٍ وَلَا دار.قال: فَطَلَعَتْ مِنْ وَرَائِهِ سَحَابَةٌ مِثْلُ التُّرْسِ، فَلَمَّا تَوَسَّطَتِ السَّمَاءَ انْتَشَرَتْ ثُمَّ أَمْطَرَتْ، فَلَا وَاللَّهِ مَا رَأَيْنَا الشَّمْسَ ستا...الحديث.","وفي رواية: اللهم اسقنا، اللهم اسقنا، اللهم اسقنا."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1014)، ومسلم في الاستسقاء (897) كلاهما من طريق إسماعيل بن جعفر، عن شريك بن أبي نمر، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقال في الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1014) and Muslim (897). The alternative wording was narrated by al-Bukhārī (1013).","chapter_en":"What Should Be Said When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Anas ibn Mālik narrated: A man entered the mosque on a Friday through a doorway facing Dār al-Qaḍāʾ while the Messenger of Allah ﷺ was standing and delivering the sermon. The man stood facing the Messenger of Allah ﷺ and said: “O Messenger of Allah, the wealth has been destroyed and the roads have been cut off. Supplicate to Allah to send us relief through rain.” The Messenger of Allah ﷺ raised his hands and said: “O Allah, send us rain. O Allah, send us rain. O Allah, send us rain.” Anas said: “By Allah, we could not see a cloud or even a small patch of cloud in the sky, and there was no house or building between us and Mount Salʿ.” A cloud then appeared from behind it like a shield. When it reached the middle of the sky, it spread and began to rain. Anas said: “By Allah, we did not see the sun for six days…” This forms part of the hadith.","Another narration states: “O Allah, give us rain. O Allah, give us rain. O Allah, give us rain.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1014)، ومسلم (897). والرواية الأخرى رواها البخاري (1013)."},{"num":11078,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: شَكَى النَّاسُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُحُوطَ الْمَطَرِ! فَأَمَرَ بِمِنْبَرٍ، فَوُضِعَ لَهُ فِي الْمُصَلَّى، وَوَعَدَ النَّاسَ يَوْمًا يَخْرُجُونَ فِيهِ، قَالَتْ عَائِشَةُ: فَخَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ بَدَا حَاجِبُ الشَّمْسِ، فَقَعَدَ عَلَى الْمِنْبَرِ، فَكَبَّرَ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَمِدَ اللَّهَ عَزَّ وَجَلَّ، ثُمَّ قَالَ: إِنَّكُمْ شَكَوْتُمْ جَدْبَ دِيَارِكُمْ، وَاسْتِئْخَارَ الْمَطَرِ عَنْ إِبَّانِ زَمَانِهِ عَنْكُمْ، وَقَدْ أَمَرَكُمُ اللَّهُ عَزَّ وَجَلَّ أَنْ تَدْعُوهُ، وَوَعَدَكُمْ أَنْ يَسْتَجِيبَ لَكُمْ. ثُمَّ قَالَ: { الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ * الرَّحْمَنِ الرَّحِيمِ * مَلِكِ يَوْمِ الدِّينِ } لاَ إِلَهَ إِلاَّ اللَّهُ، يَفْعَلُ مَا يُرِيدُ، اللَّهُمَّ! أَنْتَ اللَّهُ لاَ إِلَهَ إِلاَّ أَنْتَ الْغَنِيُّ وَنَحْنُ الْفُقَرَاءُ، أَنْزِلْ عَلَيْنَا الْغَيْثَ، وَاجْعَلْ مَا أَنْزَلْتَ لَنَا قُوَّةً وَبَلاَغًا إِلَى حِينٍ. ثُمَّ رَفَعَ يَدَيْهِ، فَلَمْ يَزَلْ فِي الرَّفْعِ، حَتَّى بَدَا بَيَاضُ إِبْطَيْهِ، ثُمَّ حَوَّلَ عَلَى النَّاسِ ظَهْرَهُ، وَقَلَّبَ أَوْ حَوَّلَ رِدَاءَهُ وَهُوَ رَافِعٌ يَدَيْهِ، ثُمَّ أَقْبَلَ عَلَى النَّاسِ وَنَزَلَ، فَصَلَّى رَكْعَتَيْنِ، فَأَنْشَأَ اللَّهُ سَحَابَةً، فَرَعَدَتْ وَبَرَقَتْ، ثُمَّ أَمْطَرَتْ بِإِذْنِ اللَّهِ، فَلَمْ يَأْتِ مَسْجِدَهُ حَتَّى سَالَتِ السُّيُولُ، فَلَمَّا رَأَى سُرْعَتَهُمْ إِلَى الْكِنِّ ضَحِكَ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ نَوَاجِذُهُ فَقَالَ: أَشْهَدُ أَنَّ اللَّهَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ، وَأَنِّي عَبْدُ اللَّهِ وَرَسُولُهُ."],"takhrij":"حسن: رواه أبو داود (1173) وصحّحه ابن حبان (2860)، والحاكم (1225) حدثنا خالد ابن نِزَار، حدثني القاسم بن مبرور، عن يونس، عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما يقال في الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1173), and authenticated by Ibn Ḥibbān (2860) and al-Ḥākim (1225).","chapter_en":"What Should Be Said When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["ʿĀ’ishah narrated: The people complained to the Messenger of Allah ﷺ about the lack of rain. He ordered that a pulpit be placed for him at the outdoor prayer ground and appointed a day on which the people should gather. ʿĀ’ishah said: The Messenger of Allah ﷺ went out when the edge of the sun appeared. He sat upon the pulpit, proclaimed Allah’s greatness, praised Allah, Mighty and Majestic, and then said: “You have complained of drought in your lands and of the rain being delayed beyond its usual season. Allah, Mighty and Majestic, has commanded you to call upon Him and has promised that He will answer you.” He then said: “All praise belongs to Allah, Lord of the worlds, the Most Compassionate, the Most Merciful, Sovereign of the Day of Judgment. There is no deity worthy of worship except Allah. He does whatever He wills. O Allah, You are Allah. There is no deity worthy of worship except You. You are the Self-Sufficient, while we are the poor and needy. Send rain down upon us, and make what You send a source of strength and provision for us for a time.” He then raised his hands and continued raising them until the whiteness of his armpits became visible. He turned his back toward the people and reversed—or turned—his cloak while continuing to raise his hands. He then faced the people, descended, and prayed two units. Allah then formed a cloud. It thundered and flashed with lightning, and rain fell by Allah’s permission. The Prophet ﷺ had not yet reached the mosque before streams began flowing. When he saw the people hurrying toward shelter, he laughed until his molar teeth became visible and said: “I testify that Allah has power over all things and that I am the servant of Allah and His Messenger.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2953],"tks":"حسن: رواه أبو داود (1173)، وصححه ابن حبان (2860)، والحاكم (1225)."},{"num":11079,"demo":false,"sanad":"","matn":["عَنْ شُرَحْبِيلَ بْنِ السِّمْطِ، أَنَّهُ قَالَ لِكَعْبٍ: يَا كَعْبُ بْنَ مُرَّةَ! حَدِّثْنَا عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَاحْذَرْ. قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! اسْتَسْقِ اللَّهَ، فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ فَقَالَ: اللَّهُمَّ اسْقِنَا غَيْثًا مَرِيئًا مَرِيعًا طَبَقًا عَاجِلاً غَيْرَ رَائِثٍ، نَافِعًا غَيْرَ ضَارٍّ. قَالَ: فَمَا جَمَّعُوا حَتَّى أُجِيبُوا. قَالَ: فَأَتَوْهُ فَشَكَوْا إِلَيْهِ الْمَطَرَ، فَقَالُوا: يَا رَسُولَ اللَّهِ: تَهَدَّمَتِ الْبُيُوتُ. فَقَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا. قَالَ: فَجَعَلَ السَّحَابُ يَنْقَطِعُ يَمِينًا وَشِمَالاً."],"takhrij":"صحيح: رواه ابن ماجه (1269)، وأحمد (18061)، والحاكم (1/328) كلهم من طريق عمرو بن مُرَّة، عن سالم بن أبي الجعد، عن شُرحبيل بن السِّمْط فذكره.وفي لفظ أحمد: طبقا غدقا وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال في الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (1269), Aḥmad (18061), and al-Ḥākim (1/328).","chapter_en":"What Should Be Said When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Shuraḥbīl ibn al-Simṭ said to Kaʿb: “O Kaʿb ibn Murrah, narrate to us from the Messenger of Allah ﷺ, but be cautious and precise.” Kaʿb said: A man came to the Prophet ﷺ and said: “O Messenger of Allah, ask Allah to send us rain.” The Messenger of Allah ﷺ raised his hands and said: “O Allah, send us wholesome, fertile, widespread rain, swiftly and without delay—beneficial and not harmful.” Before the people had dispersed, the land had been revived. They later came to him complaining about the abundance of rain and said: “O Messenger of Allah, the houses have collapsed.” He said: “O Allah, let it fall around us and not upon us.” The clouds then began breaking apart to the right and left."]},"buhuth":{"en":["The word murīʿan means fertile and productive. It is said that a valley has become fertile when abundant vegetation grows within it.","The word ṭabaqan means general and widespread, filling and covering the land like a lid.","The expression “without delay” means neither late nor slow in arriving."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2954],"tks":"صحيح: رواه ابن ماجه (1269)، وأحمد (18061)، والحاكم (1/328)."},{"num":11080,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: أَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَوَاكِي، فَقَالَ: اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا مَرِيعاً نَافِعًا غَيْرَ ضَارٍّ، عَاجِلاً غَيْرَ آجِلٍ. قَالَ: فَأَطْبَقَتْ عَلَيْهِمُ السَّمَاءُ."],"takhrij":"صحيح: رواه أبو داود (1169) وصحّحه ابن خزيمة (1416)، والحاكم (1222) كلهم من طريق محمد بن عبيد، حدثنا مسعر، عن يزيد الفقير، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال في الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1169), and authenticated by Ibn Khuzaymah (1416) and al-Ḥākim (1222).","chapter_en":"What Should Be Said When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: Weeping people came to the Prophet ﷺ, so he said: “O Allah, send us relieving, wholesome, fertile, beneficial rain that causes no harm—quickly and without delay.” The sky then became completely covered with clouds above them."]},"buhuth":{"en":["The word bawākī is the plural of bākiyah, meaning that weeping people—or weeping women—came to him."]}},"tuhfa":{},"full":1,"dr":1,"rep":[2955],"tks":"صحيح: رواه أبو داود (1169)، وصححه ابن خزيمة (1416)، والحاكم (1222)."},{"num":11081,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ! لَقَدْ جِئْتُكَ مِنْ عِنْدِ قَوْمٍ مَا يَتَزَوَّدُ لَهُمْ رَاعٍ، وَلاَ يَخْطِرُ لَهُمْ فَحْلٌ. فَصَعِدَ الْمِنْبَرَ، فَحَمِدَ اللَّهَ ثُمَّ قَالَ: اللَّهُمَّ اسْقِنَا غَيْثًا مُغِيثًا مَرِيئًا طَبَقًا مَرِيعًا غَدَقًا، عَاجِلاً غَيْرَ رَائِثٍ. ثُمَّ نَزَلَ فَمَا يَأْتِيهِ أَحَدٌ مِنْ وَجْهٍ مِنَ الْوُجُوهِ إِلاَّ قَالُوا قَدْ أُحْيِينَا."],"takhrij":"صحيح: رواه ابن ماجه (1270) عن محمد بن أبي القاسم أبي الأحوص، قال: حدثنا الحسن بن الربيع، قال: حدثنا عبدالله بن إدريس، قال: حدثنا حصين، عن حبيب بن أبي ثابت، عن ابن عباس فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال في الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (1270).","chapter_en":"What Should Be Said When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["Ibn ʿAbbās narrated: A Bedouin came to the Prophet ﷺ and said: “O Messenger of Allah, I have come to you from a people whose shepherd has nothing to take as provisions and whose male livestock no longer even moves among the herd.” The Prophet ﷺ ascended the pulpit, praised Allah, and then said: “O Allah, send us relieving, wholesome, widespread, fertile, abundant rain—quickly and without delay.” He then descended. No one came to him from any direction except that they said: “Our land has been revived.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[2956],"tks":"صحيح: رواه ابن ماجه (1270)."},{"num":11082,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَسْقَى قَالَ: اللَّهُمَّ اسْقِ عِبَادَكَ وَبَهَائِمَكَ، وَانْشُرْ رَحْمَتَكَ، وَأَحْىِ بَلَدَكَ الْمَيِّتَ."],"takhrij":"حسن: رواه أبو داود (1176) عن سهل بن صالح، حدثنا علي بن قادم، أخبرنا سفيان، عن يحيى بن سعيد، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ما يقال في الاستسقاء","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1176).","chapter_en":"What Should Be Said When Seeking Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":19,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather: When the Messenger of Allah ﷺ sought rain, he would say: “O Allah, give water to Your servants and Your animals, spread Your mercy, and revive Your dead land.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (1176)."},{"num":11083,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَأَى الْمَطَرَ قَالَ: صَيِّبًا نَافِعًا."],"takhrij":"صحيح: رواه البخاري في الاستسقاء (1032) عن محمد بن مقاتل أبو الحسن المروزي، أخبرنا عبد الله (هو ابن المبارك)، أخبرنا عبيد الله، عن نافع، عن القاسم بن محمد، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رأى المطر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1032).","chapter_en":"What One Should Say upon Seeing Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["ʿĀ’ishah narrated: When the Messenger of Allah ﷺ saw rain, he would say: “May it be beneficial, pouring rain.”"]},"buhuth":{"en":["The word ṣayyiban means rain that pours down abundantly and continuously. Its original root contains the letter wāw, which was changed into a yāʾ."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11890],"tks":"صحيح: رواه البخاري (1032)."},{"num":11084,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا كَانَ يَوْمُ الرِّيحِ وَالْغَيْمِ، عُرف ذَلِكَ فِي وَجْهِهِ، وَأَقْبَلَ وَأَدْبَرَ، فَإِذَا مَطَرَتْ سُرَّ بِهِ وَذَهَبَ عَنْهُ ذَلِكَ.","قَالَتْ عَائِشَةُ: فَسَأَلْتُهُ فَقَالَ: إِنِّي خَشِيتُ أَنْ يَكُونَ عَذَابًا سُلِّطَ عَلَى أمتي.ويقول إِذَا رَأَى الْمَطَرَ: رَحْمَةٌ."],"takhrij":"صحيح: رواه مسلم في صلاة الاستسقاء (899: 14) عن عبدالله بن مسلمة بن قعنب حدثنا سليمان بن بلال، عن جعفر بن محمد، عن عطاء بن أبي رباح أنه سمع عائشة تقول:فذكرته.","grade":"صحيح","chapter_ar":"باب ما يقول إذا رأى المطر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (899/14).","chapter_en":"What One Should Say upon Seeing Rain","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":20,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, narrated: Whenever there was strong wind and cloud, its effect could be seen upon the face of the Messenger of Allah ﷺ. He would move forward and backward anxiously. When rain began to fall, he became pleased and his concern disappeared. ʿĀ’ishah said: I asked him about this, and he replied: “I feared that it might be a punishment sent upon my nation.” When he saw the rain, he would say: “It is mercy.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (899: 14)."},{"num":11085,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ: أَنَّ رَجُلاً دَخَلَ يَوْمَ الْجُمُعَةِ مِنْ بَابٍ كَانَ نَحْوَ دار الْقَضَاءِ، وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يَخْطُبُ ... الحديث. ثُمَّ دَخَلَ رَجُلٌ مِنْ ذَلِكَ الْبَابِ فِي الْجُمُعَةِ (يَعْنِي المقبلة) وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يَخْطُبُ فَاسْتَقْبَلَهُ قَائِمًا فَقَالَ: يَا رَسُولَ اللَّهِ هَلَكَتِ الأَمْوَالُ، وَانْقَطَعَتِ السُّبُلُ، فَادْعُ اللَّهَ يُمْسِكْهَا عَنَّا، قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، ثُمَّ قَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا، اللَّهُمَّ عَلَى الآكَامِ، وَالظِّرَابِ، وَبُطُونِ الأَوْدِيَةِ، وَمَنَابِتِ الشَّجَرِ.قَالَ فَأَقْلَعَتْ، وَخَرَجْنَا نَمْشِي فِي الشَّمْسِ. قـال شَرِيكٌ: فسألت أَنَسَ بْنَ مَالِكٍ أَهُوَ الرَّجُلُ الأَوَّلُ؟ قَالَ: مَا أَدْرِي."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1014)، ومسلم في الاستسقاء (897) كلاهما من طريق إسماعيل بن جعفر، عن شريك بن أبي نمر، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقال إذا كثر المطر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1014) and Muslim (897).","chapter_en":"What Should Be Said When Rain Becomes Excessive","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":21,"content":{"translation":{"en":["Anas ibn Mālik narrated: A man entered on Friday through a doorway facing Dār al-Qaḍāʾ while the Messenger of Allah ﷺ was standing and delivering the sermon. The remainder of the earlier incident was then mentioned. On the following Friday, a man entered through the same doorway while the Messenger of Allah ﷺ was standing and delivering the sermon. He stood facing him and said: “O Messenger of Allah, the wealth has been destroyed and the roads have been cut off. Supplicate to Allah to withhold the rain from us.” The Messenger of Allah ﷺ raised his hands and said: “O Allah, let it fall around us and not upon us. O Allah, let it fall upon the hills, the small mountains, the valleys, and the places where trees grow.” The rain then stopped, and we went out walking in the sunlight. Sharīk said: I asked Anas ibn Mālik: “Was this the same man who had come the first time?” He replied: “I do not know.”"]},"buhuth":{"en":["The word ākām is the plural of akamah, meaning a raised hill.","The word ẓirāb refers to small mountains. Its singular is ẓarib."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1014)، ومسلم (897)."},{"num":11086,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُنَا الاِسْتِخَارَةَ فِي الأُمُورِ كُلِّهَا كَالسُّورَةِ مِنَ الْقُرْآنِ، إِذَا هَمَّ بِالأَمْرِ، فَلْيَرْكَعْ رَكْعَتَيْنِ، ثُمَّ يَقُولُ: اللَّهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ الْعَظِيمِ، فَإِنَّكَ تَقْدِرُ وَلاَ أَقْدِرُ، وَتَعْلَمُ وَلاَ أَعْلَمُ، وَأَنْتَ عَلاَّمُ الْغُيُوبِ، اللَّهُمَّ إِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ خَيْرٌ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي -أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ- فَاقْدُرْهُ لِي، وَإِنْ كُنْتَ تَعْلَمُ أَنَّ هَذَا الأَمْرَ شَرٌّ لِي فِي دِينِي وَمَعَاشِي وَعَاقِبَةِ أَمْرِي -أَوْ قَالَ فِي عَاجِلِ أَمْرِي وَآجِلِهِ- فَاصْرِفْهُ عَنِّي وَاصْرِفْنِي عَنْهُ، وَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ كَانَ، ثُمَّ رَضِّنِي بِهِ، وَيُسَمِّي حَاجَتَهُ.وَزَادَ فِي رِوَايَةِ: مَنْ غَيْرِ الْفَرِيضَةِ."],"takhrij":"صحيح: رواه البخاري في الدعوات (6382) عن مطرف بن عبد الله بن أبي مصعب، ثنا عبد الرحمن بن أبي الموال، عن محمد بن المنكدر، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب دعاء صلاة الاستخارة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6382). The alternative wording is also narrated by him (1162).","chapter_en":"The Supplication of the Prayer of Seeking Guidance","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["Jābir narrated: The Prophet ﷺ would teach us how to seek Allah’s guidance in all matters just as he would teach us a sūrah from the Qur’an. He said: “When he intends to undertake a matter, let him pray two units and then say: ʿO Allah, I seek the better choice through Your knowledge, and I seek ability through Your power. I ask You from Your immense bounty, for You are able while I am not, You know while I do not, and You are the Knower of all unseen things. O Allah, if You know that this matter is good for me in my religion, my livelihood, and the final outcome of my affair—or he said: in my immediate and future affairs—then decree it for me. If You know that this matter is harmful for me in my religion, my livelihood, and the final outcome of my affair—or he said: in my immediate and future affairs—then turn it away from me and turn me away from it. Decree good for me wherever it may be, and then make me content with it.’” He should then mention his particular need. Another narration adds: “Two units other than the obligatory prayer.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (6382). والرواية الأخرى له bukhari(1162)."},{"num":11087,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا أَرَادَ أَحَدُكُمْ أَمْرًا، فَلْيَقُلِ: اللهُمَّ إِنِّي أَسْتَخِيرُكَ بِعِلْمِكَ، وَأَسْتَقْدِرُكَ بِقُدْرَتِكَ، وَأَسْأَلُكَ مِنْ فَضْلِكَ، فَإِنَّكَ تَقْدِرُ وَلَا أَقْدِرُ، وَتَعْلَمُ وَلَا أَعْلَمُ، وَأَنْتَ عَلَاّمُ الْغُيُوبِ، اللهُمَّ إِنْ كَانَ كَذَا وَكَذَا خَيْرًا لِي فِي دِينِي، وَخَيْرًا لِي فِي مَعِيشَتِي، وَخَيْرًا لِي فِي عَاقِبَةِ أَمْرِي، فَاقْدُرْهُ لِي، وَبَارِكْ لِي فِيهِ، وَإِنْ كَانَ غَيْرُ ذَلِكَ خَيْرًا لِي، فَاقْدُرْ لِيَ الْخَيْرَ حَيْثُ مَا كَانَ، وَرَضِّنِي بِقَدَرِكَ."],"takhrij":"حسن: رواه ابن حبان (886)، والبخاري في تاريخه (2727)، والطبراني في الدعاء (1306) كلهم من طرق عن ابن أبي فُديك، قال: حدثنا أبو المفضَّل بن العلاء بن عبدالرحمن، عن أبيه، عن جدّه، عن أبي هريرة فذكره.واللفظ لابن حبان.","grade":"حسن","chapter_ar":"باب دعاء صلاة الاستخارة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (886), al-Bukhārī in al-Tārīkh (4/258), and al-Ṭabarānī in al-Duʿāʾ (1306).","chapter_en":"The Supplication of the Prayer of Seeking Guidance","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":22,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you intends to undertake a matter, let him say: ʿO Allah, I seek the better choice through Your knowledge, and I seek ability through Your power. I ask You from Your immense bounty, for You are able while I am not, You know while I do not, and You are the Knower of all unseen things. O Allah, if such-and-such a matter is good for me in my religion, good for me in my livelihood, and good for me in the final outcome of my affair, then decree it for me and bless it for me. If something else is better for me, then decree good for me wherever it may be and make me content with Your decree.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3000],"tks":"حسن: رواه ابن حبان (886)، والبخاري في التاريخ (2727)، والطبراني في الدعاء (1306)."},{"num":11088,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ زوج النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَتْ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ فِي سُجُودِ الْقُرْآنِ بِاللَّيْلِ: سَجَدَ وَجْهِي لِلَّذِي خَلَقَهُ، وَشَقَّ سَمْعَهُ وَبَصَرَهُ بِحَوْلِهِ وَقُوَّتِهِ. وَزَادَ فِي رِوَايَةِ فَتَبَارَكَ اللَّهُ أَحْسَنُ الْخَالِقِينَ."],"takhrij":"صحيح: رواه الترمذي (580)، والنسائي (1129)، والحاكم (802) كلهم من طريق عبد الوهاب الثقفي، عن خالد الحذاء، عن أبي العالية، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يقول في سجود القرآن","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (580), al-Nasā’ī (1129), and al-Ḥākim (802).","chapter_en":"What Should Be Said during a Prostration of Qur’anic Recitation","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأذان والصلاة وما يتعلق بها","group_en":"Collection of Narrations Concerning the Supplications of the Call to Prayer, the Prayer, and Matters Related to Them","part_no":54,"group_no":8,"chapter_no":23,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, narrated: During the prostration of Qur’anic recitation at night, the Messenger of Allah ﷺ would say: “My face has prostrated before the One who created it and opened its hearing and sight by His power and strength.” Another narration adds: “Blessed is Allah, the Best of creators.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (580)، والنسائي (1129)، والحاكم (802)."},{"num":11089,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى أَعْرَابِيٍّ يَعُودُهُ ـ قَالَ: ـ وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ عَلَى مَرِيضٍ يَعُودُهُ فَقَالَ لَهُ: لاَ بَأْسَ طَهُورٌ إِنْ شَاءَ اللَّهُ. قَالَ: قُلْتَ: طَهُورٌ، كَلاَّ بَلْ هِيَ حُمَّى تَفُورُ ـ أَوْ تَثُورُ ـ عَلَى شَيْخٍ كَبِيرٍ، تُزِيرُهُ الْقُبُورَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَنَعَمْ إِذًا."],"takhrij":"صحيح: رواه البخاري في المرضى (5656) عن معلى بن أسد، حدثنا عبدالعزيز بن مختار، حدثنا خالد، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقال عند عيادة المريض","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5656).","chapter_en":"What Should Be Said When Visiting the Sick","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ entered upon a Bedouin to visit him during his illness. Whenever the Prophet ﷺ visited a sick person, he would say: “There is no harm. It is a purification, Allah willing.” The Bedouin replied: “A purification? No! Rather, it is a fever boiling—or raging—upon an elderly man, causing him to visit the graves.” The Prophet ﷺ said: “Then so it shall be.”"]},"buhuth":{"en":["The expression “causing him to visit” means compelling him to make the visit without his choosing it."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5656)."},{"num":11090,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ: أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى أَعْرَابِيٍّ يَعُودُهُ، وَهُوَ مَحْمُومٌ، فَقَالَ: كَفَّارَةٌ وَطَهُورٌ، فَقَالَ الْأَعْرَابِيُّ: بَلْ حُمَّى تَفُورُ، عَلَى شَيْخٍ كَبِيرٍ، تُزِيرُهُ الْقُبُورَ، فَقَامَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَتَرَكَهُ."],"takhrij":"حسن: رواه أحمد (13616) عن عفان، حدثنا حماد بن سلمة، حدثنا أبو ربيعة، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند عيادة المريض","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (13616).","chapter_en":"What Should Be Said When Visiting the Sick","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ entered upon a Bedouin to visit him while he was suffering from fever. He said: “It is an expiation and a purification.” The Bedouin replied: “Rather, it is a fever boiling upon an elderly man, causing him to visit the graves.” The Messenger of Allah ﷺ then stood and left him."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3474],"tks":"حسن: رواه أحمد (13616)."},{"num":11091,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عَمْرٍو رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: إِذَا جَاءَ الرَّجُلُ يَعُودُ مَرِيضًا فَلْيَقُلِ: اللَّهُمَّ اشْفِ عَبْدَكَ يَنْكَأُ لَكَ عَدُوًّا، أَوْ يَمْشِي لَكَ إِلَى صَلَاةٍ."],"takhrij":"حسن: رواه أبو داود (3107) عن يزيد بن خالد الرملي، حدثنا ابن وهب، عن حُيي بن عبدالله، عن أبي عبدالرحمن الحُبُلي، عن عبد الله بن عمرو بن العاص فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند عيادة المريض","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3107), and authenticated by Ibn Ḥibbān (2974) and al-Ḥākim (1/344, 549).","chapter_en":"What Should Be Said When Visiting the Sick","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAmr ibn al-ʿĀṣ narrated that the Messenger of Allah ﷺ said: “When a man visits a sick person, let him say: ‘O Allah, heal Your servant, so that he may wound an enemy for Your sake or walk in a funeral procession for Your sake.’”"]},"buhuth":{"en":["The word yankaʾ means to inflict extensive wounds and losses upon the enemy."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3107)، وصححه ابن حبان (2974)، والحاكم (1/344، 549)."},{"num":11092,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لقِّنوا مَوْتَاكُمْ: لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"صحيح: رواه مسلم في الجنائز (916) من طرق عن بشر بن المفضل، عن عمارة بن غزية، حدثنا يحيى بن عمارة، قال: سمعت أبا سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقين المحتضر كلمة التوحيد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (916).","chapter_en":"Prompting the Dying Person to Say the Declaration of Allah’s Oneness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated that the Messenger of Allah ﷺ said: “Prompt your dying people to say: ‘There is no deity worthy of worship except Allah.’”"]},"buhuth":{"en":["The words “your dying people” refer to those who are approaching death, not those who have already died. The purpose of prompting them is so that their final words may be:","“There is no deity worthy of worship except Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3492],"tks":"صحيح: رواه مسلم (916)."},{"num":11093,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَقِّنُوا مَوْتَاكُمْ لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"صحيح: رواه مسلم في الجنائز (917) من طرق عن أبي خالد الأحمر، عن يزيد بن كيسان، عن أبي حازم، عن أبي هريرة فذكر الحديث.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقين المحتضر كلمة التوحيد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (917).","chapter_en":"Prompting the Dying Person to Say the Declaration of Allah’s Oneness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “Prompt your dying people to say: ‘There is no deity worthy of worship except Allah.’”"]},"buhuth":{"en":["Ibn Ḥibbān also narrated it in his Ṣaḥīḥ (3004) through another chain from Abū Hurayrah, who narrated that the Messenger of Allah ﷺ said:","“Prompt your dying people to say: ‘There is no deity worthy of worship except Allah,’ for whoever’s final words at death are ‘There is no deity worthy of worship except Allah’ will enter Paradise at some point in time, even if he is afflicted before that with whatever he may be afflicted.”","Its chain of transmission is authentic."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3493,12954],"tks":"صحيح: رواه مسلم (917)."},{"num":11094,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَقِّنُوا هَلْكَاكُمْ قَوْلَ لاَ إِلَهَ إِلاَّ اللَّهُ."],"takhrij":"صحيح: رواه النسائي (1827) عن إبراهيم بن يعقوب، قال: حدثني أحمد بن إسحاق، قال: حدثنا وُهيب، قال: حدثنا منصور بن صفية، عن أمه صفية بنت شيبة، عن عائشة فذكرتِ الحديث.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقين المحتضر كلمة التوحيد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (1827).","chapter_en":"Prompting the Dying Person to Say the Declaration of Allah’s Oneness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated that the Messenger of Allah ﷺ said: “Prompt those among you who are nearing death to say: ‘There is no deity worthy of worship except Allah.’”"]}},"tuhfa":{},"full":1,"rep":[3494],"tks":"صحيح: رواه النسائي (1827)."},{"num":11095,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَفَعَهُ قَالَ: لَقِّنُوا مَوْتَاكُمْ لَا إِلَهَ إِلَّا اللَّهُ، فَإِنَّ نَفْسَ الْمُؤْمِنِ تَخْرُجُ رَشْحًا، وَنَفْسُ الْكَافِرِ تَخْرُجُ مِنْ شِدْقِهِ كَمَا تَخْرُجُ نَفْسُ الْحِمَارِ."],"takhrij":"حسن: رواه الطبراني في الكبير (10417) عن عبدان بن أحمد، ثنا سليمان بن أيوب صاحب البصري، ثنا حماد بن زيد، عن عاصم، عن أبي وائل، عن عبدالله فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تلقين المحتضر كلمة التوحيد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (10/233).","chapter_en":"Prompting the Dying Person to Say the Declaration of Allah’s Oneness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Prophet ﷺ said: “Prompt your dying people to say: ‘There is no deity worthy of worship except Allah.’ The soul of a believer departs with perspiration, while the soul of a disbeliever emerges from the side of his mouth as the soul of a donkey departs.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3495],"tks":"حسن: رواه الطبراني في الكبير (10417)."},{"num":11096,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ عَلَى رَجُلٍ مِنْ بَنِي النَّجَّارِ يَعُودُهُ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا خَالُ، قُلْ: لَا إِلَهَ إِلَّا اللَّهُ فَقَالَ: أَوَ خَالٌ أَنَا، أَوْ عَمٌّ؟ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَا، بَلْ خَالٌ، فَقَالَ لَهُ: قُلْ: لَا إِلَهَ إِلَّا هُوَ، قَالَ: خَيْرٌ لِي؟ قَالَ: نَعَمْ."],"takhrij":"صحيح: رواه أحمد (12543، 12563، 13826) والبزار كشف الأستار (787)، وأبو يعلى (3512) كلهم من طريق حماد بن سلمة، عن ثابت البناني، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تلقين المحتضر كلمة التوحيد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (12543, 12563, 13826), al-Bazzār in Kashf al-Astār (787), and Abū Yaʿlā (3512).","chapter_en":"Prompting the Dying Person to Say the Declaration of Allah’s Oneness","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ entered upon a man from Banū al-Najjār to visit him during his illness. The Messenger of Allah ﷺ said to him: “O maternal uncle, say: ‘There is no deity worthy of worship except Allah.’” The man asked: “Am I your maternal uncle or your paternal uncle?” The Prophet ﷺ replied: “No, rather, you are my maternal uncle.” He then said to him: “Say: ‘There is no deity worthy of worship except Him.’” The man asked: “Is that better for me?” He replied: “Yes.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3498],"tks":"صحيح: رواه أحمد (12543، 12563، 13826)، والبزار في كشف الأستار (787)، وأبو يعلى (3512)."},{"num":11097,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا أَخْبَرَتْهُ  أَنَّهَا سَمِعَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ قَبْلَ أَنْ يَمُوتَ وَهُوَ مُسْنِدٌ إِلَى صَدْرِهَا، وَأَصْغَتْ إِلَيْهِ وَهُوَ يَقُولُ: اللَّهُمَّ اغْفِرْ لِي، وَارْحَمْنِي، وَأَلْحِقْنِي بِالرَّفِيقِ ."],"takhrij":"متفق عليه: رواه مالك في الجنائز (46) عن هشام بن عروة، عن عبَّاد بن عبدالله بن الزبير، أن عائشة زوج النبي صلى الله عليه وسلم أخْبرته، أنها سمعتْ فذكرته.","grade":"متفق عليه","chapter_ar":"باب دعاء المريض إذا شعر بقرب موته","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (46), Muslim (2444), and al-Bukhārī (4440).","chapter_en":"The Supplication of a Sick Person Who Senses That Death Is Near","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":3,"content":{"translation":{"en":["ʿĀ’ishah narrated that before the Messenger of Allah ﷺ died, while he was leaning against her chest, she listened closely and heard him say: “O Allah, forgive me, have mercy upon me, and join me with the Highest Companion.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3517,10390],"tks":"متفق عليه: رواه مالك (46)، ومسلم (2444)، والبخاري (4440)."},{"num":11098,"demo":false,"sanad":"","matn":["عَنِ الأَغَرِّ أَبِي مُسْلِمٍ، قَالَ أَشْهَدُ عَلَى أَبِي سَعِيدٍ وَأَبِي هُرَيْرَةَ أَنَّهُمَا شَهِدَا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَاللَّهُ أَكْبَرُ. صَدَّقَهُ رَبُّهُ فَقَالَ: لاَ إِلَهَ إِلاَّ أَنَا وَأَنَا أَكْبَرُ. وَإِذَا قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ. قَالَ: يَقُولُ اللَّهُ: لاَ إِلَهَ إِلاَّ أَنَا وَأَنَا وَحْدِي. وَإِذَا قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَحْدَهُ لاَ شَرِيكَ لَهُ. قَالَ اللَّهُ: لاَ إِلَهَ إِلاَّ أَنَا وَحْدِي لاَ شَرِيكَ لِي. وَإِذَا قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ. قَالَ اللَّهُ: لاَ إِلَهَ إِلاَّ أَنَا لِيَ الْمُلْكُ وَلِيَ الْحَمْدُ. وَإِذَا قَالَ: لاَ إِلَهَ إِلاَّ اللَّهُ وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِاللَّهِ. قَالَ اللَّهُ: لاَ إِلَهَ إِلاَّ أَنَا وَلاَ حَوْلَ وَلاَ قُوَّةَ إِلاَّ بِي. وَكَانَ يَقُولُ: مَنْ قَالَهَا فِي مَرَضِهِ ثُمَّ مَاتَ لَمْ تَطْعَمْهُ النَّارُ."],"takhrij":"صحيح: رواه الترمذي (3430) من طريق عبد الجبار بن العباس- والنسائي في عمل اليوم والليلة (30)، وابن ماجه (3794) من طريق حمزة الزيات- والنسائي (31)، وصحّحه ابن حبان (851)، والحاكم (8) من طريق إسرائيل- والنسائي (348) من طريق زهير- أربعتهم عن أبي إسحاق، عن الأغر أبي مسلم فذكره.","grade":"صحيح","chapter_ar":"باب ذكر الدعاء الذي إذا قاله المريض في مرضه ثم مات لم تطعمه النار","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3430), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (30), Ibn Mājah (3794), and al-Nasā’ī (31); authenticated by Ibn Ḥibbān (851) and al-Ḥākim (8). Al-Nasā’ī also narrated it (348).","chapter_en":"The Supplication Which, If Said by a Sick Person Who Then Dies, Prevents the Fire from Consuming Him","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":4,"content":{"translation":{"en":["Al-Agharr Abū Muslim said: I bear witness concerning Abū Saʿīd and Abū Hurayrah that they both bore witness that the Prophet ﷺ said: “Whoever says, ‘There is no deity worthy of worship except Allah, and Allah is the Greatest,’ his Lord confirms him and says: ‘There is no deity worthy of worship except Me, and I am the Greatest.’ When he says, ‘There is no deity worthy of worship except Allah alone,’ Allah says: ‘There is no deity worthy of worship except Me alone.’ When he says, ‘There is no deity worthy of worship except Allah alone, without partner,’ Allah says: ‘There is no deity worthy of worship except Me alone, and I have no partner.’ When he says, ‘There is no deity worthy of worship except Allah; to Him belong all sovereignty and all praise,’ Allah says: ‘There is no deity worthy of worship except Me; to Me belong all sovereignty and all praise.’ When he says, ‘There is no deity worthy of worship except Allah, and there is no power and no strength except through Allah,’ Allah says: ‘There is no deity worthy of worship except Me, and there is no power and no strength except through Me.’” The Prophet ﷺ would also say: “Whoever says these words during his illness and then dies, the Fire will not consume him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3430)، والنسائي في عمل اليوم والليلة (30)، وابن ماجه (3794)، والنسائي (31)، وصححه ابن حبان (851)، والحاكم (8)، ورواه النسائي أيضا (348)."},{"num":11099,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ:  دَخَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى أَبِي سَلَمَةَ، وَقَدْ شَقَّ بَصَرُهُ، فَأَغْمَضَهُ، ثُمَّ قَالَ: إِنَّ الرُّوحَ إِذَا قُبِضَ تَبِعَهُ الْبَصَرُ، فَضَجَّ نَاسٌ مِنْ أَهْلِهِ، فَقَالَ: لَا تَدْعُوا عَلَى أَنْفُسِكُمْ إِلَّا بِخَيْرٍ، فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ، ثُمَّ قَالَ: اللَّهُمَّ اغْفِرْ لِأَبِي سَلَمَةَ، وَارْفَعْ دَرَجَتَهُ فِي الْمَهْدِيِّينَ، وَاخْلُفْهُ فِي عَقِبِهِ فِي الْغَابِرِينَ، وَاغْفِرْ لَنَا وَلَهُ يَا رَبَّ الْعَالَمِينَ، وَافْسَحْ لَهُ فِي قَبْرِهِ، وَنَوِّرْ لَهُ فِيهِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (920) عن زهير بن حرب، حدثنا معاوية بن عمرو، حدثنا أبو إسحاق الفزاري، عن خالد الحذاء، عن أبي قلابة، عن قبيصة بن ذُؤيب، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب الدعاء عند إغماض بصر الميت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (920).","chapter_en":"The Supplication Recited When Closing the Eyes of the Deceased","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":5,"content":{"translation":{"en":["Umm Salamah, the wife of the Prophet ﷺ, narrated: The Messenger of Allah ﷺ entered upon Abū Salamah after his eyes had become fixed open. He closed them and then said: “When the soul is taken, the sight follows it.” Some members of his family began crying out loudly. The Prophet ﷺ said: “Do not supplicate against yourselves except with good words, for the angels say ‘Āmīn’ to whatever you say.” He then said: “O Allah, forgive Abū Salamah, raise his rank among the rightly guided, and take care of those he has left behind among those who remain. Forgive us and him, O Lord of the worlds. Make his grave spacious for him and illuminate it for him.”"]}},"tuhfa":{},"full":1,"rep":[3534,10340],"tks":"صحيح: رواه مسلم (920)."},{"num":11100,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ، أَنَّهَا قَالَتْ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  مَا مِنْ مُسْلِمٍ تُصِيبُهُ مُصِيبَةٌ فَيَقُولُ مَا أَمَرَهُ اللَّهُ: إِنَّا لِلهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ، اللَّهُمَّ أْجُرْنِي فِي مُصِيبَتِي، وَأَخْلِفْ لِي خَيْرًا مِنْهَا، إِلَّا أَخْلَفَ اللهُ لَهُ خَيْرًا مِنْهَا.","قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ قُلْتُ: أَيُّ الْمُسْلِمِينَ خَيْرٌ مِنْ أَبِي سَلَمَةَ؟ أَوَّلُ بَيْتٍ هَاجَرَ إِلَى رَسُولِ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ ثُمَّ إِنِّي قُلْتُهَا فَأَخْلَفَ اللهُ لِي رَسُولَ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ.","قَالَتْ: أَرْسَلَ إِلَيَّ رَسُولُ اللهِ صَلَّى اللهُ عَلَيْهِ وَسَلَّمَ حَاطِبَ بْنَ أَبِي بَلْتَعَةَ يَخْطُبُنِي لَهُ، فَقُلْتُ: إِنَّ لِي بِنْتًا وَأَنَا غَيُورٌ، فَقَالَ: أَمَّا ابْنَتُهَا فَنَدْعُو اللهَ أَنْ يُغْنِيَهَا عَنْهَا، وَأَدْعُو اللهَ أَنْ يَذْهَبَ بِالْغَيْرَةِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (918) من طرق عن إسماعيل بن جعفر، أخبرني سعد بن سعيد، عن عمر بن كثير بن أفلح، عن ابن سفينة، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يقال عند المصيبة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (918).","chapter_en":"What Should Be Said When a Calamity Occurs","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Umm Salamah narrated: I heard the Messenger of Allah ﷺ say: “No Muslim is afflicted by a calamity and then says what Allah has commanded: ‘Indeed, we belong to Allah, and indeed, to Him we shall return. O Allah, reward me for my calamity and replace it for me with something better,’ except that Allah replaces it for him with something better.” She said: When Abū Salamah died, I said: “Which Muslim could be better than Abū Salamah, the first household to migrate to the Messenger of Allah ﷺ?” Nevertheless, I said the supplication, and Allah replaced him for me with the Messenger of Allah ﷺ. She said: The Messenger of Allah ﷺ sent Ḥāṭib ibn Abī Baltaʿah to propose marriage to me on his behalf. I said: “I have a daughter, and I am intensely jealous.” He said: “As for her daughter, we shall supplicate to Allah to make her independent of her, and I shall supplicate to Allah to remove her jealousy.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿الَّذِينَ إِذَا أَصَابَتْهُمْ مُصِيبَةٌ قَالُوا إِنَّا لِلّٰهِ وَإِنَّا إِلَيْهِ رَاجِعُونَ ۝ أُولَٰئِكَ عَلَيْهِمْ صَلَوَاتٌ مِنْ رَبِّهِمْ وَرَحْمَةٌ، وَأُولَٰئِكَ هُمُ الْمُهْتَدُونَ﴾ [سورة البقرة: ١٥٦-١٥٧]."],"en":["Allah, the Exalted, said:","“Those who, when a calamity befalls them, say, ‘Indeed, we belong to Allah, and indeed, to Him we shall return.’ Those are the ones upon whom are blessings and mercy from their Lord, and it is they who are rightly guided.”","[Sūrat al-Baqarah 2:156–157]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[9413,11932],"tks":"صحيح: رواه مسلم (918)."},{"num":11101,"demo":false,"sanad":"","matn":["عَنْ أُمِّ سَلَمَةَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا حَضَرْتُمُ الْمَرِيضَ، أَوِ الْمَيِّتَ، فَقُولُوا خَيْرًا، فَإِنَّ الْمَلَائِكَةَ يُؤَمِّنُونَ عَلَى مَا تَقُولُونَ، قَالَتْ: فَلَمَّا مَاتَ أَبُو سَلَمَةَ أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ أَبَا سَلَمَةَ قَدْ مَاتَ، قَالَ: قُولِي: اللَّهُمَّ اغْفِرْ لِي وَلَهُ، وَأَعْقِبْنِي مِنْهُ عُقْبَى حَسَنَةً، قَالَتْ: فَقُلْتُ، فَأَعْقَبَنِي اللهُ مَنْ هُوَ خَيْرٌ لِي مِنْهُ، مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الجنائز (919) من طرق عن أبي معاوية، عن الأعمش، عن شعبة، عن أم سلمة فذكرته.","grade":"صحيح","chapter_ar":"باب ما يقال عند المصيبة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (919).","chapter_en":"What Should Be Said When a Calamity Occurs","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":6,"content":{"translation":{"en":["Umm Salamah narrated that the Messenger of Allah ﷺ said: “When you are present with a sick or deceased person, say only good things, for the angels say ‘Āmīn’ to whatever you say.” She said: When Abū Salamah died, I went to the Prophet ﷺ and said: “O Messenger of Allah, Abū Salamah has died.” He said: “Say: ‘O Allah, forgive me and him, and grant me a good successor after him.’” She said: I said it, and Allah granted me someone better than him as a successor: Muḥammad ﷺ."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (919)."},{"num":11102,"demo":false,"sanad":"","matn":["عَنْ أُسَامَةَ بْنِ زَيْدٍ، قَالَ: كُنَّا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ جَاءَهُ رَسُولُ إِحْدَى بَنَاتِهِ يَدْعُوهُ إِلَى ابْنِهَا فِي الْمَوْتِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ارْجِعْ فَأَخْبِرْهَا أَنَّ لِلَّهِ مَا أَخَذَ، وَلَهُ مَا أَعْطَى، وَكُلُّ شَىْءٍ عِنْدَهُ بِأَجَلٍ مُسَمًّى، فَمُرْهَا فَلْتَصْبِرْ وَلْتَحْتَسِبْ. فَأَعَادَتِ الرَّسُولَ أَنَّهَا أَقْسَمَتْ لَتَأْتِيَنَّهَا، فَقَامَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَامَ مَعَهُ سَعْدُ بْنُ عُبَادَةَ وَمُعَاذُ بْنُ جَبَلٍ، فَدُفِعَ الصَّبِيُّ إِلَيْهِ وَنَفْسُهُ تَقَعْقَعُ كَأَنَّهَا فِي شَنٍّ، فَفَاضَتْ عَيْنَاهُ فَقَالَ لَهُ سَعْدٌ: يَا رَسُولَ اللَّهِ. قَالَ: هَذِهِ رَحْمَةٌ جَعَلَهَا اللَّهُ فِي قُلُوبِ عِبَادِهِ، وَإِنَّمَا يَرْحَمُ اللَّهُ مِنْ عِبَادِهِ الرُّحَمَاءَ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7377)، ومسلم في الجنائز (923) كلاهما من طريق حماد بن زيد، عن عاصم الأحول، عن أبي عثمان النهدي، عن أسامة بن زيد فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقال في التعزية","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7377) and Muslim (923).","chapter_en":"What Should Be Said When Offering Condolences","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":7,"content":{"translation":{"en":["Usāmah ibn Zayd narrated: We were with the Prophet ﷺ when a messenger from one of his daughters came, asking him to come because her son was dying. The Prophet ﷺ said: “Return to her and tell her that to Allah belongs whatever He takes and whatever He gives, and everything with Him has an appointed term. Therefore, instruct her to remain patient and seek the reward from Allah.” She sent the messenger back, saying that she had sworn that he must come to her. The Prophet ﷺ then stood, accompanied by Saʿd ibn ʿUbādah and Muʿādh ibn Jabal. The child was placed in his arms while his breathing rattled like water inside an old leather water-skin. The eyes of the Prophet ﷺ overflowed with tears. Saʿd asked: “O Messenger of Allah, what is this?” He replied: “This is mercy which Allah has placed within the hearts of His servants. Allah shows mercy only to those of His servants who are merciful.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7377)، ومسلم (923)."},{"num":11103,"demo":false,"sanad":"","matn":["عن عَوْفِ بْنِ مَالِكٍ يَقُولُ:  صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى جَِنَازَةٍ، فَحَفِظْتُ مِنْ دُعَائِهِ وَهُوَ يَقُولُ: اللَّهُمَّ اغْفِرْ لَهُ، وَارْحَمْهُ، وَعَافِهِ، وَاعْفُ عَنْهُ، وَأَكْرِمْ نُزُلَهُ، وَوَسِّعْ مُدْخَلَهُ، وَاغْسِلْهُ بِالْمَاءِ وَالثَّلْجِ وَالْبَرَدِ، وَنَقِّهِ مِنَ الْخَطَايَا كَمَا نَقَّيْتَ الثَّوْبَ الْأَبْيَضَ مِنَ الدَّنَسِ، وَأَبْدِلْهُ دَارًا خَيْرًا مِنْ دَارِهِ، وَأَهْلًا خَيْرًا مِنْ أَهْلِهِ، وَزَوْجًا خَيْرًا مِنْ زَوْجِهِ، وَأَدْخِلْهُ الْجَنَّةَ، وَأَعِذْهُ مِنْ عَذَابِ الْقَبْرِ، أَوْ مِنْ عَذَابِ النَّارِ قَالَ: حَتَّى تَمَنَّيْتُ أَنْ أَكُونَ أَنَا ذَلِكَ الْمَيِّتَ.","وفي لفظ: كما ينقى الثوب الأبيض بدل كما نقيت الثوب الأبيض."],"takhrij":"صحيح: رواه مسلم في الجنائز (963) عن هارون بن سعيد الأيلي، أخبرنا ابن وهب، أخبرني معاوية بن صالح، عن حبيب بن عبيد، عن جبير بن نُفير، سمعه يقول: سمعت عوف بن مالك فذكر الحديث.","grade":"صحيح","chapter_ar":"باب الدعاء للميت في صلاة الجنازة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (963).","chapter_en":"Supplication for the Deceased during the Funeral Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["ʿAwf ibn Mālik narrated: The Messenger of Allah ﷺ performed the funeral prayer over a deceased person, and I memorized the following from his supplication: “O Allah, forgive him and have mercy upon him. Grant him well-being and pardon him. Honor his reception and make his entrance spacious. Wash him with water, snow, and hail. Purify him of sins as You have purified a white garment from filth. Replace his home with a better home, his family with a better family, and his spouse with a better spouse. Admit him into Paradise and protect him from the punishment of the grave—or from the punishment of the Fire.” ʿAwf said: “I wished that I had been that deceased person.” Another wording states: “As a white garment is purified,” instead of: “As You purified a white garment.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (963)."},{"num":11104,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: صَلَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى جَنَازَةٍ فَقَالَ: اللَّهُمَّ اغْفِرْ لِحَيِّنَا وَمَيِّتِنَا، وَصَغِيرِنَا وَكَبِيرِنَا، وَذَكَرِنَا وَأُنْثَانَا، وَشَاهِدِنَا وَغَائِبِنَا، اللَّهُمَّ مَنْ أَحْيَيْتَهُ مِنَّا فَأَحْيِهِ عَلَى الإِيمَانِ، وَمَنْ تَوَفَّيْتَهُ مِنَّا فَتَوَفَّهُ عَلَى الإِسْلاَمِ، اللَّهُمَّ لاَ تَحْرِمْنَا أَجْرَهُ، وَلاَ تُضِلَّنَا بَعْدَهُ."],"takhrij":"صحيح: رواه أبو داود (3201)، والترمذي (1024)، وابن ماجه (1498) وصحّحه ابن حبان (3070)، والحاكم (1/358) كلهم من طريق أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الدعاء للميت في صلاة الجنازة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3201), al-Tirmidhī (1024), and Ibn Mājah (1498), and authenticated by Ibn Ḥibbān (3070) and al-Ḥākim (1326).","chapter_en":"Supplication for the Deceased during the Funeral Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ performed the funeral prayer over a deceased person and said: “O Allah, forgive our living and our dead, our young and our old, our males and our females, those of us who are present and those who are absent. O Allah, whoever among us You keep alive, keep him alive upon faith, and whoever among us You cause to die, cause him to die upon Islam. O Allah, do not deprive us of his reward and do not lead us astray after him.”"]}},"tuhfa":{},"full":1,"rep":[3713],"tks":"صحيح: رواه أبو داود (3201)، والترمذي (1024)، وابن ماجه (1498)، وصححه ابن حبان (3070)، والحاكم (1326)."},{"num":11105,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: اللهُمَّ عَبْدُكَ وَابْنُ عَبْدِكَ، كَانَ يَشْهَدُ أَنْ لَا إِلَهَ إِلَاّ أَنْتَ، وَأَنَّ مُحَمَّدًا عَبْدُكَ وَرَسُولُكَ، وَأَنْتَ أَعْلَمُ بِهِ، إِنْ كَانَ مُحْسِنًا فزده فِي إِحْسَانِهِ، وَإِنْ كَانَ مُسِيئًا فَاغْفِرْ لَهُ، وَلَا تَحْرِمْنَا أَجْرَهُ وَلَا تَفْتِنَّا بَعْدَهُ."],"takhrij":"صحيح: رواه أبو يعلى المقصد العلى (465) عن وهب بن بقية، أنا خالد بن عبدالله، عن عبدالرحمن بن إسحاق المديني، عن سعيد بن أبي سعيد، عن أبي هريرة فذكر الحديث، وصحّحه ابن حبان (3073) فأخرجه عن أبي يعلى وهو أحمد بن علي بن المثنى الموصلي به مثله.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب الدعاء للميت في صلاة الجنازة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Yaʿlā in al-Maqṣad al-ʿAlī (465), and authenticated by Ibn Ḥibbān (3073).","chapter_en":"Supplication for the Deceased during the Funeral Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah narrated that the Prophet ﷺ said: “O Allah, he is Your servant and the son of Your servant. He used to testify that there is no deity worthy of worship except You and that Muḥammad is Your servant and Messenger, and You know him best. If he was a doer of good, then increase him in goodness. If he was a sinner, then forgive him. Do not deprive us of his reward and do not put us to trial after him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3714],"tks":"صحيح: رواه أبو يعلى في المقصد العلي (465)، وصححه ابن حبان (3073)."},{"num":11106,"demo":false,"sanad":"","matn":["عَنْ يَزِيدَ بْنِ عَبْدِ اللَّهِ بْنِ رُكَانَةَ بْنِ الْمُطَّلِبِ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ لِلْجِنَازَةِ لِيُصَلِّيَ عَلَيْهَا قَالَ: اللَّهُمَّ عَبْدُكَ، وَابْنُ أَمَتِكَ احْتَاجَ إِلَى رَحْمَتِكَ، وَأَنْتَ غَنِيٌّ عَنْ عَذَابِهِ، إِنْ كَانَ مُحْسِنًا فَزِدْ فِي إِحْسَانِهِ، وَإِنْ كَانَ مُسِيئًا فَتَجَاوَزَ عَنْهُ."],"takhrij":"حسن: رواه الحاكم (1328) عن أبي محمد عبد العزيز بن عبدالرحمن الخلال بمكة، ثنا عبدالرحمن بن إسحاق الكاتب، ثنا إبراهيم بن المنذر الحزامي، ثنا الحسين بن زيد بن علي بن الحسين بن علي، عن جعفر بن محمد، عن أبيه، عن يزيد بن ركانة فذكره.","grade":"حسن","chapter_ar":"باب الدعاء للميت في صلاة الجنازة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ḥākim (1328).","chapter_en":"Supplication for the Deceased during the Funeral Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Yazīd ibn Rukānah narrated: When the Messenger of Allah ﷺ stood to perform the funeral prayer, he would say: “O Allah, he is Your servant and the son of Your female servant. He is in need of Your mercy, while You have no need to punish him. If he was a doer of good, then increase him in goodness. If he was a sinner, then overlook his sins.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3716],"tks":"حسن: رواه الحاكم (1328)."},{"num":11107,"demo":false,"sanad":"","matn":["عَنْ وَاثِلَةَ بْنِ الأَسْقَعِ قَالَ: صَلَّى بِنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى رَجُلٍ مِنَ الْمُسْلِمِينَ، فَسَمِعْتُهُ يَقُولُ: اللَّهُمَّ إِنَّ فُلاَنَ بْنَ فُلاَنٍ فِي ذِمَّتِكَ، وحبْلِ جِوَارِكَ، فقِه مِنْ فِتْنَةِ الْقَبْرِ، وَعَذَابِ النَّارِ، وَأَنْتَ أهلُ الْوَفَاءِ والحق- وَفِي رِوَايَةِ: الْحَمْدُ- اللَّهُمَّ فَاغْفِرْ لَهُ، وَارْحَمْهُ، إِنَّكَ أَنْتَ الْغَفُورُ الرَّحِيمُ."],"takhrij":"حسن: رواه أبو داود (3202)، وابن ماجه (1499)، وأحمد (16018)، وصحّحه ابن حبان (3074) كلهم من طريق الوليد بن مسلم، قال: حدثنا مروان بن جناح، قال: حدثني يونس بن ميسرة بن حَلْبَسٍ، عن واثلة بن الأسْقع فذكره.","grade":"حسن","chapter_ar":"باب الدعاء للميت في صلاة الجنازة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3202), Ibn Mājah (1499), and Aḥmad (16018), and authenticated by Ibn Ḥibbān (3074).","chapter_en":"Supplication for the Deceased during the Funeral Prayer","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":8,"content":{"translation":{"en":["Wāthilah ibn al-Asqaʿ narrated: The Messenger of Allah ﷺ led us in the funeral prayer over a Muslim man, and I heard him say: “O Allah, so-and-so, the son of so-and-so, is under Your protection and the covenant of Your security. Protect him from the trial of the grave and the punishment of the Fire. You are worthy of fulfilling promises and establishing the truth.” Another narration states: “You are worthy of all praise.” He continued: “O Allah, forgive him and have mercy upon him. Indeed, You are the All-Forgiving, the Most Merciful.”"]},"buhuth":{"en":["Regarding the phrase “the covenant of Your protection,” some scholars explained that the Arabs would sometimes threaten one another. When a man intended to travel, he would obtain a pledge of protection from the leader of each tribe. He would remain safe within that tribe’s territory until reaching the next tribe, from whose leader he would obtain a similar pledge.","This was called the covenant of protection, meaning that a person remained secure while residing within that territory. It may also be derived from ijārah, meaning protection, security, and assistance. This explanation was mentioned by al-Mundhirī."]}},"tuhfa":{},"full":1,"dr":1,"rep":[3715],"tks":"حسن: رواه أبو داود (3202)، وابن ماجه (1499)، وأحمد (16018)، وصححه ابن حبان (3074)."},{"num":11108,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِذَا صَلَّيْتُمْ عَلَى الْمَيِّتِ فَأَخْلِصُوا لَهُ الدُّعَاءَ."],"takhrij":"حسن: رواه أبو داود (3199)، وابن ماجه (1497) كلاهما من طريق محمد بن سلمة الحرّاني، عن محمد بن إسحاق، عن محمد بن إبراهيم، عن أبي سلمة بن عبدالرحمن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب الإخلاص في الدعاء للميت","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3199) and Ibn Mājah (1497).","chapter_en":"Being Sincere in Supplication for the Deceased","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “When you perform the funeral prayer over the deceased, supplicate sincerely for him.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3711],"tks":"حسن: رواه أبو داود (3199)، وابن ماجه (1497)."},{"num":11109,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا وَضَعَ الْمَيِّتَ فِي الْقَبْرِ قَالَ: بِسْمِ اللَّهِ، وَعَلَى سُنَّةِ رَسُولِ اللَّهِ.","وفي رواية: وعلى ملة رسول الله."],"takhrij":"صحيح: رواه أبو داود (3213)، وأحمد (4812)، والنسائي في الكبرى (10927) وصحّحه ابن حبان (3110)، والحاكم (1354) كلهم من طريق همام بن يحيى، عن قتادة، عن أبي الصديق وهو الناجي، عن ابن عمر فذكره، واللفظ لأبي داود.وإسناده صحيح، وأبو الصديق هو بكر بن عمرو وهو ثقة،","grade":"صحيح","chapter_ar":"باب ما يقال إذا أدخل الميت في القبر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3213), Aḥmad (4812), and al-Nasā’ī in al-Sunan al-Kubrā (10927), and authenticated by Ibn Ḥibbān (3110) and al-Ḥākim (1354).","chapter_en":"What Should Be Said When the Deceased Is Placed in the Grave","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":10,"content":{"translation":{"en":["Ibn ʿUmar narrated: When the Prophet ﷺ placed the deceased in the grave, he would say: “In the name of Allah and upon the Sunnah of the Messenger of Allah.” Another narration states: “And upon the religion of the Messenger of Allah.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3213)، وأحمد (4812)، والنسائي في السنن الكبرى (10927)، وصححه ابن حبان (3110)، والحاكم (1354)."},{"num":11110,"demo":false,"sanad":"","matn":["عَنْ عُثْمَانَ بْنِ عَفَّانَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا فَرَغَ مِنْ دَفْنِ الْمَيِّتِ، وَقَفَ عَلَيْهِ فَقَالَ: اسْتَغْفِرُوا لأَخِيكُمْ، وَسَلُوا لَهُ التَّثْبِيتَ، فَإِنَّهُ الْآنَ يُسْأَلُ."],"takhrij":"حسن: أخرجه أبو داود (3221) عن إبراهيم بن موسى الرازي، حدثنا هشام، عن عبدالله بن بَحير، عن هانئ مولى عثمان، عن عثمان بن عفان فذكره.","grade":"حسن","chapter_ar":"باب الاستغفار للميت عند القبر بعد دفنه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3221).","chapter_en":"Seeking Forgiveness for the Deceased at the Grave after Burial","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":11,"content":{"translation":{"en":["ʿUthmān ibn ʿAffān narrated: When the Prophet ﷺ finished burying the deceased, he would stand by the grave and say: “Seek forgiveness for your brother and ask that he be made firm, for he is now being questioned.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3779],"tks":"حسن: أخرجه أبو داود (3221)."},{"num":11111,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّهَا قَالَتْ:  كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ (كُلَّمَا كَانَ لَيْلَتُهَا مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْرُجُ مِنْ آخِرِ اللَّيْلِ إِلَى الْبَقِيعِ فَيَقُولُ: السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَأَتَاكُمْ مَا تُوعَدُونَ، غَدًا مُؤَجَّلُونَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ، اللَّهُمَّ اغْفِرْ لِأَهْلِ بَقِيعِ الْغَرْقَدِ."],"takhrij":"صحيح: رواه مسلم في الجنائز (974) من طرق عن إسماعيل بن جعفر، عن شريك (وهو ابن أبي نمر) عن عطاء بن يسار، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب دعاء زيارة القبور","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (974).","chapter_en":"The Supplication for Visiting Graves","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah narrated: Whenever it was her night with the Messenger of Allah ﷺ, he would go out toward the end of the night to al-Baqīʿ and say: “Peace be upon you, dwelling place of believing people. What you were promised has come to you. You have been granted respite until tomorrow, and we, if Allah wills, will join you. O Allah, forgive the inhabitants of Baqīʿ al-Gharqad.”"]}},"tuhfa":{},"full":1,"rep":[3899],"tks":"صحيح: رواه مسلم (974)."},{"num":11112,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: قلتُ: كَيْفَ أَقُولُ لَهُمْ؟ (تَعْنِي أهل الْبَقِيعِ) يَا رَسُولَ اللَّهِ قَالَ: قُولِي: السَّلَامُ عَلَى أَهْلِ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَيَرْحَمُ اللَّهُ الْمُسْتَقْدِمِينَ مِنَّا وَالْمُسْتَأْخِرِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَلَاحِقُونَ."],"takhrij":"صحيح: رواه مسلم في الجنائز (974) عن هارون بن سعيد الأيلي، حدثنا عبدالله بن وهب، أخبرنا ابن جريج، عن عبدالله بن كثير بن المطلب، عن محمد بن قيس، عن عائشة فذكرته في آخر حديث طويل.","grade":"صحيح","chapter_ar":"باب دعاء زيارة القبور","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (974).","chapter_en":"The Supplication for Visiting Graves","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["ʿĀ’ishah narrated: I asked: “O Messenger of Allah, what should I say to them?” She meant the inhabitants of al-Baqīʿ. He replied: “Say: ‘Peace be upon the inhabitants of these dwellings from among the believers and Muslims. May Allah have mercy upon those of us who have gone ahead and those who will come later. We, if Allah wills, will surely join you.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (974)."},{"num":11113,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحُصَيب قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُعَلِّمُهُمْ إِذَا خَرَجُوا إِلَى الْمَقَابِرِ، فَكَانَ قَائِلُهُمْ يَقُولُ (فِي رِوَايَةِ أَبِي بَكْرٍ): السَّلَامُ عَلَى أَهْلِ الدِّيَارِ، (وَفِي رِوَايَةِ زُهَيْرٍ): السَّلَامُ عَلَيْكُمْ أَهْلَ الدِّيَارِ مِنَ الْمُؤْمِنِينَ وَالْمُسْلِمِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ لَلَاحِقُونَ، أَسْأَلُ اللَّهَ لَنَا وَلَكُمُ الْعَافِيَةَ."],"takhrij":"صحيح: رواه مسلم في الجنائز (975) عن أبي بكر بن أبي شيبة وزهير بن حرب، قالا: حدثنا محمد بن عبدالله الأسدي، عن سفيان، عن علقمة بن مَرْثَدٍ، عن سليمان بن بريدة، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب دعاء زيارة القبور","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (975).","chapter_en":"The Supplication for Visiting Graves","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb narrated: The Messenger of Allah ﷺ would teach them what to say when they went out to the graveyards. In Abū Bakr’s narration, the speaker would say: “Peace be upon the inhabitants of these dwellings.” In Zuhayr’s narration, he would say: “Peace be upon you, inhabitants of these dwellings, from among the believers and Muslims. We, if Allah wills, will join you. I ask Allah to grant well-being to us and to you.”"]},"buhuth":{"en":["Al-Nasā’ī (2040) added after the words “we will join you”:","“You have gone ahead of us, and we will follow you. I ask Allah to grant well-being to us and to you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3902],"tks":"صحيح: رواه مسلم (975)."},{"num":11114,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَرَجَ إِلَى الْمَقْبُرَةِ، فَقَالَ: السَّلَامُ عَلَيْكُمْ دَارَ قَوْمٍ مُؤْمِنِينَ، وَإِنَّا إِنْ شَاءَ اللَّهُ بِكُمْ لَاحِقُونَ."],"takhrij":"صحيح: رواه مالك في الطهارة (28) عن العلاء بن عبدالرحمن، عن أبيه، عن أبي هريرة فذكره في أول حديث طويل، وهو مذكور بطوله في كتاب الطهارة.","grade":"صحيح","chapter_ar":"باب دعاء زيارة القبور","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (28) and Muslim (249).","chapter_en":"The Supplication for Visiting Graves","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah narrated: The Messenger of Allah ﷺ went out to the graveyard and said: “Peace be upon you, dwelling place of believing people. We, if Allah wills, will join you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[3903],"tks":"صحيح: رواه مالك (28)، ومسلم (249)."},{"num":11115,"demo":false,"sanad":"","matn":["عن عائشة قالت في حديث طويل عن خروج النبي صلى الله عليه وسلم من البيت إلى البقيع حتى جاء البقيع فقام فأطال القيام ثم رفع يديه ثلاث مرات."],"takhrij":"صحيح: رواه مسلم في الجنائز (947: 103) من طريق محمد بن قيس، عن عائشة فذكرته في أثناء حديث طويل.","grade":"صحيح","chapter_ar":"باب جواز رفع اليدين عند الدعاء لأصحاب القبور","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (947/103).","chapter_en":"The Permissibility of Raising the Hands When Supplicating for the Inhabitants of the Graves","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية المرض والجنازة وما يتعلق بها","group_en":"Collection of Narrations Concerning Supplications for Illness, Funerals, and Related Matters","part_no":54,"group_no":9,"chapter_no":13,"content":{"translation":{"en":["ʿĀ’ishah narrated in a lengthy hadith concerning the departure of the Prophet ﷺ from the house toward al-Baqīʿ: When he reached al-Baqīʿ, he stood for a long time and then raised his hands three times."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (947: 103)."},{"num":11116,"demo":false,"sanad":"","matn":["عن عبدالله بن أبي أوفى، قال: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَتَاهُ قَوْمٌ بِصَدَقَتِهِمْ، قَال: اللَّهُمَّ صَلِّ عَلَى آلِ فُلانٍ.فَأَتَاهُ أَبِي بِصَدَقَتِهِ فَقَالَ: اللَّهُمَّ صَلِّ عَلَى آلِ أَبِي أَوْفَى."],"takhrij":"متفق عليه: رواه البخاريّ في الزكاة (1497)، ومسلم في الزّكاة (1078) كلاهما من طريق شعبة، عن عمرو (وهو ابن مرة)، عن عبدالله بن أبي أوفى، فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب دعاء الإمام لمن أتى بصدقته","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1497) and Muslim (1078).","chapter_en":"The Supplication of the Leader for the Person Who Brings His Charity","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Abī Awfā narrated: When people brought their charity to the Prophet ﷺ, he would say: “O Allah, bestow Your blessings upon the family of so-and-so.” When my father brought his charity to him, he said: “O Allah, bestow Your blessings upon the family of Abū Awfā.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿خُذْ مِنْ أَمْوَالِهِمْ صَدَقَةً تُطَهِّرُهُمْ وَتُزَكِّيهِمْ بِهَا وَصَلِّ عَلَيْهِمْ، إِنَّ صَلَاتَكَ سَكَنٌ لَهُمْ﴾ [سورة التوبة: ١٠٣]."],"en":["Allah, the Exalted, said:","“Take charity from their wealth to purify and cleanse them through it, and supplicate for them. Indeed, your supplication is a source of reassurance for them.”","[Sūrat al-Tawbah 9:103]"]}},"tuhfa":{},"full":1,"rep":[4112,10876],"tks":"متفق عليه: رواه البخاري (1497)، ومسلم (1078)."},{"num":11117,"demo":false,"sanad":"","matn":["عن وائل بن حجر، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ سَاعِيًا، فَأَتَى رَجُلا فَآتَاهُ فَصِيلاً مَخْلُولا.فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَعَثْنَا مُصَدِّقَ الله وَرَسُولِهِ وَإِنَّ فُلانًا أَعْطَاهُ فَصِيلا مَخْلُولا! اللَّهُمَّ لا تُبَارِكْ فِيهِ، وَلا فِي إِبِلِهِ.فَبَلَغَ ذَلِكَ الرَّجُلَ فَجَاءَ بِنَاقَةٍ حَسْنَاءَ فَقَالَ: أَتُوبُ إِلَى الله عَزَّ وَجَلَّ وَإِلَى نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ بَارِكْ فِيهِ وَفِي إِبِلِهِ."],"takhrij":"حسن: رواه النسائيّ (2458)، وصحّحه ابن خزيمة (2274)كلاهما من طريق سفيان، عن عاصم بن كليب، عن أبيه، عن وائل بن حجر، أنّ النبيّ صلى الله عليه وسلم، قال: فذكره.وإسناده حسن من أجل عاصم بن كليب، وأبيه كليب بن شهاب فهما صدوقان.","grade":"حسن","chapter_ar":"باب دعاء الإمام لمن أتى بصدقته","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (2458), and authenticated by Ibn Khuzaymah (2274).","chapter_en":"The Supplication of the Leader for the Person Who Brings His Charity","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":1,"content":{"translation":{"en":["Wā’il ibn Ḥujr narrated: The Prophet ﷺ sent a charity collector. When the collector went to a man, the man gave him a weak young camel. The Prophet ﷺ said: “We sent the collector of Allah and His Messenger, yet so-and-so gave him a weak young camel! O Allah, do not bless him or his camels.” When the man heard about this, he came with a fine she-camel and said: “I repent to Allah, Mighty and Majestic, and to His Prophet ﷺ.” The Prophet ﷺ then said: “O Allah, bless him and his camels.”"]}},"tuhfa":{},"full":1,"rep":[4113],"tks":"حسن: رواه النسائي (2458)، وصححه ابن خزيمة (2274)."},{"num":11118,"demo":false,"sanad":"","matn":["عن مَرْوَانَ -يَعْنِي ابْنَ سالم المقنع- قَالَ: رَأَيْتُ ابْنَ عُمَرَ يَقْبِضُ عَلَى لِحْيَتِهِ فَيَقْطَعُ مَا زَادَ عَلَى الْكَفِّ، وَقَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَفْطَرَ قَالَ: ذَهَبَ الظَّمَأُ وَابْتَلَّتِ الْعُرُوقُ، وَثَبَتَ الأَجْرُ إِنْ شَاءَ اللَّهُ."],"takhrij":"حسن: رواه أبو داود (2357)، والنسائي في \"الكبرى\" (3315) والدارقطني (2279)، والحاكم (1536)، والبيهقي (8133) كلهم من حديث علي بن حسن، قال: أخبرنا الحسين بن واقد، قال: أخبرنا مروان المقنع فذكره.","grade":"حسن","chapter_ar":"باب ما يقول الصائم عند فطره","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2357), al-Nasā’ī in al-Sunan al-Kubrā (3315), al-Dāraquṭnī (2279), al-Ḥākim (1536), and al-Bayhaqī (4/239).","chapter_en":"What a Fasting Person Should Say When Breaking the Fast","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":2,"content":{"translation":{"en":["Marwān—meaning Ibn Sālim al-Muqannaʿ—narrated: I saw Ibn ʿUmar grasp his beard and cut whatever extended beyond a fistful. He said: When the Messenger of Allah ﷺ broke his fast, he would say: “The thirst has gone, the veins have been moistened, and the reward has been confirmed, if Allah wills.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4387],"tks":"حسن: رواه أبو داود (2357)، والنسائي في السنن الكبرى (3315)، والدارقطني (2279)، والحاكم (1536)، والبيهقي (8133)."},{"num":11119,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَفْطَرَ عِنْدَ قَوْمٍ دَعَا لَهُمْ، فَقَالَ: أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الْأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلَائِكَةُ."],"takhrij":"حسن: رواه ابن السني في عمل اليوم والليلة (482)، والطبراني في الدّعاء (925) كلاهما من حديث عمران القطان، عن قتادة، عن أنس، فذكره.","grade":"حسن","chapter_ar":"باب ما يقول من أفطر عند قوم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (482) and al-Ṭabarānī in al-Duʿāʾ (925).","chapter_en":"What One Should Say after Breaking the Fast with a Group of People","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated: When the Messenger of Allah ﷺ broke his fast with a group of people, he would supplicate for them, saying: “May those who fast break their fast with you, may the righteous eat your food, and may the angels invoke blessings upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4388],"tks":"حسن: رواه ابن السني في عمل اليوم والليلة (482)، والطبراني في الدعاء (925)."},{"num":11120,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: قُلْتُ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ إِنْ عَلِمْتُ أَىُّ لَيْلَةٍ لَيْلَةُ الْقَدْرِ مَا أَقُولُ فِيهَا؟ قَالَ: قُولِي: اللَّهُمَّ إِنَّكَ عَفُوٌّ كَرِيمٌ تُحِبُّ الْعَفْوَ فَاعْفُ عَنِّي."],"takhrij":"صحيح: رواه الترمذي (3513)، وابن ماجه (3850) وأحمد (25384)، والنسائي في عمل اليوم والليلة (872، 873، 874)، والحاكم (1942)، والبيهقي في \"فضائل الأوقات\" (113) كلّهم من حديث كهمس بن الحسن، عن عبدالله بن بريدة، عن عائشة، فذكرته.وقال الترمذي: حسن صحيح وصحّحه النووي في \"الأذكار\".","grade":"صحيح","chapter_ar":"باب ما يقول إذا وافق ليلة القدر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3513), Ibn Mājah (3850), Aḥmad (25384), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (872, 873, 874), al-Ḥākim (1942), and al-Bayhaqī in Faḍāʾil al-Awqāt (113).","chapter_en":"What Should Be Said When One Encounters Laylat al-Qadr","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah narrated: I asked: “O Messenger of Allah, if I know which night is Laylat al-Qadr, what should I say during it?” He replied: “Say: ‘O Allah, You are Pardoning and You love to pardon, so pardon me.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3513)، وابن ماجه (3850)، وأحمد (25384)، والنسائي في عمل اليوم والليلة (872، 873، 874)، والحاكم (1942)، والبيهقي في فضائل الأوقات (113)."},{"num":11121,"demo":false,"sanad":"","matn":["عن أنس، قال: صَلَّى رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ مَعَهُ بِالمَدِينَةِ الظُّهْرَ أَرْبَعًا وَالْعَصْرَ بِذِي الحُلَيْفَةِ رَكْعَتَيْنِ، ثُمَّ بَاتَ بِهَا حَتَّى أَصْبَحَ، ثُمَّ رَكِبَ حَتَّى اسْتَوَتْ بِهِ عَلَى الْبَيْدَاءِ حَمِدَ الله وَسَبَّحَ وَكَبَّرَ، ثُمَّ أَهَلَّ بِحَجٍّ وَعُمْرَةٍ وَأَهَلَّ النَّاسُ بِهِمَا، فَلَمَّا قَدِمْنَا أَمَرَ النَّاسَ فَحَلُّوا حَتَّى كَانَ يَوْمُ التَّرْوِيَةِ أَهَلُّوا بِالحَجِّ قَالَ: وَنَحَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَدَنَاتٍ بِيَدِهِ قِيَامًا وَذَبَحَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالمَدِينَةِ كَبْشَيْنِ أَمْلَحَيْنِ."],"takhrij":"متفق عليه: رواه البخاريّ في الحج (1551)، ومسلم في صلاة المسافرين (690) كلاهما من طريق أيوب، عن أبي قلابة، عن أنس، به.","grade":"متفق عليه","chapter_ar":"باب استحباب التحميد والتسبيح والتكبير قبل الإهلال بالحج والعمرة عند الركوب","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1551) and Muslim (690).","chapter_en":"The Recommendation to Praise Allah, Glorify Him, and Proclaim His Greatness before Entering Iḥrām for Ḥajj or ʿUmrah upon Mounting","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":5,"content":{"translation":{"en":["Anas narrated: The Messenger of Allah ﷺ prayed four units of Ẓuhr with us in Madinah and two units of ʿAṣr at Dhū al-Ḥulayfah. He then spent the night there until morning. Afterward, he mounted his riding animal. When it stood upright with him upon al-Bayḍāʾ, he praised Allah, glorified Him, and proclaimed His greatness. He then entered the state of iḥrām for both Ḥajj and ʿUmrah, and the people also entered iḥrām for both. When we arrived, he instructed the people to leave the state of iḥrām. Then, when the Day of Tarwiyah came, they entered iḥrām for Ḥajj. Anas said: The Prophet ﷺ slaughtered sacrificial camels with his own hand while they were standing, and the Messenger of Allah ﷺ also slaughtered two predominantly white rams with black markings in Madinah."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4884],"tks":"متفق عليه: رواه البخاري (1551)، ومسلم (690)."},{"num":11122,"demo":false,"sanad":"","matn":["عن ابن عمر: أَنَّ تَلْبِيَةَ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لا شَرِيكَ لَكَ، لَبَّيْكَ إِنَّ الحَمْدَ وَالنِّعْمَةَ لَكَ وَالمُلْكَ لا شَرِيكَ لَك.","قَال: وَكَانَ عبدالله بْنُ عُمَرَ يَزِيدُ فِيهَا: لَبَّيْكَ لَبَّيْكَ، لَبَّيْكَ وَسَعْدَيْكَ وَالْخَيْرُ بِيَدَيْكَ، لَبَّيْكَ وَالرَّغْبَاءُ إِلَيْكَ وَالْعَمَلُ."],"takhrij":"متفق عليه: رواه مالك في الحج (28) عن نافع، عن ابن عمر، فذكره.","grade":"متفق عليه","chapter_ar":"باب صفة التلبية في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (28), al-Bukhārī (1549), and Muslim (1184/19).","chapter_en":"The Wording of the Talbiyah for Ḥajj and ʿUmrah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿUmar narrated that the talbiyah of the Messenger of Allah ﷺ was: “Here I am at Your service, O Allah, here I am. Here I am at Your service; You have no partner, here I am. Indeed, all praise, every blessing, and all sovereignty belong to You. You have no partner.” ʿAbdullāh ibn ʿUmar would add: “Here I am at Your service, here I am. Here I am in obedience and happiness. All goodness is in Your hands. Here I am at Your service; all desire and all deeds are directed toward You.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4889],"tks":"متفق عليه: رواه مالك (28)، والبخاري (1549)، ومسلم (1184/19)."},{"num":11123,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا قَالَتْ: إِنِّي لأَعْلَمُ كَيْفَ كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُلَبِّي: لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لاَ شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الْحَمْدَ وَالنِّعْمَةَ لَكَ."],"takhrij":"صحيح: رواه البخاريّ في الحج (1550) عن محمد بن يوسف، حدّثنا سفيان، عن الأعمش، عن عُمارة (هو ابن عُمير التيميّ)، عن أبي عطية (هو الوادعيّ الكوفيّ)، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب صفة التلبية في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1550).","chapter_en":"The Wording of the Talbiyah for Ḥajj and ʿUmrah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["ʿĀ’ishah narrated: I know how the Prophet ﷺ used to recite the talbiyah: “Here I am at Your service, O Allah, here I am. Here I am at Your service; You have no partner, here I am. Indeed, all praise and every blessing belong to You.”"]}},"tuhfa":{},"full":1,"rep":[4890],"tks":"صحيح: رواه البخاري (1550)."},{"num":11124,"demo":false,"sanad":"","matn":["عن جابر قال: فَأَهَلَّ بِالتَّوْحِيدِ: لَبَّيْكَ اللَّهُمَّ لَبَّيْكَ، لَبَّيْكَ لا شَرِيكَ لَكَ لَبَّيْكَ، إِنَّ الحَمْدَ وَالنِّعْمَةَ لَكَ وَالمُلْكَ لا شَرِيكَ لَكَ."],"takhrij":"صحيح: رواه مسلم في الحج (1218) من طرق عن حاتم بن إسماعيل المدني، عن جعفر بن محمد، عن أبيه، قال: دخلنا على جابر بن عبدالله، فذكر صفة حجّة النبيّ صلى الله عليه وسلم في حديث طويل كما مضى.","grade":"صحيح","chapter_ar":"باب صفة التلبية في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"The Wording of the Talbiyah for Ḥajj and ʿUmrah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Jābir narrated: The Prophet ﷺ proclaimed the talbiyah of pure monotheism: “Here I am at Your service, O Allah, here I am. Here I am at Your service; You have no partner, here I am. Indeed, all praise, every blessing, and all sovereignty belong to You. You have no partner.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4891],"tks":"صحيح: رواه مسلم (1218)."},{"num":11125,"demo":false,"sanad":"","matn":["عن عبدالله بن عباس، قال: كَانَ المُشْرِكُونَ يَقُولُونَ لَبَّيْكَ لا شَرِيكَ لَكَ قَالَ: فَيَقُولُ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: وَيْلَكُمْ! قَدْ قَدْ.فَيَقُولُونَ: إِلا شَرِيكًا هُوَ لَكَ، تَمْلِكُهُ وَمَا مَلَكَ.يَقُولُونَ هَذَا وَهُمْ يَطُوفُونَ بِالْبَيْتِ."],"takhrij":"صحيح: رواه مسلم في الحج (1185) عن عباس بن عبد العظيم العنبري، حدثنا النضر بن محمد اليماميّ، حدثنا عكرمة بن عمار، حدثنا أبو زميل (وهو سماك بن الوليد الحنفي)، عن ابن عباس، فذكره.","grade":"صحيح","chapter_ar":"باب صفة التلبية في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1185).","chapter_en":"The Wording of the Talbiyah for Ḥajj and ʿUmrah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated: The polytheists used to say: “Here we are at Your service; You have no partner.” The Messenger of Allah ﷺ would say: “Woe to you! Stop there, stop there.” But they would continue: “Except for a partner who belongs to You; You possess him and whatever he possesses.” They used to say this while circumambulating the House."]}},"tuhfa":{},"full":1,"rep":[4892],"tks":"صحيح: رواه مسلم (1185)."},{"num":11126,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ فِي تَلْبِيَتِهِ: لَبَّيْكَ إِلَهَ الْحَقِّ لَبَّيْكَ."],"takhrij":"صحيح: رواه النسائيّ (2752)، وابن ماجه (2920)، وصحّحه ابن خزيمة (2624)، وابن حبان (3800)، والحاكم (10) كلّهم من حديث عبدالعزيز بن عبدالله بن أبي سلمة، عن عبدالله بن الفضل، حدثه عن عبدالرحمن الأعرج، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"باب صفة التلبية في الحج والعمرة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (2752) and Ibn Mājah (2920), and authenticated by Ibn Khuzaymah (2624), Ibn Ḥibbān (3800), and al-Ḥākim (1/449).","chapter_en":"The Wording of the Talbiyah for Ḥajj and ʿUmrah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said in his talbiyah: “Here I am at Your service, O Allah of truth, here I am.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4893],"tks":"صحيح: رواه النسائي (2752)، وابن ماجه (2920)، وصححه ابن خزيمة (2624)، وابن حبان (3800)، والحاكم (10)."},{"num":11127,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: طَافَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْبَيْتِ عَلَى بَعِيرٍ، كُلَّمَا أَتَى الرُّكْنَ أَشَارَ إِلَيْهِ بِشَىْءٍ كَانَ عِنْدَهُ، وَكَبَّرَ."],"takhrij":"صحيح: رواه البخاري في الحج (1613) عن مسدد، ثنا خالد بن عبد الله، ثنا خالد الحذاء، عن عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب التكبير عند الحجر الأسود في الطواف","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1613).","chapter_en":"Proclaiming Allah’s Greatness at the Black Stone during Ṭawāf","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":7,"content":{"translation":{"en":["Ibn ʿAbbās narrated: The Prophet ﷺ circumambulated the House while riding a camel. Whenever he came to the Corner containing the Black Stone, he pointed toward it with something he had in his hand and proclaimed Allah’s greatness."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه البخاري (1613)."},{"num":11128,"demo":false,"sanad":"","matn":["عن عبدالله بن السائب، قال: سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ مَا بَيْنَ الرُّكْنَيْنِ: ﴿رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ﴾ [سورة البقرة:201]."],"takhrij":"حسن: رواه أبو داود (1892)، وأحمد (15398، 15399)، وصحّحه ابن خزيمة (2721)، وابن حبان (3826)، والحاكم (1673) كلهم من طريق ابن جريج، حدثني يحيى بن عبيد، عن أبيه، عن عبدالله بن السّائب، فذكره.","grade":"حسن","chapter_ar":"باب ما يقول الطائف بين الركن اليماني والحجر الأسود","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (1892) and Aḥmad (15398, 15399), and authenticated by Ibn Khuzaymah (2721), Ibn Ḥibbān (3826), and al-Ḥākim (1673).","chapter_en":"What the Person Performing Ṭawāf Should Say between the Yemeni Corner and the Black Stone","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn al-Sā’ib narrated: I heard the Messenger of Allah ﷺ say between the two corners: “Our Lord, grant us good in this world and good in the Hereafter, and protect us from the punishment of the Fire.” [Sūrat al-Baqarah 2:201]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[4983],"tks":"حسن: رواه أبو داود (1892)، وأحمد (15398، 15399)، وصححه ابن خزيمة (2721)، وابن حبان (3826)، والحاكم (1673)."},{"num":11129,"demo":false,"sanad":"","matn":["عن جابر بن عبدالله، قال: فَلَمَّا دَنَا مِن الصَّفَا قَرَأَ: ﴿إِنَّ الصَّفَا وَالْمَرْوَةَ مِنْ شَعَائِرِ اللَّهِ﴾ [البقرة: 158]، أَبْدَأُ بِمَا بَدَأَ الله بِهِ، فَبَدَأَ بِالصَّفَا فَرَقِيَ عَلَيْهِ حَتَّى رَأَى الْبَيْتَ، فَاسْتَقْبَلَ الْقِبْلَةَ، فَوَحَّدَ الله وَكَبَّرَهُ، وَقَال: لا إِلَهَ إِلا الله وَحْدَهُ لا شَرِيكَ لَهُ، لَهُ المُلْكُ وَلَهُ الحَمْدُ وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، لا إِلَهَ إِلا الله وَحْدَهُ أَنْجَزَ وَعْدَهُ وَنَصَرَ عَبْدَهُ وَهَزَمَ الْأَحْزَابَ وَحْدَهُ.ثُمَّ دَعَا بَيْنَ ذَلِكَ قَالَ مِثْلَ هَذَا ثَلاثَ مَرَّاتٍ، ثُمَّ نَزَلَ إِلَى المَرْوَةِ حَتَّى إِذَا انْصَبَّتْ قَدَمَاهُ فِي بَطْنِ الْوَادِي سَعَى حَتَّى إِذَا صَعِدَتَا مَشَى، حَتَّى أَتَى المَرْوَةَ فَفَعَلَ عَلَى المَرْوَةِ كَمَا فَعَلَ عَلَى الصَّفَا."],"takhrij":"صحيح: رواه مسلم في الحج (1218) من طرق عن حاتم بن إسماعيل المدنيّ، عن جعفر بن محمد، عن أبيه، عن جابر، فذكر الحديث بطوله في حجّة النبيّ صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب ما يقال عند الصفا والمروة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"What Should Be Said at al-Ṣafā and al-Marwah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: When the Prophet ﷺ approached al-Ṣafā, he recited: “Indeed, al-Ṣafā and al-Marwah are among the symbols of Allah.” [Sūrat al-Baqarah 2:158] He then said: “I begin with what Allah began with.” He began with al-Ṣafā and ascended it until he could see the House. He faced the qiblah, declared Allah’s oneness, proclaimed His greatness, and said: “There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things. There is no deity worthy of worship except Allah alone. He fulfilled His promise, granted victory to His servant, and defeated the confederates by Himself.” He then supplicated between these declarations and repeated the same words three times. Afterward, he descended toward al-Marwah. When his feet reached the bottom of the valley, he moved quickly. When they began ascending, he walked normally until he reached al-Marwah. At al-Marwah, he did the same as he had done at al-Ṣafā."]}},"tuhfa":{},"full":1,"rep":[5049],"tks":"صحيح: رواه مسلم (1218)."},{"num":11130,"demo":false,"sanad":"","matn":["عَنْ مُحَمَّدِ بْنِ أَبِي بَكْرٍ الثَّقَفِيِّ، أَنَّهُ سَأَلَ أَنَسَ بْنَ مَالِكٍ وَهُمَا غَادِيَانِ مِنْ مِنًى إِلَى عَرَفَةَ كَيْفَ كُنْتُمْ تَصْنَعُونَ فِي هَذَا الْيَوْمِ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ فَقَالَ كَانَ يُهِلُّ مِنَّا الْمُهِلُّ فَلاَ يُنْكِرُ عَلَيْهِ، وَيُكَبِّرُ مِنَّا الْمُكَبِّرُ فَلاَ يُنْكِرُ عَلَيْهِ."],"takhrij":"متفق عليه: رواه مالك في الحج (43) عن محمد بن أبي بكر الثقفيّ، أنه سأل أنس بن مالك فذكره.ورواه البخاريّ في الحج (1659)، ومسلم في الحج (1285) كلاهما من طريق مالك، به مثله.","grade":"متفق عليه","chapter_ar":"باب التلبية والتكبير عند الغدو من منى إلى عرفات","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (43), al-Bukhārī (1659), and Muslim (1285).","chapter_en":"Reciting the Talbiyah and Takbīr While Traveling from Minā to ʿArafāt","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["Muḥammad ibn Abī Bakr al-Thaqafī asked Anas ibn Mālik while they were traveling in the morning from Minā to ʿArafāt: “What did you used to do on this day while accompanying the Messenger of Allah ﷺ?” Anas replied: “Some of us would recite the talbiyah, and no objection was made to them. Others would proclaim Allah’s greatness, and no objection was made to them.”"]}},"tuhfa":{},"full":1,"rep":[5088],"tks":"متفق عليه: رواه مالك (43)، والبخاري (1659)، ومسلم (1285)."},{"num":11131,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن عُمَرَ، قَالَ: غَدَوْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ مِنى إِلَى عَرَفَاتٍ، مِنَّا الْمُلَبِّي، ومِنَّا الْمُكَبِّرُ."],"takhrij":"صحيح: رواه مسلم في الحج (1284) من طريق يحيى بن سعيد (هو الأنصاريّ)، عن عبدالله بن أبي سلمة (هو الماجشون)، عن عبدالله بن عبدالله بن عمر، عن أبيه فذكره.","grade":"صحيح","chapter_ar":"باب التلبية والتكبير عند الغدو من منى إلى عرفات","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1284).","chapter_en":"Reciting the Talbiyah and Takbīr While Traveling from Minā to ʿArafāt","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar narrated: We traveled in the morning with the Messenger of Allah ﷺ from Minā to ʿArafāt. Some of us recited the talbiyah, while others proclaimed Allah’s greatness."]}},"tuhfa":{},"full":1,"rep":[5089],"tks":"صحيح: رواه مسلم (1284)."},{"num":11132,"demo":false,"sanad":"","matn":["عَنْ عَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَفْضَلُ مَا قُلْتُ أَنَا وَالنَّبِيُّونَ قَبْلِي عَشِيَّةَ عَرَفَةَ: لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ، لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ."],"takhrij":"حسن: رواه الطبراني في الدعاء (874) من طريق قيس بن الربيع، عن الأغر بن الصباح، عن خليفة بن حصين، عن علي رضي الله عنه، فذكره.","grade":"حسن","chapter_ar":"باب أفضل الدعاء دعاء يوم عرفة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Duʿāʾ (874).","chapter_en":"The Best Supplication Is the Supplication of the Day of ʿArafah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":11,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib narrated that the Messenger of Allah ﷺ said: “The best words that I and the prophets before me have said on the evening of ʿArafah are: ‘There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[5114],"tks":"حسن: رواه الطبراني في الدعاء (874)."},{"num":11133,"demo":false,"sanad":"","matn":["عن أُسَامَةَ بن زَيْدٍ كُنْتُ رَدِيفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَرَفَاتٍ، فَرَفَعَ يَدَيْهِ يَدْعُو، فَمَالَتْ بِهِ نَاقَتُهُ فَسَقَطَ خِطَامُهَا، فَتَنَاوَلَ الْخِطَامَ بِإِحْدَى يَدَيْهِ، وَهُوَ رَافِعٌ يَدَهُ الأُخْرَى."],"takhrij":"حسن: رواه النسائيّ (3011) عن يعقوب بن إبراهيم، عن هُشيم، قال: حدثنا عبد الملك، عن عطاء، قال: قال أسامة، فذكره.","grade":"حسن","chapter_ar":"باب رفع اليدين في الدعاء بعرفات","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (3011).","chapter_en":"Raising the Hands in Supplication at ʿArafāt","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":12,"content":{"translation":{"en":["Usāmah ibn Zayd narrated: I was riding behind the Prophet ﷺ at ʿArafāt when he raised his hands in supplication. His she-camel leaned to one side and its halter fell, so he took hold of the halter with one hand while keeping the other hand raised."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي (3011)."},{"num":11134,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال في صفة حجة النبي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:...ثُمَّ رَكِبَ الْقَصْوَاءَ، حَتَّى أَتَى المَشْعَرَ الحَرَامَ فَاسْتَقْبَلَ الْقِبْلَةَ فَدَعَاهُ وَكَبَّرَهُ وَهَلَّلَهُ وَوَحَّدَهُ، فَلَمْ يَزَلْ وَاقِفًا حَتَّى أَسْفَرَ جِدًّا...الحديث بطوله."],"takhrij":"صحيح: رواه مسلم في الحج (1218) من طريق حاتم بن إسماعيل المدني، عن جعفر بن محمد، عن أبيه، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب الدعاء عند المشعر الحرام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Supplication at al-Mashʿar al-Ḥarām","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated while describing the pilgrimage of the Prophet ﷺ: The Prophet ﷺ then mounted al-Qaṣwāʾ and continued until he reached al-Mashʿar al-Ḥarām. He faced the qiblah, supplicated to Allah, proclaimed His greatness, declared that there is no deity worthy of worship except Him, and affirmed His oneness. He remained standing there until the daylight had become very clear. This forms part of the lengthy hadith."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿فَإِذَا أَفَضْتُمْ مِنْ عَرَفَاتٍ فَاذْكُرُوا اللّٰهَ عِنْدَ الْمَشْعَرِ الْحَرَامِ، وَاذْكُرُوهُ كَمَا هَدَاكُمْ، وَإِنْ كُنْتُمْ مِنْ قَبْلِهِ لَمِنَ الضَّالِّينَ﴾ [سورة البقرة: ١٩٨]."],"en":["Allah, the Exalted, said:","“When you depart from ʿArafāt, remember Allah at al-Mashʿar al-Ḥarām, and remember Him as He has guided you, for before that you were certainly among those who had gone astray.”","[Sūrat al-Baqarah 2:198]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1218)."},{"num":11135,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن يَزِيدَ أَنَّهُ كَانَ مَعَ ابْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ حِينَ رَمَى جَمْرَةَ الْعَقَبَةِ، فَاسْتَبْطَنَ الْوَادِيَ، حَتَّى إِذَا حَاذَى بِالشَّجَرَةِ اعْتَرَضَهَا، فَرَمَى بِسَبْعِ حَصَيَاتٍ، يُكَبِّرُ مَعَ كُلِّ حَصَاةٍ، ثُمَّ قَالَ: مِنْ هَا هُنَا وَالَّذِي لاَ إِلَهَ غَيْرُهُ قَامَ الَّذِي أُنْزِلَتْ عَلَيْهِ سُورَةُ الْبَقَرَةِ."],"takhrij":"متفق عليه: رواه البخاري في الحج (1750)، ومسلم في الحج (1296) كلاهما من طريق الأعمش قال: سمعت الحجاج يقول على المنبر: السورة التي يذكر فيها البقرة، والسورة التي يذكر فيها آل عمران، والسورة التي يذكر فيها النساء قال: فذكرت ذلك لإبراهيم فقال: حدثني عبد الرحمن بن يزيد فذكره.","grade":"متفق عليه","chapter_ar":"باب التكبير مع كل حصاة عند رمي الجمرات","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1750) and Muslim (1296).","chapter_en":"Proclaiming Allah’s Greatness with Every Pebble When Stoning the Jamarāt","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":14,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Yazīd narrated: He was with Ibn Masʿūd when he stoned Jamrat al-ʿAqabah. Ibn Masʿūd went down into the middle of the valley until he came level with the tree, positioned the Jamarah before him, and threw seven pebbles, proclaiming Allah’s greatness with each pebble. He then said: “From this very place—by the One besides whom there is no deity—stood the one to whom Sūrat al-Baqarah was revealed.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (1750)، ومسلم (1296)."},{"num":11136,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله في صفة حجة النبي صلى الله عليه وسلم قال: ...حتى أتى الجمرة التي عند الشجرة، فرماها بسبع حصيات، يكبر مع كل حصاة منها.الحديث بطوله."],"takhrij":"صحيح: رواه مسلم في الحج (1218) من طريق حاتم بن إسماعيل المدني، عن جعفر بن محمد، عن أبيه، عن جابر فذكره في صفة حجة النبي صلى الله عليه وسلم.","grade":"صحيح","chapter_ar":"باب التكبير مع كل حصاة عند رمي الجمرات","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1218).","chapter_en":"Proclaiming Allah’s Greatness with Every Pebble When Stoning the Jamarāt","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated while describing the pilgrimage of the Prophet ﷺ: The Prophet ﷺ continued until he reached the Jamarah beside the tree. He threw seven pebbles at it, proclaiming Allah’s greatness with each pebble. This forms part of the lengthy hadith."]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (1218)."},{"num":11137,"demo":false,"sanad":"","matn":["عَنْ سَالِمِ بْنِ عَبْدِ اللَّهِ، أَنَّ عَبْدَ اللَّهِ بْنَ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا كَانَ يَرْمِي الْجَمْرَةَ الدُّنْيَا بِسَبْعِ حَصَيَاتٍ، ثُمَّ يُكَبِّرُ عَلَى إِثْرِ كُلِّ حَصَاةٍ، ثُمَّ يَتَقَدَّمُ فَيُسْهِلُ، فَيَقُومُ مُسْتَقْبِلَ الْقِبْلَةِ قِيَامًا طَوِيلاً، فَيَدْعُو وَيَرْفَعُ يَدَيْهِ، ثُمَّ يَرْمِي الْجَمْرَةَ الْوُسْطَى كَذَلِكَ، فَيَأْخُذُ ذَاتَ الشِّمَالِ فَيُسْهِلُ، وَيَقُومُ مُسْتَقْبِلَ الْقِبْلَةِ قِيَامًا طَوِيلاً، فَيَدْعُو وَيَرْفَعُ يَدَيْهِ، ثُمَّ يَرْمِي الْجَمْرَةَ ذَاتَ الْعَقَبَةِ مِنْ بَطْنِ الْوَادِي، وَلاَ يَقِفُ عِنْدَهَا، وَيَقُولُ: هَكَذَا رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَفْعَلُ."],"takhrij":"صحيح: رواه البخاري في الحج (1752) عن إسماعيل بن عبد الله (هو ابن أبي أويس)، حدثني أخي (هو أبو بكر عبد الحميد)، عن سليمان (هو ابن بلال)، عن يونس بن يزيد، عن ابن شهاب، عن سالم بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب رفع اليدين بالدعاء عند الجمرتين الصغرى والوسطى دون جمرة العقبة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1752).","chapter_en":"Raising the Hands in Supplication at the First and Middle Jamarāt, but Not at Jamrat al-ʿAqabah","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":15,"content":{"translation":{"en":["Sālim ibn ʿAbdullāh narrated: ʿAbdullāh ibn ʿUmar would throw seven pebbles at the first Jamarah and proclaim Allah’s greatness after each pebble. He would then move forward to level ground, stand for a long time facing the qiblah, supplicate, and raise his hands. He would stone the middle Jamarah in the same manner. He would then move to the left toward level ground, stand for a long time facing the qiblah, supplicate, and raise his hands. Afterward, he would stone Jamrat al-ʿAqabah from the middle of the valley and would not remain standing there. He would say: “This is how I saw the Messenger of Allah ﷺ perform it.”"]}},"tuhfa":{},"full":1,"rep":[5181],"tks":"صحيح: رواه البخاري (1752)."},{"num":11138,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  ضَحَّى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكَبْشَيْنِ أَمْلَحَيْنِ أَقْرَنَيْنِ، ذَبَحَهُمَا بِيَدِهِ وَسَمَّى وَكَبَّرَ، وَوَضَعَ رِجْلَهُ عَلَى صِفَاحِهِمَا.","وفي رواية: ويقول: باسم الله، والله أكبر."],"takhrij":"متفق عليه: رواه البخاري في الأضاحي (5558)، ومسلم في الأضاحي (1966: 17) كلاهما من طريق قتادة، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب التسمية والتكبير عند الذبح","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5558) and Muslim (1966/17). The second wording was narrated by Muslim (1966/18).","chapter_en":"Mentioning Allah’s Name and Proclaiming His Greatness When Slaughtering","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":16,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ sacrificed two horned rams that were predominantly white with black markings. He slaughtered them with his own hand, mentioned Allah’s name, proclaimed His greatness, and placed his foot upon their sides. Another narration states that he said: “In the name of Allah, and Allah is the Greatest.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلِكُلِّ أُمَّةٍ جَعَلْنَا مَنْسَكًا لِيَذْكُرُوا اسْمَ اللّٰهِ عَلَى مَا رَزَقَهُمْ مِنْ بَهِيمَةِ الْأَنْعَامِ، فَإِلَٰهُكُمْ إِلَٰهٌ وَاحِدٌ فَلَهُ أَسْلِمُوا، وَبَشِّرِ الْمُخْبِتِينَ﴾ [سورة الحج: ٣٤]."],"en":["Allah, the Exalted, said:","“For every community We have appointed a rite of sacrifice so that they may mention the name of Allah over the grazing livestock He has provided for them. Your Allah is One Allah, so submit yourselves to Him, and give glad tidings to the humble.”","[Sūrat al-Ḥajj 22:34]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5558)، ومسلم (1966/17). والرواية الثانية عند مسلم (1966/18)."},{"num":11139,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَمَرَ بِكَبْشٍ أَقْرَنَ، يَطَأُ فِي سَوَادٍ، وَيَبْرُكُ فِي سَوَادٍ، وَيَنْظُرُ فِي سَوَادٍ، فَأُتِيَ بِهِ لِيُضَحِّيَ بِهِ، فَقَالَ لَهَا: يَا عَائِشَةُ، هَلُمِّي الْمُدْيَةَ. ثُمَّ قَالَ: اشْحَذِيهَا بِحَجَرٍ، فَفَعَلَتْ ثُمَّ أَخَذَهَا وَأَخَذَ الْكَبْشَ فَأَضْجَعَهُ، ثُمَّ ذَبَحَهُ ثُمَّ قَالَ: بِاسْمِ اللَّهِ، اللَّهُمَّ تَقَبَّلْ مِنْ مُحَمَّدٍ، وَآلِ مُحَمَّدٍ، وَمِنْ أُمَّةِ مُحَمَّدٍ. ثُمَّ ضَحَّى بِهِ."],"takhrij":"صحيح: رواه مسلم في الأضاحي (19:1967) عن هارون بن معروف، حدثنا عبدالله بن وهب قال: قال حيوة: أخبرني أبو صخْر، عن يزيد بن قُسيْط، عن عروة بن الزبير، عن عائشة، فذكرته.","grade":"صحيح","chapter_ar":"باب التسمية والتكبير عند الذبح","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1967/19).","chapter_en":"Mentioning Allah’s Name and Proclaiming His Greatness When Slaughtering","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":16,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ ordered that a horned ram be brought to him. Its feet were black, its belly was black, and the area around its eyes was black. It was brought to him so that he could sacrifice it. He said to ʿĀ’ishah: “O ʿĀ’ishah, bring me the knife.” He then said: “Sharpen it upon a stone.” She did so. He took the knife, took hold of the ram, laid it upon its side, and slaughtered it, saying: “In the name of Allah. O Allah, accept this from Muḥammad, the family of Muḥammad, and the nation of Muḥammad.” He then completed the sacrifice."]},"buhuth":{"en":["The word “sharpen it” means to make its blade sharp."]}},"tuhfa":{},"full":1,"dr":1,"rep":[7180,7200,7203],"tks":"صحيح: رواه مسلم (19:1967)."},{"num":11140,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: شَهِدْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الأَضْحَى بِالْمُصَلَّى، فَلَمَّا قَضَى خُطْبَتَهُ نَزَلَ مِنْ مِنْبَرِهِ، وَأُتِيَ بِكَبْشٍ فَذَبَحَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ، وَقَالَ: بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ، هَذَا عَنِّي وَعَمَّنْ لَمْ يُضَحِّ مِنْ أُمَّتِي."],"takhrij":"حسن: رواه أبوداود (2810)، والترمذي (1521)، وأحمد (14837، 14895) كلهم من طريق عمرو بن أبي عمرو، عن المطلب، عن جابر بن عبدالله قال: فذكره.","grade":"حسن","chapter_ar":"باب التسمية والتكبير عند الذبح","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2810), al-Tirmidhī (1521), and Aḥmad (14837, 14895).","chapter_en":"Mentioning Allah’s Name and Proclaiming His Greatness When Slaughtering","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":16,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated: I attended the Eid al-Aḍḥā prayer with the Messenger of Allah ﷺ at the outdoor prayer ground. When he finished his sermon, he descended from the pulpit. A ram was brought to him, and the Messenger of Allah ﷺ slaughtered it with his own hand, saying: “In the name of Allah, and Allah is the Greatest. This is on my behalf and on behalf of those from my nation who did not offer a sacrifice.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7186,7204],"tks":"حسن: رواه أبو داود (2810)، والترمذي (1521)، وأحمد (14837، 14895)."},{"num":11141,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ: سَأَلْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ: أُرْسِلُ كِلاَبِي الْمُعَلَّمَةَ. قَالَ: إِذَا أَرْسَلْتَ كِلاَبَكَ الْمُعَلَّمَةَ، وَذَكَرْتَ اسْمَ اللَّهِ فَأَمْسَكْنَ فَكُلْ، وَإِذَا رَمَيْتَ بِالْمِعْرَاضِ فَخَزَقَ فَكُلْ."],"takhrij":"متفق عليه: رواه البخاري في التوحيد (7397)، ومسلم في الصيد والذبائح (1929) كلاهما من طريق منصور، عن إبراهيم، عن همام بن الحارث، عن عدي بن حاتم فذكره.","grade":"متفق عليه","chapter_ar":"باب التسمية على الصيد","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7397) and Muslim (1929).","chapter_en":"Mentioning Allah’s Name over Game","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":17,"content":{"translation":{"en":["ʿAdī ibn Ḥātim narrated: I asked the Prophet ﷺ: “What if I release my trained hunting dogs?” He replied: “When you release your trained dogs and mention the name of Allah, then eat whatever they catch and hold for you. If you shoot with a broad-sided arrow and it pierces the animal, then eat it.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (7397)، ومسلم (1929)."},{"num":11142,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوِ اشْتَرَى خَادِمًا فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَهَا عَلَيْهِ، وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ.","وفي لفظ: إذا أفاد أحدُكم امرأةً، أو خادماً، أو دابّةً، فليأخذ بناصيتها، وليقُلْ: فذكر الحديث."],"takhrij":"حسن: رواه أبو داود (2160) وابن ماجه (1918) وابن السني (100) والحاكم (2/185) والبيهقي (13838) كلهم من حديث محمد بن عجلان، عن عمرو بن شعيب قال: فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند شراء الدابة أو الخادم","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2160), Ibn Mājah (1918), Ibn al-Sunnī (100), al-Ḥākim (2757), and al-Bayhaqī (7/148).","chapter_en":"What Should Be Said When Acquiring a Riding Animal or a Servant","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في الأدعية المتعلقة بالزكاة والصيام والحج والذبح والصيد والبيوع","group_en":"Collection of Narrations Concerning Supplications Related to Zakāh, Fasting, Pilgrimage, Slaughtering, Hunting, and Transactions","part_no":54,"group_no":10,"chapter_no":18,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather ʿAbdullāh ibn ʿAmr, that the Prophet ﷺ said: “When one of you marries a woman or acquires a servant, let him say: ‘O Allah, I ask You for the good within her and the good disposition upon which You created her. I seek refuge in You from the evil within her and the evil disposition upon which You created her.’ When he acquires a camel, let him take hold of the top of its hump and say the same.” Another wording states: “When one of you acquires a wife, a servant, or a riding animal, let him take hold of its forelock,” and then it mentions the same supplication."]},"buhuth":{"en":["The author said:","Likewise, when someone purchases a vehicle, it is recommended that he say:","“O Allah, I ask You for its good, and I seek refuge in You from its evil.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[11161],"tks":"حسن: رواه أبو داود (2160)، وابن ماجه (1918)، وابن السني (100)، والحاكم (2757)، والبيهقي (13838)."},{"num":11143,"demo":false,"sanad":"","matn":["عن عبد الله بن قيس (وهو أبو موسى الأشعري) أن النبي صلى الله عليه وسلم كان إذا خاف قوما قال: اللهم إنا نجعلك في نحورهم، ونعوذ بك من شرورهم."],"takhrij":"صحيح: رواه أبو داود (1537)، وأحمد (19720)، والنسائي في عمل اليوم والليلة (601)، وصحّحه ابن حبان (4765)، والحاكم (2629) كلهم من طرق عن معاذ بن هشام، حدثني أبي، عن قتادة، عن أبي بردة بن عبد الله بن قيس، عن أبيه عبد الله بن قيس -وهو أبو موسى الأشعري- فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا خاف قومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (1537), Aḥmad (19720), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (601), and authenticated by Ibn Ḥibbān (4765) and al-Ḥākim (2629).","chapter_en":"What One Should Say When Fearing a People","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Qays—who was Abū Mūsā al-Ashʿarī—narrated: When the Prophet ﷺ feared a people, he would say: “O Allah, we place You before them, and we seek refuge in You from their evil.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (1537)، وأحمد (19720)، والنسائي في عمل اليوم والليلة (601)، وصححه ابن حبان (4765)، والحاكم (2629)."},{"num":11144,"demo":false,"sanad":"","matn":["عن ابن عباس: حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ قالها إبراهيم عليه السلام حين ألقي في النار، وقالها محمد صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حين قالوا: ﴿إِنَّ النَّاسَ قَدْ جَمَعُوا لَكُمْ فَاخْشَوْهُمْ فَزَادَهُمْ إِيمَانًا وَقَالُوا حَسْبُنَا اللَّهُ وَنِعْمَ الْوَكِيلُ﴾ [سورة آل عمران: 173]."],"takhrij":"صحيح: رواه البخاري في التفسير (4563) عن أحمد بن يونس-أراه قال-حدثنا أبو بكر، عن أبي حصين، عن أبي الضحى، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا خاف قومًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in al-Tafsīr (4563), from Aḥmad ibn Yūnus—who, as the narrator recalled, said: Abū Bakr narrated to us, from Abū Ḥaṣīn, from Abū al-Ḍuḥā, from Ibn ʿAbbās.","chapter_en":"What One Should Say When Fearing a People","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās said regarding the words: “Allah is sufficient for us, and He is the best Disposer of affairs.” Abraham, peace be upon him, said them when he was thrown into the fire, and Muḥammad ﷺ said them when the people told him: “Indeed, the people have gathered against you, so fear them.” But it only increased them in faith, and they said, “Allah is sufficient for us, and He is the best Disposer of affairs.” [Sūrat Āl ʿImrān 3:173]"]}},"tuhfa":{},"full":1,"rep":[12105],"tks":"صحيح: رواه البخاري (4563)."},{"num":11145,"demo":false,"sanad":"","matn":["عَنْ سالم أَبِي النضر مولى عمر بن عبيد اللَّهِ -وَكَانَ كَاتِبًا لَهُ- قَالَ: كَتَبَ إِلَيْهِ عَبْدُ اللَّهِ بْنُ أَبِي أَوْفَى حِينَ خَرَجَ إِلَى الْحَرُورِيَّةِ فَقَرَأْتُهُ فَإِذَا فِيهِ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا الْعَدُوَّ، انْتَظَرَ حَتَّى مَالَتِ الشَّمْسُ، ثُمَّ قَامَ فِي النَّاسِ، فَقَالَ: أَيُّهَا النَّاسُ لاَ تَمَنَّوْا لِقَاءَ الْعَدُوِّ، وَسَلُوا اللَّهَ الْعَافِيَةَ، فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا، وَاعْلَمُوا أَنَّ الْجَنَّةَ تَحْتَ ظِلاَلِ السُّيُوفِ، ثُمَّ قَالَ: اللَّهُمَّ مُنْزِلَ الْكِتَابِ، وَمُجْرِيَ السَّحَابِ، وَهَازِمَ الأَحْزَابِ، اهْزِمْهُمْ، وَانْصُرْنَا عَلَيْهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3024-3025)، ومسلم في الجهاد والسير (1742: 20) كلاهما من حديث موسى بن عقبة، عن سالم أبي النضر فذكره والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الدعاء عند لقاء العدو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3024–3025) and Muslim (1742/20). The wording cited here is that of al-Bukhārī.","chapter_en":"Supplication When Meeting the Enemy","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Sālim Abū al-Naḍr, the freedman and scribe of ʿUmar ibn ʿUbaydillāh, narrated: ʿAbdullāh ibn Abī Awfā wrote to him when he went out against the Ḥarūriyyah. I read the letter, and it stated: On one of the days when the Messenger of Allah ﷺ encountered the enemy, he waited until the sun had declined. He then stood among the people and said: “O people, do not wish to meet the enemy. Ask Allah for safety and well-being. But when you meet them, remain steadfast, and know that Paradise lies beneath the shadows of swords.” He then said: “O Allah, Revealer of the Book, Mover of the clouds, and Defeater of the confederates, defeat them and grant us victory over them.”"]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَلَمَّا بَرَزُوا لِجَالُوتَ وَجُنُودِهِ قَالُوا رَبَّنَا أَفْرِغْ عَلَيْنَا صَبْرًا، وَثَبِّتْ أَقْدَامَنَا، وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾ [سورة البقرة: ٢٥٠].","وقال تعالى: ﴿وَكَأَيِّنْ مِنْ نَبِيٍّ قَاتَلَ مَعَهُ رِبِّيُّونَ كَثِيرٌ، فَمَا وَهَنُوا لِمَا أَصَابَهُمْ فِي سَبِيلِ اللّٰهِ، وَمَا ضَعُفُوا وَمَا اسْتَكَانُوا، وَاللّٰهُ يُحِبُّ الصَّابِرِينَ ۝ وَمَا كَانَ قَوْلَهُمْ إِلَّا أَنْ قَالُوا رَبَّنَا اغْفِرْ لَنَا ذُنُوبَنَا وَإِسْرَافَنَا فِي أَمْرِنَا، وَثَبِّتْ أَقْدَامَنَا، وَانْصُرْنَا عَلَى الْقَوْمِ الْكَافِرِينَ﴾ [سورة آل عمران: ١٤٦-١٤٧]."],"en":["Allah, the Exalted, said:","“When they advanced to face Goliath and his forces, they said, ‘Our Lord, pour patience upon us, make our feet firm, and grant us victory over the disbelieving people.’”","[Sūrat al-Baqarah 2:250]","And He, the Exalted, said:","“How many a prophet fought alongside many devoted followers! They neither lost heart because of what afflicted them in the cause of Allah, nor did they weaken or submit. Allah loves those who remain patient. Their only words were, ‘Our Lord, forgive us our sins and our excesses in our affairs, make our feet firm, and grant us victory over the disbelieving people.’”","[Sūrat Āl ʿImrān 3:146–147]"]}},"tuhfa":{},"full":1,"rep":[7830],"tks":"متفق عليه: رواه البخاري (3024-3025)، ومسلم (1742: 20)، والسياق للبخاري."},{"num":11146,"demo":false,"sanad":"","matn":["عَنْ الْبَرَاءِ بْنِ عَازِبٍ فِي قِصَّةِ غزوة حُنَيْنٍ قَالَ: فَأَقْبَلَ الْقَوْمُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَأَبُو سُفْيَانَ بْنُ الْحَارِثِ يَقُودُ بِهِ بَغْلَتَهُ، فَنَزَلَ وَدَعَا وَاسْتَنْصَرَ وَهُوَ يَقُولُ: أَنَا النَّبِيُّ لَا كَذِبْ أَنَا ابْنُ عَبْدِ الْمُطَّلِبْ اللَّهُمَّ نزِّلْ نَصْرَكَ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2930) ومسلم في الجهاد والسير (1776: 79) كلاهما من طرق عن أبي إسحاق عن البراء فذكره.والسياق لمسلم.","grade":"متفق عليه","chapter_ar":"باب ما جاء في الدعاء عند لقاء العدو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2930) and Muslim (1776/79). The wording cited here is that of Muslim.","chapter_en":"Supplication When Meeting the Enemy","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib narrated concerning the Battle of Ḥunayn: The people returned toward the Messenger of Allah ﷺ while Abū Sufyān ibn al-Ḥārith was leading his mule. The Prophet ﷺ dismounted, supplicated, and sought victory, saying: “I am the Prophet—there is no falsehood in that. I am the son of ʿAbd al-Muṭṭalib. O Allah, send down Your victory.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (2930)، ومسلم (1776: 79)، والسياق لمسلم."},{"num":11147,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا غَزَا قَالَ: اللَّهُمَّ أَنْتَ عَضُدِي وَنَصِيرِي، بِكَ أَحُولُ، وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ."],"takhrij":"صحيح: رواه أبو داود (2632)، والترمذي (3584)، وأحمد (12909/2)، وصحّحه ابن حبان (4761) من طرق عن المثنى بن سعيد، عن قتادة، عن أنس بن مالك فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الدعاء عند لقاء العدو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2632), al-Tirmidhī (3584), and Aḥmad (12909), and authenticated by Ibn Ḥibbān (4761).","chapter_en":"Supplication When Meeting the Enemy","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated: When the Messenger of Allah ﷺ set out on a military expedition, he would say: “O Allah, You are my support and my helper. Through You I maneuver, through You I charge, and through You I fight.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[7879],"tks":"صحيح: رواه أبو داود (2632)، والترمذي (3584)، وأحمد (12909)، وصححه ابن حبان (4761)."},{"num":11148,"demo":false,"sanad":"","matn":["عَنْ صُهَيْبٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَقُولُ: إِذَا لَقِيَ الْعَدُوَّ: اللهُمَّ بِكَ أَحُولُ، وَبِكَ أَصُولُ، وَبِكَ أُقَاتِلُ."],"takhrij":"صحيح: رواه أحمد (23928) عن روح، حدثنا حماد، عن ثابت، عن عبدالرحمن بن أبي ليلى، عن صهيب فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في الدعاء عند لقاء العدو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (23928).","chapter_en":"Supplication When Meeting the Enemy","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":2,"content":{"translation":{"en":["Ṣuhayb narrated: When the Messenger of Allah ﷺ encountered the enemy, he would say: “O Allah, through You I maneuver, through You I charge, and through You I fight.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أحمد (23928)."},{"num":11149,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: صَبَّحَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ وَقَدْ خَرَجُوا بِالْمَسَاحِي عَلَى أَعْنَاقِهِمْ، فَلَمَّا رَأَوْهُ قَالُوا: هَذَا مُحَمَّدٌ وَالْخَمِيسُ، مُحَمَّدٌ وَالْخَمِيسُ. فَلَجَئُوا إِلَى الْحِصْنِ، فَرَفَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، وَقَالَ: اللَّهُ أَكْبَرُ، خَرِبَتْ خَيْبَرُ، إِنَّا إِذَا نَزَلْنَا بِسَاحَةِ قَوْمٍ فَسَاءَ صَبَاحُ الْمُنْذَرِينَ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2991)، ومسلم في الصيد والذبائح (1940) كلاهما من طريق أيوب، عن محمد (هو ابن سيرين)، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب التكبير في الحرب","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2991) and Muslim (1940). The wording cited here is that of al-Bukhārī.","chapter_en":"Proclaiming Allah’s Greatness during Battle","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":3,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ arrived at Khaybar in the morning. Its people had come out carrying their farming tools upon their shoulders. When they saw him, they cried: “Muḥammad and the army! Muḥammad and the army!” They fled back into the fortress. The Prophet ﷺ raised his hands and said: “Allah is the Greatest! Khaybar is ruined. When we descend upon the territory of a people, terrible is the morning of those who were warned.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2991)، ومسلم (1940)، واللفظ للبخاري."},{"num":11150,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: قُلْنَا لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَوْمَ الْخَنْدَقِ وَقَدْ بَلَغَ مِنَّا الْجَهْدُ: هَلْ مِنْ شَيْءٍ نَقُولُهُ؟ قَالَ: قُولُوا: اللَّهُمَّ اسْتُرْ عَوْرَاتِنَا، وَآمِنْ رَوْعَاتِنَا.قَالَ: فهزم اللَّهُ بِالرِّيحِ."],"takhrij":"حسن: رواه البزار – كشف الأستار (3119) عن محمد بن المثنى، ثنا أبو عامر عبدالملك بن عمرو، ثنا الزبير بن عبد الله، ويقال: ابن رهيمة من أهل المدينة، عن ربيح بن عبد الرحمن بن أبي سعيد، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عندما يشتد أمر العدو","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār in Kashf al-Astār (3119).","chapter_en":"What Should Be Said When the Enemy’s Threat Becomes Severe","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":4,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: On the Day of the Trench, when hardship had become severe for us, we asked the Messenger of Allah ﷺ: “Is there anything we should say?” He replied: “Say: ‘O Allah, conceal our vulnerabilities and grant security from our fears.’” Allah then defeated the enemy by means of the wind."]}},"tuhfa":{},"full":1,"dr":1,"rep":[8928,13044],"tks":"حسن: رواه البزار في كشف الأستار (3119)."},{"num":11151,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ يَزِيدَ الْخَطْمِيِّ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا شَيَّعَ جَيْشًا فَبَلَغَ عَقَبَةَ الْوَدَاعِ، قَالَ: أَسْتَوْدِعُ اللهَ دِينَكُمْ، وَأَمَانَتَكُمْ، وَخَوَاتِمَ أَعْمَالِكُمْ."],"takhrij":"صحيح: رواه أبو داود (2601)، والنسائي في الكبرى (10288) واللفظ له، والحاكم (2/97-98) كلهم من طريق حماد بن سلمة، عن أبي جعفر الخطمي، عن محمد بن كعب، عن عبد الله الخطمي قال: فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقال عند توديع الجيوش","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2601), al-Nasā’ī in al-Sunan al-Kubrā (10288), whose wording is cited here, and al-Ḥākim (2478).","chapter_en":"What Should Be Said When Bidding Farewell to Armies","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الجهاد","group_en":"Collection of Narrations Concerning Supplications for Jihād","part_no":54,"group_no":11,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Yazīd al-Khaṭmī narrated: When the Messenger of Allah ﷺ accompanied an army as it departed and reached Thaniyyat al-Wadāʿ, he would say: “I entrust to Allah your religion, your trusts, and the conclusions of your deeds.”"]}},"tuhfa":{},"full":1,"rep":[7850],"tks":"صحيح: رواه أبو داود (2601)، والنسائي في السنن الكبرى (10288)، واللفظ له، والحاكم (2/97-98)."},{"num":11152,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِنَّ الْحَمْدَ لِلهِ نَحْمَدُهُ وَنَسْتَعِينُهُ، مَنْ يَهْدِهِ اللهُ فَلَا مُضِلَّ لَهُ، وَمَنْ يُضْلِلْ فَلَا هَادِيَ لَهُ، وَأَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، وَأَنَّ مُحَمَّدًا عَبْدُهُ وَرَسُولُهُ، أَمَّا بَعْدُ:."],"takhrij":"صحيح: رواه مسلم في الجمعة (868) من طرق عن عبد الأعلى (وهو أبو همام)، حدثنا داود (بن أبي هند) عن عمرو بن سعيد، عن سعيد بن جبير، عن ابن عباس فذكره، وفيه قصة.","grade":"صحيح","chapter_ar":"باب ما جاء في خطبة النكاح","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (868).","chapter_en":"Narrations Concerning the Marriage Sermon","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās narrated that the Prophet ﷺ said: “Indeed, all praise belongs to Allah. We praise Him and seek His assistance. Whoever Allah guides, none can lead astray, and whoever He allows to stray, none can guide. I testify that there is no deity worthy of worship except Allah alone, without partner, and that Muḥammad is His servant and Messenger. To proceed.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (868)."},{"num":11153,"demo":false,"sanad":"","matn":["عن عبدالله بن مسعود قال : أوتي رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جوامع الخير، وخواتمه، أو قال فواتح الخير، فعلمنا خطبة الصلاة وخطبة الحاجة، خطبة الصلاة: التحيات الله والصلوات والطيبات، السلام عليك أيها النبي ورحمة الله وبركاته.السلام علينا وعلى عباد الله الصالحين، أشهد أن لا إله إلا الله وأشهد أن محمدًا عبده ورسوله، وخطبة الحاجة: أن الحمد لله نحمده ونستعينه ونستغفره ونعوذ بالله من شرور أنفسنا ومن سيئات أعمالنا، من يهده الله فلا مضل له، ومن يضلل فلا هادي له، وأشهد أن لا إله إلا الله وحده لا شريك له، وأشهد أن محمدا عبده ورسوله، ثم تصل خطبتك بثلاث آيات من كتاب الله ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ حَقَّ تُقَاتِهِ وَلَا تَمُوتُنَّ إِلَّا وَأَنْتُمْ مُسْلِمُونَ﴾ [سورة آل عمران: ١٠٢] ﴿يَا أَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمُ الَّذِي خَلَقَكُمْ مِنْ نَفْسٍ وَاحِدَةٍ وَخَلَقَ مِنْهَا زَوْجَهَا وَبَثَّ مِنْهُمَا رِجَالًا كَثِيرًا وَنِسَاءً وَاتَّقُوا اللَّهَ الَّذِي تَسَاءَلُونَ بِهِ وَالْأَرْحَامَ إِنَّ اللَّهَ كَانَ عَلَيْكُمْ رَقِيبًا﴾ [سورة النساء:١] ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَقُولُوا قَوْلًا سَدِيدًا (70) يُصْلِحْ لَكُمْ أَعْمَالَكُمْ وَيَغْفِرْ لَكُمْ ذُنُوبَكُمْ﴾ [سورة الأحزاب: 70-71 [."],"takhrij":"صحيح: رواه أبو داود (2118)، والترمذي (1105) والنسائي (3277) وابن ماجه (1892) كلهم من طرق عن أبي إسحاق، عن أبي الأحوص، عن عبدالله بن مسعود فذكره وصحّحه ابن خزيمة (270) وابن حبان (1952) ومنهم من اقتصر على التشهد في الصلاة فقط.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في خطبة النكاح","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2118), al-Tirmidhī (1105), al-Nasā’ī (3277), and Ibn Mājah (1892).","chapter_en":"Narrations Concerning the Marriage Sermon","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":1,"content":{"translation":{"en":["Ibn Masʿūd narrated: The Messenger of Allah ﷺ was granted comprehensive words encompassing the beginnings and conclusions of goodness—or he said, the openings of goodness. He taught us the sermon of the prayer and the sermon of need. The sermon of the prayer is: “All greetings belong to Allah, as do the prayers and pure words. Peace be upon you, O Prophet, and the mercy of Allah and His blessings. Peace be upon us and upon the righteous servants of Allah. I testify that there is no deity worthy of worship except Allah, and I testify that Muḥammad is His servant and Messenger.” The sermon of need is: “Indeed, all praise belongs to Allah. We praise Him, seek His assistance, and seek His forgiveness. We seek refuge in Allah from the evils of our souls and the wickedness of our deeds. Whoever Allah guides, none can lead astray, and whoever He allows to stray, none can guide. I testify that there is no deity worthy of worship except Allah alone, without partner, and I testify that Muḥammad is His servant and Messenger.” Then the speaker should connect his sermon with three verses from the Book of Allah: “O you who believe, fear Allah as He truly deserves to be feared, and do not die except as Muslims.” [Sūrat Āl ʿImrān 3:102] “O humanity, fear your Lord, who created you from a single soul and created from it its mate, and spread from the two of them many men and women. Fear Allah, in whose name you appeal to one another, and honor family ties. Indeed, Allah is ever Watchful over you.” [Sūrat al-Nisāʾ 4:1] “O you who believe, fear Allah and speak words of truth and justice. He will rectify your deeds for you and forgive your sins.” [Sūrat al-Aḥzāb 33:70–71]"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه أبو داود (2118)، والترمذي (1105)، والنسائي (3277)، وابن ماجه (1892)."},{"num":11154,"demo":false,"sanad":"","matn":["عن جابر بن عبد الله قال في حديث طويل: قال لي رسول الله صلى الله عليه وسلم: تزوجت يا جابر؟ فقلت: نعم...فقال: بارك الله لك.أو قال لي خيرا.وفي رواية: فبارك الله عليك."],"takhrij":"متفق عليه: رواه البخاري في النفقات (5367)، ومسلم في الرضاع (715: 56) كلاهما من طريق حماد بن زيد، عن عمرو بن دينار، عن جابر بن عبد الله فذكره في حديث طويل.واللفظ الثاني رواه البخاري في الدعوات (6387) من وجه آخر عن حماد به.","grade":"متفق عليه","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5367) and Muslim (715/56). The second wording was narrated by al-Bukhārī (6387).","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated in a lengthy hadith: The Messenger of Allah ﷺ asked me: “Have you married, O Jābir?” I replied: “Yes.” He said: “May Allah bless you.” Or he spoke other words of goodness to me. Another narration states: “May Allah place blessings upon you.”"]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (5367)، ومسلم (715: 56). واللفظ الثاني رواه البخاري (6387)."},{"num":11155,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَأَى النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى عَبْدِ الرَّحْمَنِ بْنِ عَوْفٍ أَثَرَ صُفْرَةٍ فَقَالَ: مَهْيَمْ. أَوْ مَهْ. قَالَ: تَزَوَّجْتُ امْرَأَةً عَلَى وَزْنِ نَوَاةٍ مِنْ ذَهَبٍ. فَقَالَ: بَارَكَ اللَّهُ لَكَ، أَوْلِمْ وَلَوْ بِشَاةٍ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6386) ومسلم في النكاح (1427: 79) كلاهما من حديث حماد بن زيد، عن ثابت عن أنس فذكره واللفظ للبخاري.","grade":"متفق عليه","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6386) and Muslim (1427/79). The wording cited here is that of al-Bukhārī.","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: The Prophet ﷺ saw traces of yellow perfume upon ʿAbd al-Raḥmān and asked: “What is this?” He replied: “I married a woman for a dowry equal in weight to a date-stone of gold.” The Prophet ﷺ said: “May Allah bless you. Hold a wedding feast, even if only with one sheep.”"]}},"tuhfa":{},"full":1,"rep":[6244],"tks":"متفق عليه: رواه البخاري (6386)، ومسلم (1427: 79)، واللفظ للبخاري."},{"num":11156,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: بُنِيَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِزَيْنَبَ ابْنَةِ جَحْشٍ بِخُبْزٍ وَلَحْمٍ، فَأُرْسِلْتُ عَلَى الطَّعَامِ دَاعِيًا، فَيَجِيءُ قَوْمٌ فَيَأْكُلُونَ وَيَخْرُجُونَ، ثُمَّ يَجِيءُ قَوْمٌ فَيَأْكُلُونَ وَيَخْرُجُونَ، فَدَعَوْتُ حَتَّى مَا أَجِدُ أَحَدًا أَدْعُو فَقُلْتُ يَا نَبِيَّ اللَّهِ مَا أَجِدُ أَحَدًا أَدْعُوهُ قَالَ ارْفَعُوا طَعَامَكُمْ، وَبَقِيَ ثَلاَثَةُ رَهْطٍ يَتَحَدَّثُونَ فِي الْبَيْتِ، فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَانْطَلَقَ إِلَى حُجْرَةِ عَائِشَةَ فَقَالَ: السَّلاَمُ عَلَيْكُمْ أَهْلَ الْبَيْتِ وَرَحْمَةُ اللَّهِ. فَقَالَتْ: وَعَلَيْكَ السَّلاَمُ وَرَحْمَةُ اللَّهِ، كَيْفَ وَجَدْتَ أَهْلَكَ، بَارَكَ اللَّهُ لَكَ فَتَقَرَّى."],"takhrij":"متفق عليه: رواه البخاري في التفسير (4793) عن أبي معمر، ثنا عبد الوارث، ثنا عبدالعزيز بن صهيب، عن أ نس فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4793) and Muslim (1428).","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Anas narrated: When the Prophet ﷺ consummated his marriage with Zaynab bint Jaḥsh, bread and meat were served. I was sent to invite people to the meal. Groups came, ate, and left. Then other groups came, ate, and left. I continued inviting people until I could find no one else to invite. I said: “O Prophet of Allah, I cannot find anyone else to invite.” He said: “Clear away your food.” Three men remained in the house speaking with one another. The Prophet ﷺ went out and proceeded to ʿĀ’ishah’s apartment, where he said: “Peace be upon you, people of the household, and the mercy of Allah.” She replied: “And peace and the mercy of Allah be upon you. How did you find your wife? May Allah bless you…” This forms part of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4793)، ومسلم (1428)."},{"num":11157,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَفَّأَ الإِنْسَانَ إِذَا تَزَوَّجَ قَالَ بَارَكَ اللَّهُ لَكَ، وَبَارَكَ عَلَيْكَ، وَجَمَعَ بَيْنَكُمَا فِي خَيْرٍ."],"takhrij":"حسن: رواه أبو داود (2130) والترمذي (1091) وابن ماجه (1905) وأحمد (8956) والدارمي (2220) وابن حبان (4052) والحاكم (2745) كلهم من حديث عبد العزيز بن محمد الدراوردي ، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2130), al-Tirmidhī (1091), Ibn Mājah (1905), Aḥmad (8956), al-Dārimī (2220), Ibn Ḥibbān (4052), and al-Ḥākim (2745).","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah narrated: When the Prophet ﷺ congratulated a person upon marriage, he would say: “May Allah bless you, place blessings upon you, and unite the two of you in goodness.”"]},"buhuth":{"en":["The word raffaʾa, with a doubled letter fāʾ, means to congratulate someone."]}},"tuhfa":{},"full":1,"dr":1,"rep":[6246],"tks":"حسن: رواه أبو داود (2130)، والترمذي (1091)، وابن ماجه (1905)، وأحمد (8956)، والدارمي (2220)، وابن حبان (4052)، والحاكم (2745)."},{"num":11158,"demo":false,"sanad":"","matn":["عَنِ الْحَسَنِ، قَالَ: تَزَوَّجَ عَقِيلُ بْنُ أَبِي طَالِبٍ امْرَأَةً مِنْ بَنِي جُشَمٍ، فَقِيلَ لَهُ: بِالرِّفَاءِ وَالْبَنِينِ. قَالَ قُولُوا كَمَا قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: بَارَكَ اللَّهُ فِيكُمْ، وَبَارَكَ لَكُمْ."],"takhrij":"صحيح: رواه النسائي (3371) واللفظ له، وابن ماجه (1906) وأحمد (1739) والبيهقي (7/148) والدارمي (2119) كلهم من طرق عن الحسن قال فذكره.ولفظ البيهقي: قدم عقيل بن أبي طالب البصرة","grade":"صحيح","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (3371), whose wording is cited here, Ibn Mājah (1906), Aḥmad (1739), al-Bayhaqī (7/148), and al-Dārimī (2119).","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Al-Ḥasan narrated: ʿAqīl ibn Abī Ṭālib married a woman from Banū Jusham. People said to him: “May there be harmony and many sons.” He replied: “Say what the Messenger of Allah ﷺ said: ‘May Allah bless you and grant blessings for you.’”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[6247],"tks":"صحيح: رواه النسائي (3371)، واللفظ له، وابن ماجه (1906)، وأحمد (1739)، والبيهقي (7/148)، والدارمي (2119)."},{"num":11159,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ قَالَ: قَالَ نَفَرٌ مِنَ الْأَنْصَارِ لِعَلِيٍّ: عِنْدَكَ فَاطِمَةُ.فَأَتَى رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: مَا حَاجَةُ ابْنِ أَبِي طَالِبٍ؟ قَالَ: ذَكَرْتُ فَاطِمَةَ بِنْتَ مُحَمَّدٍ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَرْحَبًا وَأَهْلًا.لَمْ يَزِدْهُ عَلَيْهِمَا.فَخَرَجَ عَلِيُّ عَلَى أُولَئِكَ الرَّهْطِ مِنَ الْأَنْصَارِ يَنْتَظِرُونَهُ.قَالُوا: مَا وَرَاءَكَ؟ قَالَ: مَا أَدْرِي غَيْرَ أَنَّهُ قَالَ لِي: مَرْحَبًا وَأَهْلًا.قَالُوا: يَكْفِيكَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِحْدَاهُمَا.أَعْطَاكَ الْأَهْلَ أَعْطَاكَ المرحب، فَلَمَّا كَانَ بَعْدَمَا زَوَّجَهُ قَالَ: يَا عَلِيُّ إِنَّهُ لَا بُدَّ لِلْعَرُوسِ مِنْ وَلِيمَةٍ فَقَالَ سَعْدٌ: عِنْدِي كَبْشٌ، وَجَمَعَ لَهُ رهط مِنَ الْأَنْصَارِ آصعاً مِنْ ذُرَةٍ.فَلَمَّا كَانَ لَيْلَةُ الْبِنَاءِ قَالَ: لَا تُحْدِثْ شَيْئًا حَتَّى تَلْقَانِي.قَالَ: فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِنَاءٍ فَتَوَضَّأَ مِنْهُ، ثُمَّ أَفْرَغَهُ على علي، ثُمَّ قَالَ: اللَّهُمَّ بَارِكْ فِيهِمَا، وَبَارِكْ عَلَيْهِمَا وَبَارِكْ لَهُمَا فِي نسلهما."],"takhrij":"حسن: رواه ابن سعد (6895) والطبراني في الكبير (1153) والطحاوي في مشكله (5947) والنسائي في اليوم والليلة (258) وأحمد (23035) مختصرا كلهم من حديث عبد الكريم بن سليط عن ابن بريدة، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Saʿd (8/21), al-Ṭabarānī in al-Muʿjam al-Kabīr (2/4), al-Ṭaḥāwī in Mushkil al-Āthār (5947), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (258), and Aḥmad (23035) in an abbreviated form.","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["Buraydah narrated: A group from the Anṣār said to ʿAlī: “You should ask for Fāṭimah.” He went to the Messenger of Allah ﷺ and greeted him. The Prophet ﷺ asked: “What does the son of Abū Ṭālib need?” ʿAlī replied: “I have come to mention Fāṭimah, the daughter of Muḥammad, the Messenger of Allah ﷺ.” He said: “Welcome, and you are among family.” He added nothing beyond those two expressions. ʿAlī went out to the group of Anṣār who were waiting for him. They asked: “What happened?” He replied: “I do not know, except that he said to me, ‘Welcome, and you are among family.’” They said: “Either one of those statements from the Messenger of Allah ﷺ would have been enough for you. He granted you welcome and granted you family.” After the Prophet ﷺ married her to him, he said: “O ʿAlī, a wedding must have a feast.” Saʿd said: “I have a ram.” A group of the Anṣār gathered several measures of millet for him. On the night the marriage was to be consummated, the Prophet ﷺ said: “Do not do anything until you meet me.” The Messenger of Allah ﷺ then requested a vessel of water, performed ablution from it, poured the remaining water over ʿAlī, and said: “O Allah, bless them both, place blessings upon them, and bless them in their offspring.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن سعد (6895)، والطبراني في الكبير (1153)، والطحاوي في مشكل الآثار (5947)، والنسائي في عمل اليوم والليلة (258)، وأحمد (23035) مختصرا."},{"num":11160,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ: تَزَوَّجَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَدْخَلَتْنِي أُمِّي بَيْتًا فَإِذَا نِسْوَةٌ مِنَ الأَنْصَارِ قُلْنَ: عَلَى الْخَيْرِ وَالْبَرَكَةِ، وَعَلَى خَيْرِ طَائِرٍ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3894) ومسلم في النكاح (1422) كلاهما عن هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما يقال لمن تزوج","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3894) and Muslim (1422).","chapter_en":"What Should Be Said to Someone Who Marries","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ married me, and my mother brought me into a house. Some women from the Anṣār were present and said: “May this be upon goodness and blessing, and upon the best fortune.”"]},"buhuth":{"en":["The expression “upon the best fortune” means upon the finest share and destiny. A person’s ṭāʾir refers to his allotted fortune."]}},"tuhfa":{},"full":1,"dr":1,"rep":[6245],"tks":"متفق عليه: رواه البخاري (3894)، ومسلم (1422)."},{"num":11161,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: إِذَا تَزَوَّجَ أَحَدُكُمُ امْرَأَةً، أَوِ اشْتَرَى خَادِمًا فَلْيَقُلِ: اللَّهُمَّ إِنِّي أَسْأَلُكَ خَيْرَهَا، وَخَيْرَ مَا جَبَلْتَهَا عَلَيْهِ، وَأَعُوذُ بِكَ مِنْ شَرِّهَا وَمِنْ شَرِّ مَا جَبَلْتَهَا عَلَيْهِ، وَإِذَا اشْتَرَى بَعِيرًا فَلْيَأْخُذْ بِذِرْوَةِ سَنَامِهِ وَلْيَقُلْ مِثْلَ ذَلِكَ.","وفي لفظ: إذا أفاد أحدُكم امرأةً، أو خادماً، أو دابّةً، فليأخذ بناصيتها، وليقُلْ: فذكر الحديث."],"takhrij":"حسن: رواه أبو داود (2160) وابن ماجه (1918) وابن السني في عمل اليوم والليلة (100) والحاكم (2/185) والبيهقي (13838) كلهم من حديث محمد بن عجلان، عن عمرو بن شعيب، بإسناده مثله.","grade":"حسن","chapter_ar":"باب ما يقول الرجل إذا تزوج امرأة","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2160), Ibn Mājah (1918), Ibn al-Sunnī (100), al-Ḥākim (2757), and al-Bayhaqī (7/148).","chapter_en":"What a Man Should Say When He Marries a Woman","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":3,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb narrated from his father, from his grandfather ʿAbdullāh ibn ʿAmr, that the Prophet ﷺ said: “When one of you marries a woman or acquires a servant, let him say: ‘O Allah, I ask You for the good within her and the good disposition upon which You created her. I seek refuge in You from the evil within her and the evil disposition upon which You created her.’ If he acquires a camel, let him take hold of the top of its hump and say the same.” Another wording states: “When one of you acquires a wife, a servant, or a riding animal, let him take hold of its forelock,” and then it mentions the same supplication."]}},"tuhfa":{},"full":1,"dr":1,"rep":[11142],"tks":"حسن: رواه أبو داود (2160)، وابن ماجه (1918)، وابن السني (100)، والحاكم (2757)، والبيهقي (13838)."},{"num":11162,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ أَنَّ أَحَدَهُمْ إِذَا أَرَادَ أَنْ يَأْتِيَ أَهْلَهُ قَالَ: بِاسْمِ اللَّهِ، اللَّهُمَّ جَنِّبْنَا الشَّيْطَانَ، وَجَنِّبِ الشَّيْطَانَ مَا رَزَقْتَنَا، فَإِنَّهُ إِنْ يُقَدَّرْ بَيْنَهُمَا وَلَدٌ فِي ذَلِكَ، لَمْ يَضُرَّهُ شَيْطَانٌ أَبَدًا."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6388)، ومسلم في النكاح (1434) كلاهما من طريق جرير، عن منصور، عن سالم بن أبي الجعد، عن كُريب، عن ابن عباس، فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقول إذا أراد أن يأتي أهله","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6388) and Muslim (1434).","chapter_en":"What a Man Should Say When He Intends to Have Relations with His Wife","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية النكاح وما يتعلق به","group_en":"Collection of Narrations Concerning Supplications for Marriage and Related Matters","part_no":54,"group_no":12,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās narrated that the Prophet ﷺ said: “If, when one of them intends to have relations with his wife, he says, ‘In the name of Allah. O Allah, keep Satan away from us and keep Satan away from whatever You provide for us,’ then if a child is decreed for them through that union, Satan will never harm that child.”"]},"buhuth":{"en":["Regarding the words “Satan will never harm that child,” al-Qāḍī ʿIyāḍ said:","It has been said that the intended harm is that the child will not suffer seizure. It has also been said that Satan will not pierce him at the time of birth. No scholar understood it as an absolute protection from every form of harm, whispering, and temptation.","Sharḥ Ṣaḥīḥ Muslim (5/10)."]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6388)، ومسلم (1434)."},{"num":11163,"demo":false,"sanad":"","matn":["عن عُمَرَ بن أَبِي سَلَمَةَ يَقُولُ كُنْتُ غُلاَمًا فِي حَجْرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَكَانَتْ يَدِي تَطِيشُ فِي الصَّحْفَةِ، فَقَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا غُلاَمُ سَمِّ اللَّهَ، وَكُلْ بِيَمِينِكَ، وَكُلْ مِمَّا يَلِيكَ. فَمَا زَالَتْ تِلْكَ طِعْمَتِي بَعْدُ."],"takhrij":"متفق عليه: رواه البخاري في الأطعمة (5376)، ومسلم في الأشربة (2022: 108) كلاهما من طريق سفيان بن عيينة، عن الوليد بن كثير، عن وهب بن كيسان أنه سمع عمر بن أبي سلمة يقول فذكره.","grade":"متفق عليه","chapter_ar":"باب التسمية على الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5376) and Muslim (2022/108).","chapter_en":"Mentioning Allah’s Name over Food","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["ʿUmar ibn Abī Salamah narrated: I was a young boy under the care of the Messenger of Allah ﷺ, and my hand would move around the entire dish while eating. The Messenger of Allah ﷺ said to me: “Young boy, mention the name of Allah, eat with your right hand, and eat from what is directly in front of you.” That continued to be my manner of eating afterward."]}},"tuhfa":{},"full":1,"rep":[14302],"tks":"متفق عليه: رواه البخاري (5376)، ومسلم (2022: 108)."},{"num":11164,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  إِذَا دَخَلَ الرَّجُلُ بَيْتَهُ فَذَكَرَ اللهَ عِنْدَ دُخُولِهِ وَعِنْدَ طَعَامِهِ، قَالَ الشَّيْطَانُ: لَا مَبِيتَ لَكُمْ وَلَا عَشَاءَ، وَإِذَا دَخَلَ فَلَمْ يَذْكُرِ اللَّهَ عِنْدَ دُخُولِهِ، قَالَ الشَّيْطَانُ: أَدْرَكْتُمُ الْمَبِيتَ، وَإِذَا لَمْ يَذْكُرِ اللَّهَ عِنْدَ طَعَامِهِ قَالَ: أَدْرَكْتُمُ الْمَبِيتَ وَالْعَشَاءَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2018) عن محمد بن المثنى العنزي، ثنا الضحاك أبو عاصم، عن ابن جريج، أخبرني أبو الزبير، عن جابر بن عبدالله فذكره.","grade":"صحيح","chapter_ar":"باب التسمية على الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2018).","chapter_en":"Mentioning Allah’s Name over Food","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh narrated that he heard the Prophet ﷺ say: “When a man enters his home and mentions Allah at the time of entering and when eating, Satan says, ‘You have no place to spend the night and no evening meal.’ If he enters without mentioning Allah, Satan says, ‘You have secured a place to spend the night.’ If he also fails to mention Allah when eating, Satan says, ‘You have secured both lodging and an evening meal.’”"]}},"tuhfa":{},"full":1,"rep":[8227,11304,14304],"tks":"صحيح: رواه مسلم (2018)."},{"num":11165,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ قَالَ:  كُنَّا إِذَا حَضَرْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ طَعَامًا، لَمْ نَضَعْ أَيْدِيَنَا، حَتَّى يَبْدَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَيَضَعَ يَدَهُ، وَإِنَّا حَضَرْنَا مَعَهُ مَرَّةً طَعَامًا، فَجَاءَتْ جَارِيَةٌ كَأَنَّهَا تُدْفَعُ، فَذَهَبَتْ لِتَضَعَ يَدَهَا فِي الطَّعَامِ، فَأَخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهَا، ثُمَّ جَاءَ أَعْرَابِيٌّ كَأَنَّمَا يُدْفَعُ، فَأَخَذَ بِيَدِهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ الشَّيْطَانَ يَسْتَحِلُّ الطَّعَامَ أَنْ لَا يُذْكَرَ اسْمُ اللَّهِ عَلَيْهِ، وَإِنَّهُ جَاءَ بِهَذِهِ الْجَارِيَةِ لِيَسْتَحِلَّ بِهَا، فَأَخَذْتُ بِيَدِهَا، فَجَاءَ بِهَذَا الْأَعْرَابِيِّ، لِيَسْتَحِلَّ بِهِ فَأَخَذْتُ بِيَدِهِ، وَالَّذِي نَفْسِي بِيَدِهِ، إِنَّ يَدَهُ فِي يَدِي مَعَ يَدِهَا."],"takhrij":"صحيح: رواه مسلم في الأشربة (2017) من طريق أبي معاوية، عن الأعمش، عن خيثمة، عن أبي حذيفة، عن حذيفة فذكره.","grade":"صحيح","chapter_ar":"باب التسمية على الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2017).","chapter_en":"Mentioning Allah’s Name over Food","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":1,"content":{"translation":{"en":["Ḥudhayfah narrated: Whenever we attended a meal with the Prophet ﷺ, we would not place our hands into the food until the Messenger of Allah ﷺ began by placing his hand into it. On one occasion, we attended a meal with him. A young girl came as though she were being pushed forward and reached out to place her hand into the food. The Messenger of Allah ﷺ took hold of her hand. Then a Bedouin came as though he too were being pushed forward, and the Prophet ﷺ took hold of his hand. The Messenger of Allah ﷺ said: “Satan considers food lawful for himself when Allah’s name has not been mentioned over it. He brought this young girl so that he might make the food lawful through her, so I took hold of her hand. Then he brought this Bedouin so that he might make it lawful through him, so I took hold of his hand. By the One in whose hand is my soul, Satan’s hand is in my hand together with her hand.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2017)."},{"num":11166,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ نَسِيَ أَنْ يَذْكُرَ اللَّهَ فِي أَوَّلِ طَعَامِهِ فَلْيَقُلْ حِينَ يَذْكُرُ: بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ فَإِنَّهُ يَسْتَقْبِلُ طَعَامَهُ جَدِيدًا، وَيَمْنَعُ الْخَبِيثَ مَا كَانَ يُصِيبُ مِنْهُ."],"takhrij":"صحيح: رواه ابن حبان (5213)، وابن السني (460)، والطبراني في الكبير (10354) كلهم من طريق خليفة بن خياط، حدثنا عمر بن علي المقدمي قال: سمعت موسى الجهني يقول: أخبرني القاسم بن عبد الرحمن بن عبد الله بن مسعود، عن أبيه، عن جده عبد الله بن مسعود فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقول من نسي التسمية عند ابتداء الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (5213), Ibn al-Sunnī (460), and al-Ṭabarānī in al-Muʿjam al-Kabīr (10/210).","chapter_en":"What One Should Say If He Forgets to Mention Allah’s Name at the Beginning of a Meal","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated that the Messenger of Allah ﷺ said: “Whoever forgets to mention Allah at the beginning of his meal should say when he remembers: ‘In the name of Allah at its beginning and its end.’ He will then begin his meal anew, and the wicked one will be prevented from continuing to take any share of it.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[14305],"tks":"صحيح: رواه ابن حبان (5213)، وابن السني (460)، والطبراني في الكبير (10354)."},{"num":11167,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَأْكُلُ فِي سِتَّةٍ مِنْ أَصْحَابِهِ فَجَاءَ أَعْرَابِيٌّ جَائِعٌ فَأَكَلَ بِلُقْمَتَيْنِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّهُ لَوْ ذَكَرَ اسْمَ اللَّهِ لَكَفَاكُمْ، فَإِذَا أَكَلَ أَحَدُكُمْ فَلْيَذْكُرْ اسْمَ اللَّهِ، فَإِنْ نَسِيَ أَنْ يُسَمِّيَ اللهَ فِي أَوَّلِهِ، فَلْيَقُلْ بِسْمِ اللَّهِ فِي أَوَّلِهِ وَآخِرِهِ."],"takhrij":"حسن: رواه أبو داود (3767)، والترمذي (1858)، وأحمد (25733) وأحمد (26089)، والنسائي في عمل اليوم والليلة (281) وصحّحه الحاكم (4/108) كلهم من طرق عن هشام بن أبي عبد الله الدستوائي، عن بديل بن ميسرة، عن عبدالله بن عبيد بن عمير، عن امرأة منهم يقال لها: أم كلثوم، عن عائشة فذكرته.","grade":"حسن","chapter_ar":"باب ما يقول من نسي التسمية عند ابتداء الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3767), al-Tirmidhī (1858), Aḥmad (25733, 26089), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (281), and authenticated by al-Ḥākim (4/108).","chapter_en":"What One Should Say If He Forgets to Mention Allah’s Name at the Beginning of a Meal","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah narrated: The Messenger of Allah ﷺ was eating with six of his Companions when a hungry Bedouin arrived and consumed the food in two mouthfuls. The Prophet ﷺ said: “Had he mentioned the name of Allah, the food would have been sufficient for all of you. When one of you eats, let him mention the name of Allah. If he forgets to mention Allah’s name at the beginning, let him say: ‘In the name of Allah at its beginning and its end.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3767)، والترمذي (1858)، وأحمد (25733، 26089)، والنسائي في عمل اليوم والليلة (281)، وصححه الحاكم (4/108)."},{"num":11168,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ اللَّهَ لَيَرْضَى عَنِ الْعَبْدِ أَنْ يَأْكُلَ الْأَكْلَةَ فَيَحْمَدَهُ عَلَيْهَا، أَوْ يَشْرَبَ الشَّرْبَةَ فَيَحْمَدَهُ."],"takhrij":"صحيح: رواه مسلم في الذكر والدعاء (2734) من طرق عن زكريا بن أبي زائدة، عن سعيد بن أبي بردة، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2734).","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik narrated that the Messenger of Allah ﷺ said: “Allah is certainly pleased with a servant who eats a meal and praises Him for it, or drinks a drink and praises Him for it.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2734)."},{"num":11169,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا رَفَعَ مَائِدَتَهُ قَالَ الْحَمْدُ لِلَّهِ كَثِيرًا طَيِّبًا مُبَارَكًا فِيهِ، غَيْرَ مَكْفِيٍّ، وَلاَ مُوَدَّعٍ وَلاَ مُسْتَغْنًى عَنْهُ، رَبَّنَا.","وفي رواية: كَانَ إِذَا فَرَغَ مِنْ طَعَامِهِ -وَقَالَ مَرَّةً: إِذَا رَفَعَ مَائِدَتَهُ- قَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَفَانَا وَأَرْوَانَا غَيْرَ مَكْفِيٍّ وَلاَ مَكْفُورٍ.","وَقَالَ مَرَّةً: الْحَمْدُ لِلَّهِ رَبِّنَا غَيْرَ مَكْفِىٍّ وَلَا مُوَدَّعٍ وَلَا مُسْتَغْنًى رَبَّنَا."],"takhrij":"صحيح: رواه البخاري في الأطعمة (5458) عن أبي نعيم، ثنا سفيان، عن ثور، عن خالد بن معدان، عن أبي أمامة فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5458) with the first wording and by al-Bukhārī (5459) with the second wording.","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Abū Umāmah narrated: When the Prophet ﷺ had his dining spread removed, he would say: “All praise belongs to Allah—abundant, pure, and blessed praise. Our Lord is not one whose favor can be fully repaid, nor one who may be abandoned, nor one whose blessings can ever be dispensed with.” Another narration states that when he finished his food—or on one occasion, when his dining spread was removed—he said: “All praise belongs to Allah, who has sufficed us and quenched our thirst. His favors cannot be fully repaid, nor may they be denied.” On another occasion, he said: “All praise belongs to Allah, our Lord, whose favors cannot be fully repaid, who is never to be abandoned, and whose blessings can never be dispensed with.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5458) باللفظ الأول، ورواه البخاري (5459) باللفظ الثاني."},{"num":11170,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ، عَنْ أَبِيهِ، قَالَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَكَلَ طَعَامًا فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَنِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلاَ قُوَّةٍ. غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ."],"takhrij":"حسن: رواه الترمذي (3458)، وابن ماجه (3285)، وأحمد (15632)، وابن السني (468)، والحاكم (1870) كلهم من طريق سعيد بن أبي أيوب قال: حدثني أبو مرحوم عبد الرحيم بن ميمون، عن سهل بن معاذ بن أنس، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3458), Ibn Mājah (3285), Aḥmad (15632), Ibn al-Sunnī (468), and al-Ḥākim (1870).","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Sahl ibn Muʿādh ibn Anas narrated from his father that the Messenger of Allah ﷺ said: “Whoever eats food and says, ‘All praise belongs to Allah, who fed me this and provided it for me without any power or strength on my part,’ will have his previous sins forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3458)، وابن ماجه (3285)، وأحمد (15632)، وابن السني (468)، والحاكم (1870)."},{"num":11171,"demo":false,"sanad":"","matn":["عَنْ عبدالرحمن بن جُبَيْرٍ، أَنَّهُ حَدَّثَهُ رَجُلٌ خَدَمَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَمَانِ سِنِينَ، أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قُرِّبَ إِلَيْهِ طَعَامُهُ يَقُولُ: بِسْمِ اللَّهِ، وَإِذَا فَرَغَ مِنْ طَعَامِهِ قَالَ: اللهُمَّ أَطْعَمْتَ وَأَسْقَيْتَ، وَأَغْنَيْتَ وَأَقْنَيْتَ، وَهَدَيْتَ وَأَحْيَيْتَ، فَلَكَ الْحَمْدُ عَلَى مَا أَعْطَيْتَ."],"takhrij":"صحيح: رواه أحمد (16595)، والنسائي في الكبرى (6871) كلاهما من طريق سعيد بن أبي أيوب قال: حدثني بكر بن عمرو (هو المعافري)، عن عبد الله بن هبيرة، عن عبد الرحمن بن جبير فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (16595) and al-Nasā’ī in al-Sunan al-Kubrā (6871).","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Jubayr narrated from a man who served the Messenger of Allah ﷺ for eight years: When food was brought near the Prophet ﷺ, he would say: “In the name of Allah.” When he finished eating, he would say: “O Allah, You have fed and given drink, enriched and granted possessions, guided and given life. Therefore, all praise belongs to You for what You have given.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أحمد (16595)، والنسائي في السنن الكبرى (6871)."},{"num":11172,"demo":false,"sanad":"","matn":["عَن أبي هُرَيْرَة قَالَ: دَعَا رجل من الْأَنْصَار من أهل قبَاء النَّبِي صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَانْطَلَقْنَا مَعَه، فَلَمَّا طعم وَغسل يَده أَو يَدَيْهِ قَالَ: الْحَمد لله الَّذِي يطعم وَلَا يطعم، من علينا فهدانا وأطعمنا وَسَقَانَا وكل بلَاء حسن أبلانا، الْحَمد لله غير مُودع وَلَا مكافأ وَلَا مكفور وَلَا مستغني عَنهُ، الْحَمد لله الَّذِي أطْعم من الطَّعَام وَسَقَى من الشَّرَاب، وكسا من العري، وَهدى من الضَّلَالَة وبصر من الْعَمى، وَفضل على كثير من خلقه تَفْضِيلًا، الْحَمد لله رب الْعَالمين."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (301)، وابن السني في في عمل اليوم والليلة (486)، وابن حبان (5219)، والحاكم (2003) كلهم من طريق بشر بن منصور السليمي، عن زهير بن محمد، عن سهيل بن أبي صالح، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (301), Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (486), Ibn Ḥibbān (5219), and al-Ḥākim (2003).","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah narrated: A man from the Anṣār who lived in Qubāʾ invited the Prophet ﷺ, and we went with him. After the Prophet ﷺ had eaten and washed his hand—or both hands—he said: “All praise belongs to Allah, who feeds but is not fed. He bestowed His favor upon us, guided us, fed us, gave us drink, and granted us every good blessing. All praise belongs to Allah, who is never to be abandoned, whose favors can never be adequately repaid, who is never to be denied, and whose blessings can never be dispensed with. All praise belongs to Allah, who provided food to eat and drink to consume, clothed us after nakedness, guided us from misguidance, granted us sight after blindness, and greatly favored us above many of His creatures. All praise belongs to Allah, Lord of the worlds.”"]}},"tuhfa":{},"full":1,"dr":1,"rep":[12303],"tks":"حسن: رواه النسائي في عمل اليوم والليلة (301)، وابن السني في عمل اليوم والليلة (486)، وابن حبان (5219)، والحاكم (2003)."},{"num":11173,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ دَخَلْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا وَخَالِدُ بْنُ الْوَلِيدِ عَلَى مَيْمُونَةَ، فَجَاءَتْنَا بِإِنَاءٍ مِنْ لَبَنٍ، فَشَرِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَا عَلَى يَمِينِهِ، وَخَالِدٌ عَلَى شِمَالِهِ، فَقَالَ لِي: الشَّرْبَةُ لَكَ فَإِنْ شِئْتَ آثَرْتَ بِهَا خَالِدًا. فَقُلْتُ مَا كُنْتُ أُوثِرُ عَلَى سُؤْرِكَ أَحَدًا. ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَطْعَمَهُ اللَّهُ الطَّعَامَ فَلْيَقُلِ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَأَطْعِمْنَا خَيْرًا مِنْهُ. وَمَنْ سَقَاهُ اللَّهُ لَبَنًا فَلْيَقُلِ: اللَّهُمَّ بَارِكْ لَنَا فِيهِ وَزِدْنَا مِنْهُ. وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَيْسَ شَيْءٌ يَجْزِي مَكَانَ الطَّعَامِ وَالشَّرَابِ غَيْرُ اللَّبَنِ."],"takhrij":"حسن: رواه الترمذي (3455- والسياق له-، وأبو داود (3730)، وأحمد (1978)، والنسائي في عمل اليوم والليلة (286، 287)، وابن السني في عمل اليوم والليلة (474) كلهم من طريق علي بن زيد بن جدعان، عن عمر بن حرملة –أو ابن أبي حرملة- عن ابن عباس فذكره.","grade":"حسن","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3455), whose wording is cited here, Abū Dāwūd (3730), Aḥmad (1978), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (286, 287), and Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (474).","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās narrated: Khālid ibn al-Walīd and I entered upon Maymūnah with the Messenger of Allah ﷺ. She brought us a vessel containing milk. The Messenger of Allah ﷺ drank from it. I was seated to his right, while Khālid was to his left. He said to me: “The drink is yours, but you may give preference to Khālid if you wish.” I replied: “I would never give anyone preference over myself regarding what remains from your drink.” The Messenger of Allah ﷺ then said: “When Allah gives someone food, let him say: ‘O Allah, bless it for us and feed us something better than it.’ When Allah gives someone milk to drink, let him say: ‘O Allah, bless it for us and give us more of it.’” The Messenger of Allah ﷺ also said: “Nothing serves as both food and drink except milk.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3455)، والسياق له، وأبو داود (3730)، وأحمد (1978)، والنسائي في عمل اليوم والليلة (286، 287)، وابن السني في عمل اليوم والليلة (474)."},{"num":11174,"demo":false,"sanad":"","matn":["عَنْ أَبِي أَيُّوبَ الأَنْصَارِيِّ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا أَكَلَ أَوْ شَرِبَ قَالَ: الْحَمْدُ لِلَّهِ الَّذِي أَطْعَمَ وَسَقَى، وَسَوَّغَهُ، وَجَعَلَ لَهُ مَخْرَجًا."],"takhrij":"صحيح: رواه أبو داود (3851)، والنسائي في عمل اليوم والليلة (285)، وابن السني (471)، وصحّحه ابن حبان (5220) كلهم من طريق ابن وهب قال: أخبرني سعيد بن أبي أيوب، عن أبي عقيل القرشي (هو: زهرة بن معبد)، عن أبي عبد الرحمن الحبلي، عن أبي أيوب الأنصاري فذكره.","grade":"صحيح","chapter_ar":"باب ما يقول إذا فرغ من طعامه أو شرابه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3851), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (285), Ibn al-Sunnī (471), and authenticated by Ibn Ḥibbān (5220).","chapter_en":"What One Should Say after Finishing Food or Drink","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":3,"content":{"translation":{"en":["Abū Ayyūb al-Anṣārī narrated: When the Messenger of Allah ﷺ ate or drank, he would say: “All praise belongs to Allah, who provided food and drink, made them easy to swallow, and provided a means for their discharge.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3851)، والنسائي في عمل اليوم والليلة (285)، وابن السني (471)، وصححه ابن حبان (5220)."},{"num":11175,"demo":false,"sanad":"","matn":["عَبْدِ اللَّهِ بْنِ مَسْعُودٍ - قَالَ: ضَافَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَيْفًا، فَأَرْسَلَ إِلَى أَزْوَاجِهِ يَبْتَغِي عِنْدَهُنَّ طَعَامًا، فَلَمْ يَجِدْ عِنْدَ وَاحِدَةٍ مِنْهُنَّ، فَقَالَ: اللَّهُمَّ إِنِّي أَسْأَلُكَ مِنْ فَضْلِكَ وَرَحْمَتِكَ، ; فَإِنَّهُ لَا يَمْلِكُهُمَا إِلَّا أَنْتَ. فَأُهْدِيَتْ إِلَيْهِ شَاةٌ مَصْلِيَّةٌ فَقَالَ: هَذِهِ مِنْ فَضْلِ اللَّهِ، وَنَحْنُ نَنْتَظِرُ الرَّحْمَةَ."],"takhrij":"حسن: رواه الطبراني في الكبير (10379) عن عبدان بن أحمد، ثنا محمد بن زياد البرجمي، ثنا عبيد الله بن موسى، ثنا مسعر، عن زبيد، عن مرة، عن عبد الله فذكره.","grade":"حسن","chapter_ar":"باب ما يقول من نزل به ضيف وليس عنده ما يطعمه","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Ṭabarānī in al-Muʿjam al-Kabīr (10/220).","chapter_en":"What One Should Say When a Guest Arrives and He Has Nothing with Which to Feed Him","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd narrated: A guest came to the Prophet ﷺ. He sent to his wives seeking food from them, but none of them had anything. He then said: “O Allah, I ask You from Your bounty and mercy, for none possesses them except You.” A roasted sheep was then presented to him as a gift. He said: “This is from Allah’s bounty, and we are still awaiting His mercy.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الطبراني في الكبير (10379)."},{"num":11176,"demo":false,"sanad":"","matn":["عَنْ عبدالله بْنِ بُسْرٍ قَالَ : نَزَلَ رَسُولُ اللهِ صلى الله عليه وسلم عَلَى أَبِي قَالَ: فَقَرَّبْنَا إِلَيْهِ طَعَامًا وَوَطْبَةً، فَأَكَلَ مِنْهَا، ثُمَّ أُتِيَ بِتَمْرٍ، فَكَانَ يَأْكُلُهُ وَيُلْقِي النَّوَى بَيْنَ إِصْبَعَيْهِ وَيَجْمَعُ السَّبَّابَةَ وَالْوُسْطَى، ثُمَّ أُتِيَ بِشَرَابٍ فَشَرِبَهُ، ثُمَّ نَاوَلَهُ الَّذِي عَنْ يَمِينِهِ قَالَ: فَقَالَ أَبِي وَأَخَذَ بِلِجَامِ دَابَّتِهِ: ادْعُ اللهَ لَنَا فَقَالَ: اللَّهُمَّ بَارِكْ لَهُمْ فِي مَا رَزَقْتَهُمْ وَاغْفِرْ لَهُمْ وَارْحَمْهُمْ."],"takhrij":"صحيح: رواه مسلم في الأشربة (2042) عن محمد بن المثنى العنزي، ثنا محمد بن جعفر، ثنا شعبة، عن يزيد بن خمير، عن عبد الله بن بسر فذكره.","grade":"صحيح","chapter_ar":"باب دعاء الضيف لصاحب الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2042).","chapter_en":"The Guest’s Supplication for the Host","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["ʿAbdullāh ibn Busr narrated: The Messenger of Allah ﷺ stayed as a guest with my father. We brought him food and a preparation made from dates, clarified butter, and cheese, and he ate from it. Dates were then brought to him. He ate them and placed the date-stones between his fingers, joining his index and middle fingers together. A drink was then brought to him. He drank from it and passed it to the person seated on his right. My father took hold of the reins of the riding animal of the Prophet ﷺ and said: “Supplicate to Allah for us.” The Prophet ﷺ said: “O Allah, bless them in what You have provided for them, forgive them, and have mercy upon them.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2042)."},{"num":11177,"demo":false,"sanad":"","matn":["عَنِ الْمِقْدَادِ قَالَ: أَقْبَلْتُ أَنَا وَصَاحِبَانِ لِي، وَقَدْ ذَهَبَتْ أَسْمَاعُنَا وَأَبْصَارُنَا مِنَ الْجَهْدِ...الحديث بطوله.","وفيه قول النبي صلى الله عليه وسلم: اللهم أطعم من أطعمني، واسق من سقاني."],"takhrij":"صحيح: رواه مسلم في الأشربة (2055) عن أبي بكر بن أبي شيبة، ثنا شبابة بن سوار، ثنا سليمان بن المغيرة، عن ثابت، عن عبد الرحمن بن أبي ليلى، عن المقداد (هو ابن الأسود) فذكره.","grade":"صحيح","chapter_ar":"باب دعاء الضيف لصاحب الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2055).","chapter_en":"The Guest’s Supplication for the Host","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Al-Miqdād narrated: Two companions and I arrived in a state of such severe exhaustion that our hearing and sight had been affected. This forms part of a lengthy hadith. Within it, the Prophet ﷺ said: “O Allah, feed the one who feeds me, and give drink to the one who gives me drink.”"]}},"tuhfa":{},"full":1,"tks":"صحيح: رواه مسلم (2055)."},{"num":11178,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ بْنِ مَالِكٍ: أَنَّ البني صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَاءَ إِلَى سَعْدِ بْنِ عُبَادَةَ فَجَاءَ بِخُبْزٍ وَزَيْتٍ، فَأَكَلَ ثُمَّ قَالَ: أَفْطَرَ عِنْدَكُمُ الصَّائِمُونَ، وَأَكَلَ طَعَامَكُمُ الأَبْرَارُ، وَصَلَّتْ عَلَيْكُمُ الْمَلاَئِكَةُ."],"takhrij":"صحيح: رواه أبو داود (3854) عن مخلد بن خالد، حدثنا عبد الرزاق، أخبرنا معمر، عن ثابت عن أنس فذكره.وللحديث أسانيد أخرى، وهذا أصحها.","grade":"صحيح","chapter_ar":"باب دعاء الضيف لصاحب الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (3854).","chapter_en":"The Guest’s Supplication for the Host","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik narrated: The Prophet ﷺ came to Saʿd ibn ʿUbādah, who brought him bread and oil. After eating, the Prophet ﷺ said: “May those who fast break their fast with you, may the righteous eat your food, and may the angels invoke blessings upon you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (3854)."},{"num":11179,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِذَا دُعِيَ أَحَدُكُمْ فَلْيُجِبْ، فَإِنْ كَانَ صَائِمًا فَلْيُصَلِّ، وَإِنْ كَانَ مُفْطِرًا فَلْيَطْعَمْ."],"takhrij":"صحيح: رواه مسلم في النكاح (1431) عن أبي بكر بن أبي شيبة، ثنا حفص بن غياث، عن هشام، عن ابن سيرين، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب دعاء الصائم لصاحب الطعام","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1431).","chapter_en":"The Fasting Person’s Supplication for the Host","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah narrated that the Messenger of Allah ﷺ said: “When one of you is invited, let him accept the invitation. If he is fasting, let him supplicate, and if he is not fasting, let him eat.”"]},"buhuth":{"en":["The words “let him pray” mean that he should supplicate for the host’s forgiveness and blessing. The original linguistic meaning of ṣalāh is supplication."]}},"tuhfa":{},"full":1,"dr":1,"rep":[4416,14445],"tks":"صحيح: رواه مسلم (1431)."},{"num":11180,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا اسْتَجَدَّ ثَوْبًا سَمَّاهُ بِاسْمِهِ إِمَّا قَمِيصًا أَوْ عِمَامَةً ثُمَّ يَقُولُ: اللَّهُمَّ لَكَ الْحَمْدُ أَنْتَ كَسَوْتَنِيهِ أَسْأَلُكَ مِنْ خَيْرِهِ وَخَيْرِ مَا صُنِعَ لَهُ، وَأَعُوذُ بِكَ مِنْ شَرِّهِ وَشَرِّ مَا صُنِعَ لَهُ.","قَالَ أَبُو نَضْرَةَ: فَكَانَ أَصْحَابُ النَّبِيِّ صلى الله عليه وسلم إِذَا لَبِسَ أَحَدُهُمْ ثَوْبًا جَدِيدًا قِيلَ لَهُ: تُبْلِي وَيُخْلِفُ اللَّهُ تَعَالَى."],"takhrij":"حسن: رواه أبو داود (4020)، والترمذي (1767)، والنسائي في عمل اليوم والليلة (309)، وأحمد (11248)، وصحّحه ابن حبان (5420)، والحاكم (7408) كلهم من طرق عن الجريري، عن أبي نضرة، عن أبي سعيد الخدري فذكره.والسياق لأبي داود.","grade":"حسن","chapter_ar":"باب ما يقول إذا لبس ثوبًا جديدًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4020), al-Tirmidhī (1767), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (309), and Aḥmad (11248), and authenticated by Ibn Ḥibbān (5420) and al-Ḥākim (7408).","chapter_en":"What One Should Say When Wearing a New Garment","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":7,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī narrated: Whenever the Messenger of Allah ﷺ acquired a new garment, he would mention it by name—whether it was a shirt or a turban—and then say: “O Allah, all praise belongs to You. You have clothed me with it. I ask You for its good and the good for which it was made, and I seek refuge in You from its evil and the evil for which it was made.” Abū Naḍrah said: When one of the Companions of the Prophet ﷺ wore a new garment, it would be said to him: “May you wear it until it becomes worn, and may Allah replace it for you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4020)، والترمذي (1767)، والنسائي في عمل اليوم والليلة (309)، وأحمد (11248)، وصححه ابن حبان (5420)، والحاكم (7408)."},{"num":11181,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ مُعَاذِ بْنِ أَنَسٍ، عَنْ أَبِيهِ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ لَبِسَ ثَوْبًا، فَقَالَ: الْحَمْدُ لِلَّهِ الَّذِي كَسَانِي هَذَا وَرَزَقَنِيهِ مِنْ غَيْرِ حَوْلٍ مِنِّي وَلَا قُوَّةٍ، غُفِرَ لَهُ مَا تَقَدَّمَ مِنْ ذَنْبِهِ."],"takhrij":"حسن: رواه أبو داود (4023)، والدارمي (2732)، وأبو يعلى (1488)، وابن السني في عمل اليوم والليلة (272) كلهم من حديث أبي عبد الرحمن عبد الله بن يزيد المقرئ، عن سعيد بن أبي أيوب، عن أبي مرحوم عبد الرحيم بن ميمون، عن سهل بن معاذ بن أنس، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما يقول إذا لبس ثوبًا جديدًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4023), al-Dārimī (2732), Abū Yaʿlā (1488), and Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (272).","chapter_en":"What One Should Say When Wearing a New Garment","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":7,"content":{"translation":{"en":["Sahl ibn Muʿādh ibn Anas narrated from his father that the Messenger of Allah ﷺ said: “Whoever puts on a garment and says, ‘All praise belongs to Allah, who clothed me with this and provided it for me without any power or strength on my part,’ will have his previous sins forgiven.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4023)، والدارمي (2732)، وأبو يعلى (1488)، وابن السني في عمل اليوم والليلة (272)."},{"num":11182,"demo":false,"sanad":"","matn":["عَنْ أُمِّ خَالِدٍ بِنْتِ خالد قَالَتْ: أُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِثِيَابٍ فِيهَا خَمِيصَةٌ سَوْدَاءُ قَالَ: مَنْ تَرَوْنَ نَكْسُوهَا هَذِهِ الْخَمِيصَةَ؟ فَأُسْكِتَ الْقَوْمُ قَالَ: ائْتُونِي بِأُمِّ خَالِدٍ فَأُتِيَ بِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فألبسنيها بِيَدِهِ، وَقَالَ: أَبْلِي وَأَخْلِقِي مَرَّتَيْنِ، فَجَعَلَ يَنْظُرُ إِلَى عَلَمِ الْخَمِيصَةِ، وَيُشِيرُ بِيَدِهِ إِلَى وَيَقُولُ: يَا أُمَّ خَالِدٍ هَذَا سَنَا، وَيَا أم خَالِدٍ هَذَا سَنَا، وَالسَّنَا بِلِسَانِ الْحَبَشِيَّةِ الْحَسَنُ.","وفي رواية: أبلي وأخلفي، ثم أبلي وأخلفي، ثم أبلي وأخلفي."],"takhrij":"صحيح: رواه البخاري في اللباس (5845) عن أبي الوليد، حدثنا إسحاق بن سعيد بن عمرو بن سعيد بن العاص قال: حدثني أبي قال: حدثتني أم خالد بنت خالد فذكرته.والرواية الأخرى عند البخاري أيضا في الجهاد والسير (3071) من وجه آخر عن أم خالد.","grade":"صحيح","chapter_ar":"باب ما يقول لصاحبه إذا رأى عليه ثوبًا جديدًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5845). The other wording was narrated by al-Bukhārī (3071).","chapter_en":"What One Should Say to a Companion upon Seeing Him Wearing a New Garment","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الأكل والشرب واللباس","group_en":"Collection of Narrations Concerning Supplications for Eating, Drinking, and Clothing","part_no":54,"group_no":13,"chapter_no":8,"content":{"translation":{"en":["Umm Khālid bint Khālid narrated: Some garments were brought to the Messenger of Allah ﷺ, including a small black cloak. He asked: “Whom do you think we should dress in this cloak?” The people remained silent. He then said: “Bring Umm Khālid to me.” I was brought to the Prophet ﷺ, and he dressed me in it with his own hand. He said twice: “May you wear it until it becomes worn and old.” He began looking at the decorative markings upon the cloak, pointing toward them with his hand and saying: “O Umm Khālid, this is beautiful. O Umm Khālid, this is beautiful.” The word sanā means “beautiful” in the Abyssinian language. Another narration states that he said three times: “May you wear it until it becomes worn, and then receive another in its place.”"]},"buhuth":{"en":["The expression “wear it until it becomes worn and old” is a supplication that the person may live for a long time, until the garment itself becomes worn out.","Al-Ḥāfiẓ explained that the narration using “and may it be replaced” is more meaningful than the narration using “and may it become old.” The latter merely emphasizes that the garment will wear out, whereas the former adds the meaning that once it wears out, it will be replaced with another."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5845). والرواية الأخرى عند البخاري (3071)."},{"num":11183,"demo":false,"sanad":"","matn":["عن ابْنِ عُمَرَ علّمهم أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ إِذَا اسْتَوَى عَلَى بَعِيرِهِ خَارِجًا إِلَى سَفَرٍ، كَبَّرَ ثَلَاثًا، ثُمَّ قَالَ: ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ * وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ﴾ اللَّهُمَّ إِنَّا نَسْأَلُكَ فِي سَفَرِنَا هَذَا الْبِرَّ وَالتَّقْوَى، وَمِنَ الْعَمَلِ مَا تَرْضَى، اللَّهُمَّ هَوِّنْ عَلَيْنَا سَفَرَنَا هَذَا، وَاطْوِ عَنَّا بُعْدَهُ، اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ، وَالْخَلِيفَةُ فِي الْأَهْلِ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمَنْظَرِ وَسُوءِ الْمُنْقَلَبِ فِي الْمَالِ وَالْأَهْلِ، وَإِذَا رَجَعَ قَالَهُنَّ، وَزَادَ فِيهِنَّ: آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ."],"takhrij":"صحيح: رواه مسلم في الحج (1342) عن هارون بن عبدالله، ثنا حجاج بن محمد، قال: قال ابن جريج: أخبرني أبو الزبير أن عليا الأزدي، أخبره أن ابن عمر أخبره فذكره.","grade":"صحيح","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1342).","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿUmar taught them that when the Messenger of Allah ﷺ mounted his camel to set out on a journey, he would proclaim Allah’s greatness three times and then say: “Glory be to the One who subjected this to us, for we could never have controlled it, and indeed, to our Lord we shall return. O Allah, we ask You during this journey of ours for righteousness, mindfulness of You, and deeds with which You are pleased. O Allah, make this journey easy for us and fold up its distance for us. O Allah, You are the Companion during the journey and the Guardian of the family left behind. O Allah, I seek refuge in You from the hardship of travel, from a distressing sight, and from an unpleasant return concerning wealth and family.” When he returned, he would say the same words and add: “We return, repenting, worshipping, and praising our Lord.”"]},"buhuth":{"en":["The word muqrinīn means having the power and ability to control something. The meaning is that we would not have been able to subdue and use it had Allah not subjected it to us."]},"intro":{"ar":["قال اللّٰه تعالى: ﴿وَالَّذِي خَلَقَ الْأَزْوَاجَ كُلَّهَا، وَجَعَلَ لَكُمْ مِنَ الْفُلْكِ وَالْأَنْعَامِ مَا تَرْكَبُونَ ۝ لِتَسْتَوُوا عَلَى ظُهُورِهِ، ثُمَّ تَذْكُرُوا نِعْمَةَ رَبِّكُمْ إِذَا اسْتَوَيْتُمْ عَلَيْهِ، وَتَقُولُوا سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا، وَمَا كُنَّا لَهُ مُقْرِنِينَ﴾ [سورة الزخرف: ١٢-١٣]."],"en":["Allah, the Exalted, said:","“He is the One who created all pairs and made for you ships and livestock upon which you ride, so that you may settle upon their backs and then remember your Lord’s blessing when you have settled upon them and say, ‘Glory be to the One who subjected this to us, for we could never have controlled it.’”","[Sūrat al-Zukhruf 43:12–13]"]}},"tuhfa":{},"full":1,"dr":1,"rep":[13239],"tks":"صحيح: رواه مسلم (1342)."},{"num":11184,"demo":false,"sanad":"","matn":["عَنْ عبدالله بن سَرْجِسَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ يَتَعَوَّذُ مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَالْحَوْرِ بَعْدَ الكون، وَدَعْوَةِ الْمَظْلُومِ، وَسُوءِ الْمَنْظَرِ فِي الْأَهْلِ وَالْمَالِ.","زاد في رواية: يبدأ بالأهل إذا رجع.","وفي لفظ: كَانَ النَّبِىُّ صلى الله عليه وسلم إِذَا سَافَرَ يَقُولُ: اللَّهُمَّ أَنْتَ الصَّاحِبُ فِى السَّفَرِ، وَالْخَلِيفَةُ فِى الأَهْلِ، اللَّهُمَّ اصْحَبْنَا فِى سَفَرِنَا، وَاخْلُفْنَا فِى أَهْلِنَا، اللَّهُمَّ إِنِّى أعوذبك مِنْ وَعْثَاءِ السَّفَرِ، وَكَآبَةِ الْمُنْقَلَبِ، وَمِنَ الْحَوْرِ بَعْدَ الكور، وَمِنْ دَعْوَةِ الْمَظْلُومِ، وَمِنْ سُوءِ الْمَنْظَرِ فِى الأَهْلِ وَالْمَالِ."],"takhrij":"صحيح: رواه مسلم في الحج (1343: 426) عن زهير بن حرب، حدثنا إسماعيل بن علية، عن عاصم الأحول، عن عبد الله بن سرجس فذكره باللفظ الأول.","grade":"صحيح","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1343/426). Ibn Mājah (3888) narrated that he would say the same words when returning. Al-Tirmidhī (3439) narrated the second wording and said:","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Sarjis narrated: When the Messenger of Allah ﷺ traveled, he would seek refuge from the hardship of travel, the distress of an unpleasant return, regression after steadfastness, the supplication of an oppressed person, and an evil sight concerning family and wealth. Another narration adds: “When returning, he would mention the family first.” Another wording states that when the Prophet ﷺ traveled, he would say: “O Allah, You are the Companion during the journey and the Guardian of the family left behind. O Allah, accompany us during our journey and take care of our families in our absence. O Allah, I seek refuge in You from the hardship of travel, the distress of an unpleasant return, regression after steadfastness, the supplication of an oppressed person, and an evil sight concerning family and wealth.”"]},"buhuth":{"en":["“This is a good authentic hadith.”","The expression is narrated both as “regression after being established” and “regression after being wound together.”","Al-Tirmidhī explained that both wordings are meaningful. They refer to returning from faith to disbelief, from obedience to disobedience, or generally from a good condition to an evil one.","Al-Nawawī explained in Sharḥ Muslim that most manuscripts of Ṣaḥīḥ Muslim contain the wording with the letter nūn, meaning “after being established.” This was also the wording preserved by precise transmitters of Ṣaḥīḥ Muslim.","Al-Qāḍī stated that al-Fārisī and other narrators of Ṣaḥīḥ Muslim transmitted it this way, while al-ʿUdhrī narrated the wording with the letter rāʾ, meaning “after being wound together.”","Ibrāhīm al-Ḥarbī claimed that the narrator ʿĀṣim may have erred and that the wording with rāʾ was correct. Al-Nawawī rejected this, explaining that both are established narrations. Al-Tirmidhī, many hadith scholars, Abū ʿUbayd, and numerous linguists mentioned both wordings.","Both convey the meaning of returning from steadfastness or progress to decline and deficiency.","The wording with rāʾ is derived from winding a turban together. It may mean seeking refuge from abandoning unity after having been part of it, or from one’s affairs becoming ruined after having been sound, like a turban unraveling after being properly arranged.","The wording with nūn comes from kawn, meaning existence and stability. Abū ʿUbayd narrated that when ʿĀṣim was asked about it, he said:","“Have you not heard the saying, ‘He declined after he had been established’?”","That is, he had been in a good condition and then turned away from it.","Allah knows best.","The phrase “when he returned, he said the same words” means that he said them when intending to return home from the journey."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1343: 426). ورواه ابن ماجه (3888)، وفيه: فإذا رجع قال مثلها. ورواه الترمذي (3439) باللفظ الثاني، وقال الترمذي: «هذا حديث حسن صحيح»."},{"num":11185,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا سَافَرَ فَرَكِبَ رَاحِلَتَهُ قَالَ بِأُصْبُعِهِ -وَمَدَّ شُعْبَةُ (أحد رواة الحديث) بإصبعه- قَالَ: اللَّهُمَّ أَنْتَ الصَّاحِبُ فِي السَّفَرِ وَالْخَلِيفَةُ فِي الأَهْلِ، اللَّهُمَّ اصْحَبْنَا بِنُصْحِكَ وَاقْلِبْنَا بِذِمَّةٍ، اللَّهُمَّ ازْوِ لَنَا الأَرْضَ، وَهَوِّنْ عَلَيْنَا السَّفَرَ، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ وَعْثَاءِ السَّفَرِ وَكَآبَةِ الْمُنْقَلَبِ."],"takhrij":"حسن: رواه الترمذي (3438)، والنسائي (5501)، وابن السني في عمل اليوم والليلة (499) كلهم من طريق شعبة، عن عبد الله بن بشر الخثعمي، عن أبي زرعة، عن أبي هريرة فذكره. وقال الترمذي: \"هذا حديث حسن غريب من حديث أبي هريرة\".","grade":"حسن","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3438), al-Nasā’ī (5501), and Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (499).","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: When the Messenger of Allah ﷺ traveled and mounted his riding animal, he gestured with his finger—and Shuʿbah, one of the narrators, demonstrated it with his finger—and said: “O Allah, You are the Companion during the journey and the Guardian of the family left behind. O Allah, accompany us with Your protection and return us under Your covenant of safety. O Allah, fold up the earth for us and make the journey easy for us. O Allah, I seek refuge in You from the hardship of travel and the distress of an unpleasant return.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3438)، والنسائي (5501)، وابن السني في عمل اليوم والليلة (499)."},{"num":11186,"demo":false,"sanad":"","matn":["عَنْ أَبِي لَاسٍ الْخُزَاعِيِّ، قَالَ: حَمَلَنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى إِبِلٍ مِنْ إِبِلِ الصَّدَقَةِ لِلْحَجِّ، فَقُلْنَا: يَا رَسُولَ اللَّهِ، مَا نَرَى أَنْ تَحْمِلَنَا هَذِهِ. قَالَ: مَا مِنْ بَعِيرٍ إِلَّا فِي ذُرْوَتِهِ شَيْطَانٌ، فَاذْكُرُوا اسْمَ اللَّهِ عَلَيْهَا إِذَا رَكِبْتُمُوهَا كَمَا أمَرَكم، ثُمَّ امْتَهِنُوهَا لِأَنْفُسِكُمْ فَإِنَّمَا يَحْمِلُ اللهُ."],"takhrij":"حسن: رواه أحمد (17938، 17939)، وصحّحه ابن خزيمة (2377)، والحاكم (1624) كلهم من طريق محمد بن إسحاق، عن محمد بن إبراهيم، عن عمر بن الحكم بن ثوبان، عن أبي لاس الخزاعي فذكره.","grade":"حسن","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17938, 17939), and authenticated by Ibn Khuzaymah (2377) and al-Ḥākim (1624).","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Abū Lās al-Khuzāʿī narrated: The Messenger of Allah ﷺ placed us upon camels from the charity camels so that we could perform Ḥajj. We said: “O Messenger of Allah, we do not think these animals will be able to carry us.” He replied: “There is no camel except that a devil is upon the top of its hump. Therefore, mention Allah’s name over them when you mount them, as I have commanded you, and then make use of them for your needs, for it is Allah, Mighty and Majestic, who truly carries you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (17938، 17939)، وصححه ابن خزيمة (2377)، والحاكم (1624)."},{"num":11187,"demo":false,"sanad":"","matn":["عَنْ حَمْزَةَ بن عمرو الأسلمي قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: عَلَى ظَهْرِ كُلِّ بَعِيرٍ شَيْطَانٌ، فَإِذَا ركبتوها فَسَمُّوا اللهَ عَزَّ وَجَلَّ، ثُمَّ لَا تُقَصِّرُوا عَنْ حَاجَاتِكُمْ."],"takhrij":"حسن: رواه أحمد (16039)، والنسائي في عمل اليوم والليلة (504)، وصحّحه ابن خزيمة (2546)، وابن حبان (1703)، والحاكم (1626) من طرق عن أسامة بن زيد قال: أخبرني محمد بن حمزة بن عمرو الأسلمي أنه سمع أباه يقول فذكره.","grade":"حسن","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (16039), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (504), and authenticated by Ibn Khuzaymah (2546), Ibn Ḥibbān (1703), and al-Ḥākim (1626).","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Ḥamzah ibn ʿAmr al-Aslamī narrated: I heard the Messenger of Allah ﷺ say: “Upon the back of every camel is a devil. Therefore, when you mount them, mention the name of Allah, Mighty and Majestic, and then do not refrain from using them for your needs.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (16039)، والنسائي في عمل اليوم والليلة (504)، وصححه ابن خزيمة (2546)، وابن حبان (1703)، والحاكم (1626)."},{"num":11188,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ عَلَى كُلِّ ذِرْوَةِ بَعِيرٍ شَيْطَانًا، فَامْتَهِنُوهُنَّ بِالرُّكُوبِ، فَإِنَّمَا يَحْمِلُ اللَّهُ."],"takhrij":"حسن: رواه ابن خزيمة في صحيحه (2547)، والحاكم (1627) كلاهما من طريق عبدالله بن وهب، أخبرني ابن أبي الزناد، عن أبيه، عن الأعرج، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Khuzaymah in his Ṣaḥīḥ (2547) and al-Ḥākim (1627).","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["Abū Hurayrah narrated: I heard the Messenger of Allah ﷺ say: “Upon the top of every camel’s hump is a devil. Therefore, make use of them by riding them, for it is Allah who truly carries you.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه ابن خزيمة في صحيحه (2547)، والحاكم (1627)."},{"num":11189,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ رَبِيعَةَ، قَالَ: كُنْتُ رِدْفًا لِعَلِيٍّ، رَضِيَ اللَّهُ عَنْهُ، فَلَمَّا وَضَعَ رِجْلَهُ فِي الرِّكَابِ قَالَ: بِسْمِ اللَّهِ، فَلَمَّا اسْتَوَى عَلَى ظَهْرِ الدَّابَّةِ قَالَ: الْحَمْدُ لِلَّهِ ثَلَاثَ مَرَّاتٍ، اللَّهُ أَكْبَرُ ثَلَاثَ مَرَّاتٍ، ثُمَّ قَالَ: ﴿سُبْحَانَ الَّذِي سَخَّرَ لَنَا هَذَا وَمَا كُنَّا لَهُ مُقْرِنِينَ وَإِنَّا إِلَى رَبِّنَا لَمُنْقَلِبُونَ﴾ [الزخرف: ١٤] ثُمَّ قَالَ: لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي ظَلَمْتُ نَفْسِي فَاغْفِرْ لِي ذُنُوبِي، إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، ثُمَّ ضَحِكَ، فَقُلْتُ: يَا أَمِيرَ الْمُؤْمِنِينَ مَا يُضْحِكُكَ؟ فَقَالَ: كُنْتُ رَدِيفَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَصَنَعَ كَمَا صَنَعْتُ، ثُمَّ قُلْتُ لَهُ كَمَا قُلْتَ لِي، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنَّ اللَّهَ عَزَّ وَجَلَّ لَيَضْحَكُ إِلَى عَبْدِهِ إِذَا قَالَ: ﴿لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي﴾ [سورة الأنبياء: 87] ظَلَمْتُ نَفْسِي، فَاغْفِرْ لِي ذُنُوبِي إِنَّهُ لَا يَغْفِرُ الذُّنُوبَ إِلَّا أَنْتَ، قَالَ: عَبْدِي عَرَفَ أَنِّي أَغْفِرُ وَأُعَاقِبُ."],"takhrij":"حسن: رواه المحاملي في الدعاء (23)، والطبراني في الدعاء (778)، وصحّحه الحاكم (2482) كلهم من طريق فضيل بن مرزوق، عن ميسرة بن حبيب، عن المنهال بن عمرو، عن علي بن ربيعة فذكره.","grade":"حسن","chapter_ar":"باب ما يقوله المسافر إذا ركب للسفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Maḥāmilī in al-Duʿāʾ (23), al-Ṭabarānī in al-Duʿāʾ (778), and authenticated by al-Ḥākim (2482).","chapter_en":"What a Traveler Should Say When Mounting for a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":1,"content":{"translation":{"en":["ʿAlī ibn Rabīʿah narrated: I was riding behind ʿAlī. When he placed his foot into the stirrup, he said: “In the name of Allah.” When he settled upon the animal’s back, he said three times: “All praise belongs to Allah.” Then he said three times: “Allah is the Greatest.” He then recited: “Glory be to the One who subjected this to us, for we could never have controlled it, and indeed, to our Lord we shall return.” He then said: “There is no deity worthy of worship except You. Glory be to You. Indeed, I have wronged myself, so forgive my sins, for none forgives sins except You.” He then laughed. I asked: “O Commander of the Believers, what made you laugh?” He replied: I was riding behind the Messenger of Allah ﷺ, and he did as I have just done. I then asked him the same question that you asked me. The Messenger of Allah ﷺ said: “Allah, Mighty and Majestic, laughs at His servant when he says, ‘There is no deity worthy of worship except You. Glory be to You. Indeed, I have wronged myself, so forgive my sins, for none forgives sins except You.’ Allah says: ‘My servant knows that I forgive and that I punish.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه المحاملي في الدعاء (23)، والطبراني في الدعاء (778)، وصححه الحاكم (2482)."},{"num":11190,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ عُمَرَ: رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَفَلَ مِنْ غَزْوٍ أَوْ حَجٍّ أَوْ عُمْرَةٍ يُكَبِّرُ عَلَى كُلِّ شَرَفٍ مِنَ الأَرْضِ ثَلاَثَ تَكْبِيرَاتٍ، ثُمَّ يَقُولُ: لاَ إِلَهَ إِلاَّ اللَّهُ، وَحْدَهُ لاَ شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهْوَ عَلَى كُلِّ شَىْءٍ قَدِيرٌ، آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا، حَامِدُونَ، صَدَقَ اللَّهُ وَعْدَهُ، وَنَصَرَ عَبْدَهُ، وَهَزَمَ الأَحْزَابَ وَحْدَهُ."],"takhrij":"متفق عليه: رواه مالك في الحج (243) عن نافع، عن عبد الله بن عمر فذكره.ورواه البخاري في الدعوات (6385)، ومسلم في الحج (1344) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما يقول إذا رجع من السفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (243), al-Bukhārī (6385), and Muslim (1344).","chapter_en":"What One Should Say upon Returning from a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["Ibn ʿUmar narrated: Whenever the Messenger of Allah ﷺ returned from a military expedition, Ḥajj, or ʿUmrah, he would proclaim Allah’s greatness three times whenever he ascended a high place and then say: “There is no deity worthy of worship except Allah alone, without partner. To Him belongs all sovereignty and all praise, and He has power over all things. We return, repenting, worshipping, prostrating, and praising our Lord. Allah has fulfilled His promise, granted victory to His servant, and defeated the confederates by Himself.”"]},"buhuth":{"en":["The words “then he would say: ‘There is no deity worthy of worship except Allah…’” mean that he would recite this supplication together with the previously mentioned supplication for mounting:","“Glory be to the One who subjected this to us…”","This is because the narration concerning the supplication for mounting states that when he returned, he would recite the same words and add:","“We return, repenting…”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (243)، والبخاري (6385)، ومسلم (1344)."},{"num":11191,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ أَقْبَلْنَا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَا، وَأَبُو طَلْحَةَ، وَصَفِيَّةُ رَدِيفَتُهُ عَلَى نَاقَتِهِ، حَتَّى إِذَا كُنَّا بِظَهْرِ الْمَدِينَةِ قَالَ: آيِبُونَ، تَائِبُونَ، عَابِدُونَ، لِرَبِّنَا حَامِدُونَ، فَلَمْ يَزَلْ يَقُولُ ذَلِكَ حَتَّى قَدِمْنَا الْمَدِينَةَ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (3085، 3086)، ومسلم في الحج (1345) والسياق له- كلاهما من طريق يحيى بن أبي إسحاق، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقول إذا رجع من السفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3085, 3086) and Muslim (1345). The wording cited here is that of Muslim.","chapter_en":"What One Should Say upon Returning from a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik narrated: We returned with the Prophet ﷺ, accompanied by Abū Ṭalḥah, while Ṣafiyyah was riding behind the Prophet ﷺ upon his she-camel. When we reached the outskirts of Madinah, he said: “We return, repenting, worshipping, and praising our Lord.” He continued repeating these words until we entered Madinah."]}},"tuhfa":{},"full":1,"tks":"متفق عليه: رواه البخاري (3085، 3086)، ومسلم (1345)، والسياق لمسلم."},{"num":11192,"demo":false,"sanad":"","matn":["عن الربيع بن البراء بْنِ عَازِبٍ، يُحَدِّثُ عَنْ أَبِيهِ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ إِذَا قَدِمَ مِنْ سَفَرٍ قَالَ: آيِبُونَ تَائِبُونَ عَابِدُونَ لِرَبِّنَا حَامِدُونَ."],"takhrij":"حسن: رواه الترمذي (3440)، وأحمد (18476)، والنسائي في عمل اليوم والليلة (550)، وصحّحه ابن حبان (2711) كلهم من طرق عن شعبة، عن أبي إسحاق قال: سمعت الربيع بن البراء بن عازب، عن أبيه فذكره.","grade":"حسن","chapter_ar":"باب ما يقول إذا رجع من السفر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3440), Aḥmad (18476), and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (550), and authenticated by Ibn Ḥibbān (2711).","chapter_en":"What One Should Say upon Returning from a Journey","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":2,"content":{"translation":{"en":["Al-Rabīʿ ibn al-Barāʾ ibn ʿĀzib narrated from his father: When the Prophet ﷺ returned from a journey, he would say: “We return, repenting, worshipping, and praising our Lord.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3440)، وأحمد (18476)، والنسائي في عمل اليوم والليلة (550)، وصححه ابن حبان (2711)."},{"num":11193,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ، قَالَ: كُنْتُ رَدِيفَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَعَثَرَتْ دَابَّتُهُ فَقُلْتُ: تَعِسَ الشَّيْطَانُ. فَقَالَ لاَ تَقُلْ تَعِسَ الشَّيْطَانُ؛ فَإِنَّكَ إِذَا قُلْتَ ذَلِكَ تَعَاظَمَ حَتَّى يَكُونَ مِثْلَ الْبَيْتِ وَيَقُولَ: بِقُوَّتِي وَلَكِنْ قُلْ: بِسْمِ اللَّهِ؛ فَإِنَّكَ إِذَا قُلْتَ ذَلِكَ تَصَاغَرَ حَتَّى يَكُونَ مِثْلَ الذُّبَابِ."],"takhrij":"صحيح: رواه أبوداود (4982)، والنسائي في عمل اليوم والليلة (554) كلاهما من طرق عن خالد الحذاء، عن أبي تميمة الهجيمي، عن أبي المليح، عن رديف النبي صلى الله عليه وسلم فذكره.وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما يقول إذا عثرت به دابته","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4982) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (554).","chapter_en":"What One Should Say If His Riding Animal Stumbles","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":3,"content":{"translation":{"en":["A man narrated: I was riding behind the Prophet ﷺ when his animal stumbled, so I said: “May Satan perish!” The Prophet ﷺ said: “Do not say, ‘May Satan perish,’ for when you say that, he grows in pride until he becomes as large as a house and says, ‘It happened through my power.’ Instead, say, ‘In the name of Allah,’ for when you say that, he shrinks until he becomes like a fly.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4982)، والنسائي في عمل اليوم والليلة (554)."},{"num":11194,"demo":false,"sanad":"","matn":["عَنْ قَزَعَةَ قَالَ: أَرْسَلَنِي ابْنُ عُمَرَ فِي حَاجَةٍ فَقَالَ: تَعَالَ حَتَّى أُوَدِّعَكَ كَمَا وَدَّعَنِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَرْسَلَنِي فِي حَاجَةٍ لَهُ، فَقَالَ: أَسْتَوْدِعُ اللهَ دِينَكَ، وَأَمَانَتَكَ، وَخَوَاتِيمَ عَمَلِكَ."],"takhrij":"حسن: رواه أحمد (6199)، والنسائي في عمل اليوم والليلة (512) كلاهما من حديث أبي نعيم، حدثنا عبد العزيز بن عمر بن عبد العزيز، عن يحيى بن إسماعيل بن جرير، عن قزعة فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند توديع المسافر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (6199) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (512).","chapter_en":"What Should Be Said When Bidding Farewell to a Traveler","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Qazaʿah narrated: Ibn ʿUmar sent me to carry out an errand and said: “Come so that I may bid you farewell as the Messenger of Allah ﷺ once bade me farewell when he sent me on an errand.” He then said: “I entrust to Allah your religion, your trusts, and the conclusions of your deeds.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (6199)، والنسائي في عمل اليوم والليلة (512)."},{"num":11195,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ: إِنَّ لُقْمَانَ الْحَكِيمَ كَانَ يَقُولُ: إِنَّ اللَّهَ عَزَّ وَجَلَّ إِذَا اسْتُوْدِعَ شَيْئًا حَفِظَهُ."],"takhrij":"حسن: رواه أحمد (5605-5606)، والنسائي في عمل اليوم والليلة (517-518) كلاهما من طريق سفيان –هو الثوري-، عن نهشل بن مجمع، عن قزعة، عن ابن عمر فذكره.وإسناده حسن من أجل نهشل بن مجمع فإنه حسن الحديث.","grade":"حسن","chapter_ar":"باب ما يقال عند توديع المسافر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (5605–5606) and al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (517–518).","chapter_en":"What Should Be Said When Bidding Farewell to a Traveler","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar narrated: The Messenger of Allah ﷺ informed us that Luqmān the Wise, peace be upon him, used to say: “When Allah, Mighty and Majestic, is entrusted with something, He preserves it.”"]}},"tuhfa":{},"full":1,"tks":"حسن: رواه أحمد (5605-5606)، والنسائي في عمل اليوم والليلة (517-518)."},{"num":11196,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، رَضِيَ اللَّهُ عَنْهُ أَنَّ رَجُلاً، قَالَ: يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ أَنْ أُسَافِرَ فَأَوْصِنِي. قَالَ عَلَيْكَ بِتَقْوَى اللَّهِ، وَالتَّكْبِيرِ عَلَى كُلِّ شَرَفٍ. فَلَمَّا أَنْ وَلَّى الرَّجُلُ قَالَ: اللَّهُمَّ اطْوِ لَهُ الأَرْضَ وَهَوِّنْ عَلَيْهِ السَّفَرَ."],"takhrij":"حسن: رواه الترمذي (3445)، وابن ماجه (2771)، وأحمد (8310)، والنسائي في عمل اليوم والليلة (505)، و ابن خزيمة (2561)، وابن حبان (2692، 2702)، والحاكم (2/98) كلهم من طرق عن أسامة بن زيد، عن سعيد المقبري، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند توديع المسافر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3445), Ibn Mājah (2771), Aḥmad (8310), al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (505), Ibn Khuzaymah (2561), and authenticated by Ibn Ḥibbān (2692, 2702) and al-Ḥākim (2/98).","chapter_en":"What Should Be Said When Bidding Farewell to a Traveler","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah narrated: A man said: “O Messenger of Allah, I intend to travel, so advise me.” He said: “Adhere to mindfulness of Allah and proclaim Allah’s greatness whenever you ascend a high place.” When the man turned to leave, the Prophet ﷺ said: “O Allah, fold up the distance for him and make the journey easy for him.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3445)، وابن ماجه (2771)، وأحمد (8310)، والنسائي في عمل اليوم والليلة (505)، وابن خزيمة (2561)، وابن حبان (2692، 2702)، والحاكم (2/98)."},{"num":11197,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ جَاءَ رَجُلٌ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ إِنِّي أُرِيدُ سَفَرًا فَزَوِّدْنِي. قَالَ: زَوَّدَكَ اللَّهُ التَّقْوَى. قَالَ زِدْنِي. قَالَ وَغَفَرَ ذَنْبَكَ. قَالَ زِدْنِي بِأَبِي أَنْتَ وَأُمِّي. قَالَ وَيَسَّرَ لَكَ الْخَيْرَ حَيْثُمَا كُنْتَ."],"takhrij":"حسن: رواه الترمذي (3444)، وابن السني في عمل اليوم والليلة (503)، وصحّحه ابن خزيمة (2532)، والحاكم (2477) كلهم من طريق سيار بن حاتم، حدثنا جعفر بن سليمان، عن ثابت، عن أنس فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند توديع المسافر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (3444), Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (503), and authenticated by Ibn Khuzaymah (2532) and al-Ḥākim (2477).","chapter_en":"What Should Be Said When Bidding Farewell to a Traveler","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Anas narrated: A man came to the Prophet ﷺ and said: “O Messenger of Allah, I intend to travel, so provide me with provisions.” He said: “May Allah provide you with mindfulness of Him.” The man said: “Give me more.” He said: “And may He forgive your sin.” The man said: “Give me more—may my father and mother be sacrificed for you.” He said: “And may He make goodness easy for you wherever you may be.”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3444)، وابن السني في عمل اليوم والليلة (503)، وصححه ابن خزيمة (2532)، والحاكم (2477)."},{"num":11198,"demo":false,"sanad":"","matn":["عن مُوسَى بن وردان يَقُول: أَتَيْتُ أَبَا هُرَيْرَة أودعهُ فَقَالَ: أَلا أُعَلِّمُكَ يَا ابْن أَخِي شَيْئا علمنيه رَسُول اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أقوله عِنْد الْوَدَاع قُلْتُ: بلَى قَالَ: قل أستودعك الله لَا تضيع ودائعه."],"takhrij":"حسن: رواه النسائي في عمل اليوم والليلة (508) –واللفظ له-، وأحمد (9230)، وابن السني في عمل اليوم والليلة (506) كلهم من طريق عبد الله بن وهب، أخبرني الليث بن سعد وسعيد بن أبي ايوب، عن الحسن بن ثوبان أنه سمع موسى بن وردان فذكره.","grade":"حسن","chapter_ar":"باب ما يقال عند توديع المسافر","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in ʿAmal al-Yawm wa al-Laylah (508), whose wording is cited here, Aḥmad (9230), and Ibn al-Sunnī in ʿAmal al-Yawm wa al-Laylah (506).","chapter_en":"What Should Be Said When Bidding Farewell to a Traveler","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":4,"content":{"translation":{"en":["Mūsā ibn Wardān narrated: I came to Abū Hurayrah to bid him farewell. He said: “My nephew, shall I teach you something that the Messenger of Allah ﷺ taught me to say when bidding farewell?” I replied: “Yes.” He said: “Say: ‘I entrust you to Allah, whose trusts are never lost.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في عمل اليوم والليلة (508)، واللفظ له، وأحمد (9230)، وابن السني في عمل اليوم والليلة (506)."},{"num":11199,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَكُنَّا إِذَا عَلَوْنَا كَبَّرْنَا...الحديث.وَفِي رِوَايَةِ: فَكُنَّا إِذَا أَشْرَفْنَا عَلَى وَادٍ هللنا وَكَبَّرْنَا.","وفي رواية أخرى: فجعل رجل كلما علا ثنية نادى: لا إله إلا الله، والله أكبر."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6384)، ومسلم في الذكر والدعاء (2704) كلاهما من طريق حماد بن زيد، عن أيوب، عن أبي عثمان، عن أبي موسى فذكره.","grade":"متفق عليه","chapter_ar":"باب ما يقوله المسافر إذا علا شرفًا أو نزل واديًا","chapter_ur":"","part_ar":"كتاب الأدعية والأذكار، والصلاة على النبي المختار ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6384) and Muslim (2704). The second narration was recorded by al-Bukhārī (2992).","chapter_en":"What a Traveler Should Say When Ascending a High Place or Descending into a Valley","part_en":"Supplications, Remembrances, and Sending Blessings upon the Chosen Prophet ﷺ","group_ar":"مجموع ما جاء في أدعية الركوب والسفر","group_en":"Collection of Narrations Concerning Supplications for Riding and Travel","part_no":54,"group_no":14,"chapter_no":5,"content":{"translation":{"en":["Abū Mūsā narrated: We were traveling with the Prophet ﷺ, and whenever we ascended, we proclaimed Allah’s greatness. This forms part of the hadith. Another narration states: “Whenever we looked down upon a valley, we declared that there is no deity worthy of worship except Allah and proclaimed His greatness.” Another narration states: “Whenever a man ascended a mountain pass, he would call out: ‘There is no deity worthy of worship except Allah, and Allah is the Greatest.’”"]}},"tuhfa":{},"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6384)، ومسلم (2704). والرواية الثانية عند البخاري (2992)."}]);